// ------------------------------------------------------------------- boot

interface Panel {
  readonly c: ChromeStub;
  readonly dom: PanelDom;
  readonly app: El;
  /** Everything the panel has asked the service for, in order. */
  readonly requests: Request[];
  /** Messages the panel pushed at the worker. */
  readonly pushed: unknown[];
  /** Point the service somewhere else, for what the next screen will fetch. */
  route(table: Table): void;
}

/**
 * Evaluate the shipped `panel.ts` with this service behind it.
 *
 * The import *is* the first render: `panel.ts` ends in a bare `void
 * renderHome()`, so there is no seam to call and no way to observe the panel
 * before it has already asked for the board. That is the shipped shape and the
 * tests take it as given.
 */
async function open(
  t: TestContext, table: Table, listening = true, store: Record<string, unknown> = {},
  browser: Omit<ChromeStubOptions, 'store'> = {}, routeHash?: string, demoEntry = false,
): Promise<Panel> {
  // `store` is what `chrome.storage.local` already holds when the panel opens.
  // Empty for every screen but one: SB-59's hand-off is the only thing the
  // panel reads out of storage, and it decides which screen this even is.
  //
  // `browser` is the rest of the ambient surface — a clipboard that refuses, a
  // tab that will not open — which UX_SPEC §5d's seam has to have an answer for.
  const c = installChrome({ store, ...browser });
  // A hand-off is a panel thing by construction: the main page never draws
  // somebody's pending take and never consumes it. So a test that seeds one is
  // a test about the panel, and one that does not is a test about the page.
  const dom = installPanelDom(
    HANDOFF_KEY in store ? 'panel' : 'page', routeHash, browser.tabsFail ?? false,
  );
  const ambient = globalThis as typeof globalThis & {
    __VIRGIL_WEB_CONFIG__?: { readonly judgeDemoEnabled?: boolean };
  };
  if (demoEntry) {
    (globalThis.location as Location & { search: string }).search = '?judge=1';
    ambient.__VIRGIL_WEB_CONFIG__ = { judgeDemoEnabled: true };
  }
  t.after(() => {
    delete ambient.__VIRGIL_WEB_CONFIG__;
    c.uninstall();
    dom.uninstall();
  });
  c.fetchHandler = serve(table);

  const pushed: unknown[] = [];
  if (listening) {
    // The worker's half of the PREFS_CHANGED contract, standing in for
    // `background.ts` — which is tested separately against the same message.
    const runtime = (globalThis as unknown as { chrome: { runtime: { onMessage: { addListener(fn: (m: unknown) => boolean) : void } } } }).chrome.runtime;
    runtime.onMessage.addListener((m: unknown) => { pushed.push(m); return false; });
  }

  clearLessonMemory();
  await freshImport('../panel.js');
  await settle();
  return {
    c, dom, app: dom.app, requests: c.requests, pushed,
    route: (next: Table) => { c.fetchHandler = serve(next); },
  };
}

const paths = (p: Panel): string[] => p.requests.map((r) => `${r.method} ${r.url.slice(SERVICE.length)}`);

/**
 * What drawing the main page costs, in requests.
 *
 * One per zone, and named so the several tests that count requests after a
 * click do not each carry a hard-coded 2. The important property is not the
 * number: it is that the number does not grow with the board.
 */
/**
 * What arriving costs, as of 2026-08-23.
 *
 * The board stopped being the arrival page when the study-buddy capabilities
 * arrived, and this list is the evidence that the change made the front door
 * CHEAPER rather than more expensive: no `/board`, no `/flagged`, no `/batch`
 * on the way in. The board pays for those when somebody opens it.
 *
 * Cheaper again on 2026-08-24. `/plan` and `/burst` were read for a due strip
 * and a five-minute offer drawn in a branch that ran only when `/today` was
 * missing, which no live service has ever been. Both facts are inside
 * `/today`'s own answer — what is due is a commitment candidate, five minutes
 * is the burst candidate — so the two reads fetched the same information a
 * second time and drew it nowhere.
 */
const FIRST_PAINT = [
  'GET /session', 'GET /prefs', 'GET /today', 'GET /progression',
];

/** And what the board room costs, which is what the front door used to. */
/**
 * And what showing the board FACE costs, on top of arriving at Learn.
 *
 * The board stopped being a room on 2026-08-25 and became Learn's second face.
 * It lost its own `/prefs` read with the move: the paused banner is drawn by
 * the room, once, above both faces, and the face was asking for the same
 * preferences a second time to draw a second copy of it.
 */
/**
 * `/prospects` joined the list on 2026-08-29 and is the strip's business rather
 * than the board's: the foot of the board says what is waiting, and proposals
 * nobody has answered are waiting. It is one read for the whole face, it does
 * not grow with the board, and a service too old to answer it changes nothing.
 */
const BOARD_PAINT = [
  'GET /board', 'GET /session', 'GET /flagged', 'GET /prospects', 'GET /batch',
  'GET /model-config', 'GET /plan',
];
/**
 * The last thing the panel SENT.
 *
 * It used to be the last request of any kind, which held while every screen's
 * final act was its write. The board now asks `/batch` after a redraw, so the
 * last request became a GET carrying no body and three merge tests started
 * asserting against `null`. A GET sends nothing, so it can never be the answer
 * to "what did we send".
 */
const lastWrite = (p: Panel): Request | undefined =>
  [...p.requests].reverse().find((r) => (r.method ?? 'GET') !== 'GET');
const lastBody = (p: Panel): unknown => lastWrite(p)?.body;

// =============================================================== first paint

test('the panel asks for the board and the session, and nothing else, to draw its first screen', async (t) => {
  const p = await open(t, home());
  // Five now — one per zone plus the paused state (the collection-pause contract) — and still
  // nothing per pin or per topic. The point of the assertion is not the number:
  // it is that the first screen's cost does not grow with the board, which is
  // the same promise the flat nightly call count makes.
  assert.deepEqual(paths(p), FIRST_PAINT);
});

test('every request the first paint makes carries the shared secret, when one is set', async (t) => {
  /**
   * The exposed-service authentication boundary's other half of the extension. The panel is five requests before
   * it has drawn anything, and the private service answers 401 to all of them
   * without the header — which `api()` turns into `null`, which every zone
   * renders as its empty state. A panel that quietly showed "nothing ready yet"
   * on a healthy board is the failure this asserts against.
   */
  const p = await open(t, home(), true, { [SHARED_SECRET_KEY]: SECRET });
  assert.deepEqual(paths(p), FIRST_PAINT, 'all five zones were asked');
  for (const r of p.requests) {
    assert.equal(r.headers[SHARED_SECRET_HEADER], SECRET, `${r.method} ${r.url} went without the secret`);
    assert.equal(r.headers[TIME_ZONE_HEADER], Intl.DateTimeFormat().resolvedOptions().timeZone,
      `${r.method} ${r.url} went without the learner's calendar zone`);
    assert.equal(r.headers[CLIENT_SCHEMA_HEADER], String(CLIENT_SCHEMA_VERSION),
      `${r.method} ${r.url} went without the extension compatibility receipt`);
  }
});


/** What the hero says on the clock this test run is happening on. The mapping
 *  is `panel-view.test.ts`'s; every screen that merely passes through the
 *  lineup asserts the heading it would get now, rather than a fixed evening. */
const lineupNow = (): string => lineupHeading(new Date().getHours());

const atHour = (t: TestContext, hour: number): void => {
  const real = Date.prototype.getHours;
  Date.prototype.getHours = function pinned(this: Date): number { return hour; };
  t.after(() => { Date.prototype.getHours = real; });
};

test('the lineup heading follows the learner’s own clock, not the run’s', async (t) => {
  atHour(t, 9);
  const morning = await open(t, home());
  assert.equal(text(find(morning.app, '.next-action h1')), 'This morning’s lineup');

  atHour(t, 14);
  const afternoon = await open(t, home());
  assert.equal(text(find(afternoon.app, '.next-action h1')), 'This afternoon’s lineup');

  atHour(t, 21);
  const evening = await open(t, home());
  assert.equal(text(find(evening.app, '.next-action h1')), 'Tonight’s lineup');
});

test('only the lineup heading is reworded: another kind of next move keeps its own title', async (t) => {
  atHour(t, 9);
  const p = await open(t, home({ 'GET /today': { next: NEXT_QUICK } }));
  assert.equal(text(find(p.app, '.next-action h1')), 'A quick take on TLS');
});

test('a panel with no secret set sends no header, and the local service is unchanged', async (t) => {
  const p = await open(t, home());
  for (const r of p.requests) assert.equal(SHARED_SECRET_HEADER in r.headers, false);
});

test('the loading class the page ships with is cleared once the panel owns the screen', async (t) => {
  const p = await open(t, home());
  // panel.html paints `class="loading"` before any script runs, and every render
  // entry point clears it. A panel that left it on would look permanently busy.
  // Not `className === ''`: the front door names itself `home`, because it is
  // the one screen the stylesheet gives the full width of the window to. What
  // must be gone is the loading class, and that is what is asserted.
  assert.ok(!p.app.className.split(/\s+/).includes('loading'));
  assert.ok(!text(p.app).includes('Loading…'));
});

test('one ready session is offered, and the board is not a backlog behind it', async (t) => {
  const p = await open(t, home());
  /**
   * SB-18, and still the single most load-bearing assertion in this file —
   * restated for one screen now that the board-as-page layout contract collapsed the arrival page into
   * the board.
   *
   * What it protected was never "no cards anywhere". It was: **exactly one
   * thing to start, and this is not a backlog to clear.** The board being on
   * the same page does not change that; the board is the learner's own work,
   * and it is asserted below that nothing on it is counted as a debt.
   */
  assert.equal(p.app.querySelectorAll('.next-action').length, 1, 'exactly one thing is offered');
  assert.equal(p.app.querySelectorAll('button').filter((b) => text(b) === 'Start').length, 1);
  assert.equal(p.app.querySelectorAll('.section').length, 0, 'and no list of sessions');
  // The part that would mean the product had failed.
  assert.ok(!/left to|remaining|to clear|unread|overdue|behind/i.test(text(p.app)), text(p.app).slice(0, 200));
  // One hero, and it is the session, because there is one. There is no second
  // card about the same lesson under it: the zone that used to draw one was
  // reachable only through a branch for a service that predates `/today`.
  assert.equal(p.app.querySelectorAll('[data-zone=session]').length, 0);
  assert.equal(text(find(p.app, '.next-action h1')), lineupNow());
  assert.equal(text(button(p.app, 'Start')), 'Start');

  await clickButton(p.app, 'Start');
  assert.equal(p.app.dataset.room, 'today');
  assert.equal(p.app.querySelectorAll('.room-main .section').length, 1);
});

/**
 * SB-279: THE ARRIVAL SCREEN IS THE FRONT DOOR.
 *
 * The empty board used to be one verb under one sentence, and it taught a
 * person that this product wants a syllabus. It takes three kinds of thing,
 * and this is the screen where saying so is worth the most: nobody has given
 * it anything yet, so what it says it accepts IS what it is.
 */
test('a first-run board names every way in without inventing a lesson or an estimate', async (t) => {
  const p = await open(t, home({
    'GET /session': { session: null, card: null, upcoming: [] },
    'GET /today': { next: NEXT_EMPTY },
  }));
  const rail = find(p.app, '.room-rail');

  assert.equal(rail.querySelector('.rail-kicker'), null,
    'the learner\'s available time was presented as the cost of work that does not exist');
  assert.equal(rail.querySelector('[data-rail-empty]'), null,
    'the after-session empty state was reused before a session existed');

  // The hero sells the product rather than one intake.
  assert.equal(text(find(p.app, '.next-action h1')), 'Collect anything. Virgil finds your next move.');
  assert.match(text(find(p.app, '.next-action')), /a course, an assignment, a page that taught you something/);
  assert.equal(find(p.app, '.masthead').getAttribute('data-guide-target'), 'top');
  assert.equal(find(p.app, '.room-columns').getAttribute('data-guide-target'), 'learn-surface');
  assert.equal(find(p.app, '.next-action').getAttribute('data-guide-target'), 'current-priority');

  const ways = find(rail, '[data-rail-ways]');
  assert.equal(text(find(ways, '.alt-label')), 'Ways to add');
  assert.deepEqual(
    ways.querySelectorAll('[data-way] .what').map((node) => text(node)),
    ['A course', 'Your own work', 'The web, as you browse'],
  );
  assert.match(text(ways), /Virgil drafts the plan; you review every line before it counts/);
  assert.match(text(ways), /the minutes you actually have/);
  assert.match(text(ways), /one pin away/);
  assert.doesNotMatch(text(rail), /tonight|expected time|overnight/i);

  // Two rows have a room behind them and are buttons, which is what makes them
  // reachable by tab and announced as controls. The third has nowhere on this
  // page to go, so it is not dressed as a control that does nothing.
  assert.deepEqual(
    ways.querySelectorAll('[data-way]').map((node) => node.tagName.toLowerCase()),
    ['button', 'button', 'div'],
  );
  assert.equal(find(p.app, '.room-columns').getAttribute('data-rail'), 'empty');
  assert.equal(text(button(p.app, 'Add course material')), 'Add course material');
});

