test('the hero carries what the session card knows and `/today` does not', async (t) => {
  /**
   * The registers in their three colours were drawn in a zone under the hero,
   * and that zone was unreachable. They belong on the card that IS the session.
   *
   * The learner-controlled lineup contract moved them one step further: the level is a fact about a
   * SECTION, so it is drawn on the row it is about rather than as a strip
   * summarising the evening. The session-wide strip survives only where there
   * is no lineup to replace it, which the test below covers.
   */
  const p = await open(t, home({
    'GET /session': {
      session: session({
        sections: [
          section({ depth: 'from-nothing' }),
          section({ topicId: 't2', heading: 'Why forward secrecy', depth: 'fluent', question: null }),
        ],
      }),
      card: card({ registers: ['from-nothing', 'fluent'], why: 'TLS is due for a check' }),
    },
  }));
  const hero = find(p.app, '.next-action');
  assert.deepEqual(hero.querySelectorAll('.lineup-item .register').map((r) => text(r)),
    ['new to you', 'fluent'], 'the level is shown per row, on the thing it is about');
  // The build line left this screen: a timestamp is a fact about a pipeline,
  // and the pin count is per lesson now, behind the row's own disclosure.
  assert.equal(hero.querySelectorAll('.built').length, 0);

  assert.equal(hero.querySelectorAll('.eyebrow').length, 0);
  assert.equal(text(find(p.app, '.room-rail .rail-kicker')), 'Expected time · 10 min');
});

test('a session with nothing left to line up falls back to the card the hero always had', async (t) => {
  /**
   * The lineup is what the learner is ABOUT to do. A session whose sections are
   * all done has none, so the strip and the night-wide why-line are still the
   * honest summary and are still drawn.
   */
  const p = await open(t, home({
    'GET /session': {
      session: session({ sections: [section({ completed: true })], currentSectionIndex: 1 }),
      card: card({ registers: ['building'], why: 'TLS: due for a check' }),
    },
  }));
  const hero = find(p.app, '.next-action');
  assert.equal(hero.querySelectorAll('.lineup').length, 0);
  assert.deepEqual(hero.querySelectorAll('.register').map((r) => text(r)), ['building']);
  assert.ok(hero.querySelectorAll('.why').map((w) => text(w)).includes('TLS: due for a check'));
});

// =============================================== The learner-controlled lineup contract: tonight's lineup


/** Three rows, each with a level, a length and a stored reason. */
const lined = (over: Table = {}): Table => home({
  'GET /session': {
    session: session({
      sections: [
        section({ topicId: 't1', heading: 'How TLS gets its keys', depth: 'from-nothing', estimatedMinutes: 6, why: 'nothing has been asked about this yet' }),
        section({ topicId: 't2', heading: 'Why forward secrecy', depth: 'building', estimatedMinutes: 4, question: null, why: 'you have been struggling with this' }),
        section({ topicId: 't3', heading: 'Certificate pinning', depth: 'fluent', estimatedMinutes: 5, question: null, why: 'due a quick check so it stays put' }),
      ],
    }),
    card: card(),
  },
  ...over,
});

const rows = (p: Panel): El[] => p.app.querySelectorAll('.lineup-item');


const iconControl = (root: El, label: string): El => {
  const found = root.querySelectorAll('button')
    .find((b) => b.getAttribute('aria-label') === label);
  assert.ok(found, `no lineup control is labelled "${label}"`);
  return found;
};

const pressIcon = async (root: El, label: string): Promise<void> => click(iconControl(root, label));

test('the hero shows what is lined up: the subject, the level and the minutes, in order', async (t) => {
  const p = await open(t, lined());
  const list = rows(p);
  assert.equal(list.length, 3, 'one row per section still to do');
  assert.deepEqual(list.map((r) => text(find(r, '.lineup-open'))),
    ['How TLS gets its keys', 'Why forward secrecy', 'Certificate pinning']);
  assert.deepEqual(list.map((r) => text(find(r, '.register'))),
    ['new to you', 'building', 'fluent']);
  assert.deepEqual(list.map((r) => text(find(r, '.lineup-minutes'))),
    ['6 min', '4 min', '5 min']);
  // No heading over the list and no total under it: the hero's one surviving
  // line computes the time against the chip, and the list leads.
  assert.equal(p.app.querySelectorAll('.lineup-total').length, 0);
  assert.equal(p.app.querySelectorAll('.lineup-heading').length, 0);
  // Drawing the lineup costs nothing: it is the session the panel already read.
  assert.deepEqual(paths(p), FIRST_PAINT);
});


test('pressing a lesson opens the session at that lesson', async (t) => {
  const p = await open(t, lined());
  await clickButton(rows(p)[2]!, 'Certificate pinning');
  assert.equal(p.app.dataset.room, 'today', 'a lesson is not a different page');
  /**
   * It used to be marked and scrolled to, because arriving in the middle of a
   * stacked session with no indication of why was worse than arriving at the
   * top. There is no middle now: the lesson pressed is the only lesson on
   * screen, so being there IS the indication.
   */
  const landed = find(p.app, '.room-main .section');
  assert.equal(landed.getAttribute('data-section'), 't3');
  assert.equal(text(find(landed, '.lesson-area')), 'Certificate pinning');
  assert.equal(p.app.querySelectorAll('.room-main .section').length, 1);
});

test('pressing a lesson writes no progress, because pressing a heading is not doing the work', async (t) => {
  const p = await open(t, lined());
  const before = p.requests.length;
  await clickButton(rows(p)[2]!, 'Certificate pinning');
  // The room is drawn from the session the panel already holds. Nothing is
  // marked done, no index is written, and the resume point is untouched: it is
  // a record of what the learner finished, not of what they looked at.
  assert.deepEqual(p.requests.slice(before).filter((r) => (r.method ?? 'GET') !== 'GET'), []);
  assert.equal(p.app.querySelectorAll('.section.done').length, 0);
});

test('the subject sits beside the minutes and opens My studies at that course', async (t) => {
  const p = await open(t, lined({
    'GET /session': {
      session: session({
        sections: [section({
          topicId: 't1', heading: 'How TLS gets its keys',
          subject: { courseId: 'c-net', title: 'Networks and Security' },
        })],
      }),
      card: card(),
    },
    'GET /courses': { courses: [], drafts: [] },
  }));
  const row = rows(p)[0]!;
  // Next to the time, which is where the ruling puts it: the two facts a
  // learner scans a lineup on are how long it is and what it is part of.
  const line = find(row, '.lineup-what').children.map((c) => c.className);
  assert.ok(line.findIndex((c) => c.includes('lineup-course'))
    > line.findIndex((c) => c.includes('lineup-minutes')),
    `the subject is not beside the time: ${line.join(' | ')}`);
  assert.equal(text(find(row, '.lineup-course')), 'Networks and Security');
  await click(find(row, '.lineup-course'));
  assert.equal(p.app.dataset.room, 'courses');
});

