test('a slow room cannot finish painting into the room opened after it', async (t) => {
  const routes = everyRoom();
  const p = await open(t, routes);
  const immediate = serve(routes);
  let releasePlan!: (response: FakeResponse) => void;
  const delayedPlan = new Promise<FakeResponse>((resolve) => { releasePlan = resolve; });

  p.c.fetchHandler = (url, init) => {
    const path = url.startsWith(SERVICE) ? url.slice(SERVICE.length) : url;
    if (`${init?.method ?? 'GET'} ${path}` === 'GET /plan') return delayedPlan;
    return immediate(url, init);
  };

  await clickButton(p.app, 'Plan');
  assert.equal(p.app.dataset.room, 'plan');
  await clickButton(p.app, 'My studies');
  assert.equal(p.app.dataset.room, 'courses');
  assert.equal(text(find(p.app, 'h1')), 'My studies');

  releasePlan(jsonResponse({
    commitments: [], points: 0, stars: 0, towardNextStar: 0, recentAwards: [],
  }));
  await settle();

  assert.equal(p.app.dataset.room, 'courses');
  assert.equal(text(find(p.app, 'h1')), 'My studies');
  assert.equal(p.app.querySelector('.plan-wall'), null,
    'the late Plan continuation appended its wall into My studies');
  assert.equal(p.app.querySelector('.plan-done'), null,
    'the late Plan continuation appended its finished lane into My studies');
});


