test('"Got it" does not move on when the mark never landed', async (t) => {
  const p = await open(t, home({ 'POST /sessions/sess-1/sections/t1/skip': DOWN }));
  await startSession(p);
  const sessionReads = () => paths(p).filter((path) => path === 'GET /session').length;
  const before = sessionReads();
  await clickButton(find(p.app, '.section'), 'Got it');
  assert.equal(text(find(p.app, '.section .lesson-area')), 'How TLS gets its keys');
  assert.equal(sessionReads(), before, 'a failed mark was followed by a read and treated like progress');
  assert.equal(text(find(p.app, '.lesson-said')), "That didn't go through. Nothing changed.");
  assert.equal(button(find(p.app, '.section'), 'Got it').disabled, false);
});

