/** Two done, two to go, and the store's index agreeing with the flags. */
const halfDone = (over: RawSection = {}): Table => home({
  // `/today` names the cta, so a session part way through says Continue there
  // as well. The two used to be decided in two places and could disagree.
  'GET /today': {
    next: {
      ...NEXT_SESSION,
      primary: { ...NEXT_SESSION.primary, cta: 'Continue', detail: 'Here is what you will cover, in order.' },
    },
  },
  'GET /session': {
    session: session({
      sections: [
        section({ topicId: 't1', heading: 'How TLS gets its keys', completed: true }),
        section({ topicId: 't2', heading: 'Why forward secrecy', completed: true, question: null }),
        section({ topicId: 't3', heading: 'IAM conditions', question: null }),
        section({ topicId: 't4', heading: 'Certificate pinning', question: null }),
      ],
      currentSectionIndex: 2,
      ...over,
    }),
    card: card(),
  },
});

test('SB-31: a resumed session opens at the section the learner stopped on', async (t) => {
  // The index has been written by the service since SB-31 was built and read by
  // nothing: every section was drawn identically, so "continue" reopened the
  // whole session at the top and the first half was there to be done again.
  const p = await open(t, halfDone());
  await clickButton(p.app, 'Continue');

  const resume = find(p.app, '[data-resume]');
  assert.equal(text(find(resume, '.lesson-area')), 'IAM conditions');
});

test('SB-31: the lessons already done are still reachable, and are not offered again', async (t) => {
  /**
   * SB-31's rule is that a resumed session must not DISCARD what was done, and
   * it holds through the one-lesson change — what moved is where the done ones
   * live. They are the rail's second list, pressable, so the learner can see
   * what they did and re-read it. Stacking them above the lesson they are meant
   * to be doing was never what the rule asked for.
   */
  const p = await open(t, halfDone());
  await clickButton(p.app, 'Continue');

  assert.deepEqual(p.app.querySelectorAll('.section .lesson-area').map((h) => text(h)),
    ['IAM conditions'], 'one lesson, and it is the one they stopped on');
  const rail = find(p.app, '.room-rail');
  assert.deepEqual(rail.querySelectorAll('[data-list="done"] .rail-name').map((n) => text(n)),
    ['How TLS gets its keys', 'Why forward secrecy']);
  assert.deepEqual(rail.querySelectorAll('[data-list="next"] .rail-name').map((n) => text(n)),
    ['Certificate pinning']);

  // And re-reading one offers nothing that writes. Every control on a lesson
  // records a signal, and a second answer to a question already answered is a
  // duplicate rather than a second reading of anybody's comfort.
  await clickButton(rail, 'How TLS gets its keys');
  const done = find(p.app, '.section.done');
  assert.equal(done.querySelectorAll('.controls').length, 0);
  assert.equal(done.querySelectorAll('.q').length, 0, 'its question is not asked again');
  // The one exception, and it is the exception on purpose: checking where a
  // claim came from writes nothing (SB-44), and scepticism about something
  // already read is exactly when a learner reaches for it.
  assert.equal(done.querySelectorAll('.sources').length, 1);
  assert.equal(done.querySelectorAll('.lesson-correction').length, 1,
    'a completed lesson became impossible to correct after the learner had time to check it');
});

test('SB-31: a completed lesson remains full-contrast when it is re-read', () => {
  const css = readFileSync(fileURLToPath(new URL('../../panel.css', import.meta.url)), 'utf8');
  assert.match(css, /\.section\.done\s*\{[^}]*opacity:\s*1\s*;/,
    'completion dimmed the title, prose and sources the learner came back to read');
  assert.doesNotMatch(css, /\.section\.done\s*\{[^}]*opacity:\s*0?\.[0-9]+/,
    'a completed lesson inherits reduced contrast from its section');
});

