// ----------------------------------------------- the taught claim (SB-45)

const checkedCorrection = {
  id: 'correction-1', clientRef: 'browser-correction-1',
  claim: 'The handshake picks a key.',
  challenge: 'The source says it derives a fresh session key.',
  reply: 'You are right. The handshake derives a fresh session key; it does not reuse the certificate key.',
  conceded: true, sourceIds: ['p1'], withdrawn: 2, at: '2026-08-27T00:00:00Z',
};

const challengeLesson = async (p: Panel, words: string): Promise<El> => {
  const correction = find(p.app, '.lesson-correction');
  await typeInto(find(correction, 'textarea'), words);
  await clickButton(correction, 'Check the cited source');
  return correction;
};

test('SB-45: the learner can challenge ordinary teaching and read a graceful concession', async (t) => {
  const p = await open(t, home({
    'POST /sessions/sess-1/sections/t1/correction': {
      correction: checkedCorrection,
      section: section({
        heading: 'TLS session keys', body: checkedCorrection.reply,
        summary: null, question: null, estimatedMinutes: 1,
      }),
    },
    'GET /sessions/sess-1/sections/t1/sources': {
      sources: [{
        id: 'p1', origin: 'user-pin', title: 'TLS guide', url: 'https://example.com/tls',
        at: '2026-08-20T00:00:00Z', moment: null, page: null,
        readByVirgil: true, excerpt: 'A fresh session key is derived.',
      }], unresolved: 0,
    },
  }));
  await startSession(p);
  const correction = await challengeLesson(p, checkedCorrection.challenge);
  const req = lastWrite(p)!;
  assert.equal(req.url, `${SERVICE}/sessions/sess-1/sections/t1/correction`);
  assert.equal(req.method, 'POST');
  assert.equal((req.body as Record<string, unknown>).challenge, checkedCorrection.challenge);
  assert.equal(typeof (req.body as Record<string, unknown>).clientRef, 'string');
  assert.match(text(find(correction, '.turn.virgil .what')), /fresh session key/);
  assert.equal(text(find(correction, '.receipt')),
    'I got this wrong. 2 learning marks from this lesson no longer count. You do not have to repeat it; the corrected lesson stays here.');
  assert.match(text(find(p.app, '.section .body')), /fresh session key/,
    'the known-wrong lesson stayed current above the concession');
  assert.equal(text(find(p.app, '.section .lesson-area')), 'TLS session keys');
  assert.equal(p.app.querySelectorAll('.section .q').length, 0,
    'the mounted lesson kept asking the question written from the conceded claim');
  assert.equal(p.dom.activeElement, find(correction, '.turn.virgil'));
  await clickButton(correction, 'See cited sources');
  assert.ok(paths(p).some((path) => path.endsWith('/sections/t1/sources')));
  assert.match(text(find(p.app, '.sources-out')), /TLS guide/);
});

