test('SB-140: finishing a session becomes caught up and returns to the same board', async (t) => {
  const initial = session({
    sections: [
      section(),
      section({ topicId: 't2', heading: 'Why forward secrecy' }),
    ],
  });
  const p = await open(t, home({
    'GET /session': { session: initial, card: card() },
    'POST /sessions/sess-1/sections/t1/answer': {
      response: 'That is the shape of it.', signal: 'answer-right',
    },
    'POST /sessions/sess-1/sections/t2/answer': {
      response: 'That is why the old key cannot decrypt the later session.', signal: 'answer-right',
    },
  }));

  await startSession(p);
  await answerFirst(p, 'They agree a temporary key and discard it afterwards.');
  await clickButton(find(p.app, '.room-rail'), 'Next lesson');
  assert.deepEqual(
    find(p.app, '.room-rail').querySelectorAll('[data-list="done"] .rail-name').map((n) => text(n)),
    ['How TLS gets its keys'],
  );
  assert.equal(text(find(p.app, '[data-done-label]')), 'Already done');

  await answerFirst(p, 'A discarded session key is not available to decrypt a later capture.');
  const complete = session({
    currentSectionIndex: 2,
    sections: [
      section({ completed: true, completionEvidence: 'answer' }),
      section({ topicId: 't2', heading: 'Why forward secrecy', completed: true,
        completionEvidence: 'answer' }),
    ],
  });
  p.route(home({
    'GET /session': { session: complete, card: card({ minutes: 0 }) },
    'GET /today': { next: NEXT_CAUGHT_UP },
    'GET /board': {
      topics: [topic('t1', 'TLS key agreement'), topic('t2', 'Forward secrecy')], suggestions: [],
    },
    'GET /sessions/sess-1/awards': { awards: [] },
  }));

  await clickButton(find(p.app, '.room-rail'), 'Finish');
  assert.equal(text(find(p.app, '.closing')),
    'Virgil saved new learning evidence from each lesson. It can use that when choosing what comes next.');
  assert.ok(button(p.app, 'See what’s next'));

  await clickButton(p.app, 'See what’s next');
  assert.equal(text(find(p.app, '.next-action h1')), 'You’re done for now');
  assert.ok(button(p.app, 'See my board'));
  assert.doesNotMatch(text(p.app), /Collect anything\. Virgil finds your next move\./);
  assert.equal(p.app.querySelector('[data-rail-ways]'), null,
    'a board with work on it was still being sold the arrival screen');

  await clickButton(p.app, 'See my board');
  assert.equal(button(p.app, 'Board').getAttribute('aria-pressed'), 'true');
  assert.deepEqual(
    p.app.querySelectorAll('.board .card .label').map((node) => text(node)),
    ['TLS key agreement', 'Forward secrecy'],
  );
});

