test('the concession is a confirmation: nothing is withdrawn until it is confirmed', async (t) => {
  const p = await open(t, wrongAnswer({ 'POST /sessions/sess-1/sections/t1/contest': { withdrawn: 2 } }));
  await startSession(p);
  const q = await answerFirst(p, 'It reuses the certificate key.');
  const before = paths(p).length;
  await clickButton(q, 'That marking is wrong');
  assert.equal(paths(p).length, before, 'the confirm step has not written anything');
  assert.match(text(find(q, '.confirm')), /I marked your answer on “How TLS gets its keys” wrong/);
  assert.match(text(find(q, '.confirm')), /It stops counting towards what I think you find hard/);
  assert.equal(find(q, '.confirm-status').getAttribute('role'), null,
    'the confirmation nested a second live region inside the contest status');

  await clickButton(q, 'Take the mark back');
  const req = lastWrite(p)!;
  assert.equal(req.url, `${SERVICE}/sessions/sess-1/sections/t1/contest`);
  assert.equal(req.method, 'POST');
  assert.equal(text(find(q, '.contest-form')), 'Taken back. 2 marks against you on this no longer count.');
  assert.equal(find(q, '.contest-form').getAttribute('role'), 'status');
  assert.equal(p.dom.activeElement, find(q, '.contest-form'));
  assert.equal(q.querySelectorAll('[data-contest]').length, 0, 'it cannot be taken back twice');
});

