// ============================================================== the board (SB-33)

const BOARD = {
  topics: [topic('t1', 'TLS'), topic('t2', 'Rust ownership'), topic('t3', 'Old thing', 'settled', 1)],
};


/**
 * Arrive, then walk to the board.
 *
 * The board was the arrival page for one day. These tests were written against
 * that and are unchanged in what they assert; what changed is that a person now
 * presses a door to get there, so they do too.
 */
/**
 * Show the board face.
 *
 * The board stopped being a room on 2026-08-25 and became Learn's second face,
 * so getting to it is a toggle rather than a door — and from anywhere else it
 * is the Learn door first. Scoped to `.face-toggle` because the nav's own Learn
 * door carries the same word, which is correct: one means "go to Learn" and the
 * other means "show this face of it".
 */
const toBoardFace = async (p: Panel): Promise<void> => {
  if (p.app.dataset.room !== 'today') await clickButton(p.app, 'Learn');
  await clickButton(find(p.app, '.face-toggle'), 'Board');
};

const openOnBoard = async (
  t: TestContext, table: Table, opts?: { worker?: boolean },
): Promise<Panel> => {
  const p = opts?.worker === false ? await open(t, table, false) : await open(t, table);
  await toBoardFace(p);
  return p;
};


const NO_SESSION: Table = {
  'GET /session': {
    session: null,
    card: card({ state: 'nothing-ready', sessionId: null, registers: [], why: null, reason: 'Nothing pinned yet.' }),
  },
};

const openBoard = async (t: TestContext, over: Table = {}): Promise<Panel> => {
  // Opening a topic reads what is inside it, so the board's own table answers
  // that too. A test that overrides it still wins, which is how the split
  // picker's fixtures keep working.
  const p = await open(t, home({
    'GET /board': { ...BOARD, suggestions: [] },
    'GET /topics/t1/pins': PINS,
    'GET /topics/t2/pins': PINS,
    ...over,
  }));
  await toBoardFace(p);
  return p;
};

/**
 * The board, with the first topic opened.
 *
 * Merge and Split belong to a topic a learner has opened and is looking at,
 * rather than to every row on the board — on a board of seven topics they were
 * fourteen underlined links, the most repeated thing on the screen and level
 * with the subjects themselves. So the repair tests open one first, which is
 * also what a person does.
 */
const openBoardTopic = async (t: TestContext, over: Table = {}): Promise<Panel> => {
  const p = await openBoard(t, { ...NO_SESSION, ...over });
  await clickButton(find(p.app, '.card'), 'TLS');
  return p;
};

test('a board topic with a lesson tonight opens that lesson on the Learn face', async (t) => {

  const p = await openBoard(t);
  const first = find(p.app, '.card');
  await clickButton(first, 'TLS');
  assert.equal(find(p.app, '.room-columns').getAttribute('data-face'), 'learn',
    'the click did not leave the board face');
  assert.equal(first.className, 'card', 'the card also opened its disclosure, which is two behaviours on one press');
  assert.match(text(find(p.app, '.room-main')), /How TLS gets its keys|TLS/,
    'the Learn face is not showing the lesson that was pressed');
});

/** A topic card by the subject written on it, because the areas decide the
 *  order and this is a question about one card. */
const boardCardFor = (p: Panel, label: string): El => {
  const hit = p.app.querySelectorAll('.card')
    .find((c) => text(c.querySelector('.label')) === label);
  if (!hit) throw new Error(`no card for "${label}"`);
  return hit;
};

test('the board marks the subjects tonight’s lesson serves, and marks no others', async (t) => {
  /**
   * The one decision this product makes for a learner was legible on the Learn
   * face and invisible on the face where their own subjects live. The default
   * session teaches t1 and t2; t3 is on the board and is not in it, and a mark
   * on that card would be the board promising a lesson that does not exist.
   */
  const p = await openBoard(t);
  assert.equal(text(boardCardFor(p, 'TLS').querySelector('.tonight')), 'In today’s lesson');
  assert.equal(text(boardCardFor(p, 'Rust ownership').querySelector('.tonight')), 'In today’s lesson');
  assert.equal(boardCardFor(p, 'Old thing').querySelector('.tonight'), null,
    'a subject the prepared session does not teach was marked as tonight’s work');
  // A fact, not an offer. The accent belongs to one control per screen and the
  // board is not it.
  assert.equal(p.app.querySelectorAll('.card .primary').length, 0);
});

test('a lesson already finished is not still tonight’s work on the board', async (t) => {
  // `lineupItems` drops completed sections, and the mark reads the lineup for
  // exactly this reason: what is left to do tonight, not what was composed.
  const p = await openBoard(t, {
    'GET /session': {
      session: session({ sections: [
        section({ completed: true, completionEvidence: 'answer', question: null }),
        section({ topicId: 't2', heading: 'Why forward secrecy', question: null }),
      ] }),
      card: card(),
    },
  });
  assert.equal(boardCardFor(p, 'TLS').querySelector('.tonight'), null);
  assert.equal(text(boardCardFor(p, 'Rust ownership').querySelector('.tonight')), 'In today’s lesson');
});

test('a board card declares both of its presses, and each label is true for that card', async (t) => {
  /**
   * The affordance-first interface contract: the affordances ARE the instruction, so this is not a sentence
   * on the screen. It is the accessible name and the tooltip of the two
   * controls, and there are two strings because the title press is genuinely
   * two doors: t1 has a lesson tonight and leaves the board for it, t3 has none
   * and opens onto its own pins. One label would be true half the time.
   */
  const p = await openBoard(t);
  const served = boardCardFor(p, 'TLS');
  const other = boardCardFor(p, 'Old thing');
  assert.equal(find(served, '.label').getAttribute('aria-label'), 'Open today’s lesson on TLS');
  assert.equal(find(served, '.label').getAttribute('title'), 'Open today’s lesson on TLS');
  assert.equal(find(other, '.label').getAttribute('aria-label'),
    'Open Old thing and see what you pinned to it');
  for (const node of [served, other]) {
    assert.equal(find(node, '.disclose').getAttribute('aria-label'), 'Show what you pinned to this');
    assert.equal(find(node, '.disclose').getAttribute('aria-expanded'), 'false');
  }
});

test('the triangle opens the pins in place, even on a topic whose title leaves for the lesson', async (t) => {
  const p = await openBoard(t);
  const served = boardCardFor(p, 'TLS');
  await click(find(served, '.disclose'));
  assert.equal(find(p.app, '.room-columns').getAttribute('data-face'), 'board',
    'the disclosure did the title’s job and left the board');
  assert.equal(find(served, '.disclose').getAttribute('aria-expanded'), 'true');
  assert.ok(find(served, '.pin'), 'the pins inside the topic were not drawn');
});

test('a finished session does not present zero remaining work as an expected duration', async (t) => {
  const p = await openBoard(t, {
    'GET /session': {
      session: session({
        sections: [section({ completed: true, completionEvidence: 'answer', question: null })],
        currentSectionIndex: 1,
      }),
      card: card(),
    },
  });
  await clickButton(find(p.app, '.card'), 'TLS');
  assert.equal(find(p.app, '.room-columns').getAttribute('data-face'), 'learn');
  assert.equal(p.app.querySelector('.room-rail .rail-kicker'), null,
    'finished work was still described as Expected time · 0 min');
  assert.match(text(find(p.app, '[data-lesson-completion]')), /Lesson finished/);
  await clickButton(find(p.app, '[data-rail="teaching"]'), 'See what’s next');
  assert.equal(p.app.querySelector('.section'), null,
    'the completed Board re-read had no product route back to Today');
});

test('a completed lesson in a mixed session uses the next-lesson rail without a duplicate action', async (t) => {
  const p = await open(t, home({
    'GET /session': {
      session: session({ sections: [
        section({ completed: true, completionEvidence: 'answer', question: null }),
        section({ topicId: 't2', heading: 'Why forward secrecy', question: null }),
      ] }),
      card: card(),
    },
  }));
  await startSession(p);
  await clickButton(find(p.app, '.room-rail'), 'How TLS gets its keys');
  assert.equal(p.app.querySelector('.section [data-after-session]'), null,
    'mixed-session navigation was duplicated inside the completed lesson');
  assert.ok(button(find(p.app, '.room-rail'), 'Why forward secrecy'));
});

test('the board lays out every area, and an empty area is still part of the board', async (t) => {
  const p = await openBoard(t);
  assert.equal(text(find(p.app, '.board-face-head h1')), 'Your learning board');
  assert.match(text(find(p.app, '.board-face-explainer')), /organised by where it is in your learning/);
  // Every area, every time. `boardGroups` dropped an empty group because a
  // heading over nothing is debris in a LIST; on a board the areas are the
  // furniture, and a learner who has settled nothing should still be able to
  // see where settled things go.
  assert.deepEqual(find(p.app, '.board').querySelectorAll('h2').map((h) => text(h)),
    ['Pending', 'Get Started', 'Currently Learning', 'Recharging', 'Paused', 'Learnt']);
});

test('a topic counts the things pinned to it — the evidence, not the display unit', async (t) => {
  const p = await openBoard(t);
  const first = find(p.app, '.card');
  assert.equal(text(find(first, '.label')), 'TLS');
  assert.equal(text(find(first, '.count')), '2 things you pinned');
  // SB-33: pins are evidence. The board shows topics, and confusing the two is
  // exactly how this becomes the backlog SB-18 refuses to be.
  assert.equal(p.app.querySelectorAll('.pin').length, 0);
});

test('an empty board says so', async (t) => {
  const p = await openOnBoard(t, home({ 'GET /board': { topics: [], suggestions: [] } }));
  // First-use guidance explains the gesture; it cannot erase the product's
  // structure. The headings are what tells a learner what Virgil will do
  // with the first thing they pin.
  assert.equal(text(find(p.app, '.firstrun h2')), 'Nothing here yet');
  assert.match(text(find(p.app, '.firstrun')), /Pin something/);
  assert.deepEqual(p.app.querySelectorAll('[data-area] h2').map((h) => text(h)),
    ['Pending', 'Get Started', 'Currently Learning', 'Recharging', 'Paused', 'Learnt']);
  assert.equal(p.app.querySelectorAll('[data-zone=process]').length, 0,
    'an empty board offered to build a refresh from material that does not exist');
});

test('a board the service cannot supply says so rather than claiming there is nothing on it', async (t) => {
  // "Nothing yet" here would be a lie about the learner's own work, and this is
  // the one place where an unreachable service and an empty board look
  // identical. The board is a room of its own now, so the line it draws is the
  // unreachable one rather than the both-halves-failed one — and it still names
  // the failure rather than reporting an empty board.
  const p = await openOnBoard(t, home({ 'GET /board': DOWN }));
  const said = text(find(p.app, '.empty'));
  assert.match(said, /I can't open your board/);
  assert.match(said, /wait safely in this browser/, 'and it says where a pin made now would go');
});

// ------------------------------------------------------------------- merge

test('a merge names both sides and promises the history before it asks', async (t) => {
  const p = await openBoardTopic(t, { 'POST /topics/t1/merge': { ok: true } });
  const first = find(p.app, '.card');
  await clickButton(first, 'Merge into…');
  assert.equal(find(first, 'select').value, 't2', 'the first other topic is offered');
  assert.equal(p.dom.activeElement, find(first, 'select'),
    'opening the merge choice left focus on the topic behind it');

  const before = paths(p).length;
  await clickButton(first, 'Continue');
  assert.equal(paths(p).length, before, 'still nothing written');
  assert.equal(p.dom.activeElement, button(first, 'Merge'),
    'the confirmation opened behind keyboard focus');
  const confirm = text(find(first, '.confirm'));
  assert.match(confirm, /2 things you pinned move to “Rust ownership”/);
  // The promise the learner would actually worry about, and the reason this
  // control can be offered at all.
  assert.match(confirm, /The history of “TLS” will be kept under “Rust ownership”\. Nothing you have done is lost/);
});

test('a confirmed merge posts the target and redraws the board', async (t) => {
  const p = await openBoardTopic(t, { 'POST /topics/t1/merge': { ok: true } });
  const first = find(p.app, '.card');
  await clickButton(first, 'Merge into…');
  await clickButton(first, 'Continue');
  let pending = '';
  let busy = '';
  let buttonsWaiting = false;
  p.route(home({
    ...NO_SESSION,
    'GET /board': { ...BOARD, suggestions: [] },
    'GET /topics/t1/pins': PINS,
    'POST /topics/t1/merge': () => {
      const confirm = find(first, '.confirm');
      pending = text(find(confirm, '.confirm-status'));
      busy = confirm.getAttribute('aria-busy') ?? '';
      buttonsWaiting = confirm.querySelectorAll('button').every((b) => b.disabled);
      return { ok: true };
    },
  }));
  await clickButton(first, 'Merge');
  const req = lastWrite(p)!;
  assert.equal(req.url, `${SERVICE}/topics/t1/merge`);
  assert.equal(req.method, 'POST');
  assert.deepEqual(req.body, { into: 't2' });
  assert.ok(paths(p).slice(-BOARD_PAINT.length).includes('GET /board'), 'the board is re-read, not patched');
  assert.equal(pending, 'Merge…');
  assert.equal(busy, 'true');
  assert.equal(buttonsWaiting, true);
  const receipt = find(p.app, '.board-write-receipt');
  assert.equal(text(receipt), 'Topics merged.');
  assert.equal(receipt.getAttribute('role'), 'status');
});

test('a merge into a different topic sends that one', async (t) => {
  const p = await openBoardTopic(t, { 'POST /topics/t1/merge': { ok: true } });
  const first = find(p.app, '.card');
  await clickButton(first, 'Merge into…');
  find(first, 'select').value = 't3';
  await clickButton(first, 'Continue');
  await clickButton(first, 'Merge');
  assert.deepEqual(lastWrite(p)!.body, { into: 't3' });
});

test('cancelling a merge at either step writes nothing', async (t) => {
  const p = await openBoardTopic(t, { 'POST /topics/t1/merge': { ok: true } });
  const first = find(p.app, '.card');
  await clickButton(first, 'Merge into…');
  await clickButton(first, 'Cancel');
  assert.equal(text(find(first, '.repair-form')), '');
  assert.equal(p.dom.activeElement, button(first, 'Merge into…'));

  await clickButton(first, 'Merge into…');
  await clickButton(first, 'Continue');
  await clickButton(first, 'Cancel');
  assert.equal(text(find(first, '.repair-form')), '');
  assert.equal(p.dom.activeElement, button(first, 'Merge into…'));
  assert.ok(!paths(p).some((s) => s.includes('merge')));
});

test('a merge that does not land says so and leaves the board alone', async (t) => {
  const p = await openBoardTopic(t, { 'POST /topics/t1/merge': DOWN });
  const first = find(p.app, '.card');
  await clickButton(first, 'Merge into…');
  await clickButton(first, 'Continue');
  await clickButton(first, 'Merge');
  const failure = find(first, '.repair-form .empty');
  assert.equal(text(failure), "That didn't go through. Nothing changed.");
  assert.equal(failure.getAttribute('role'), 'alert');
  assert.equal(failure.getAttribute('tabindex'), '-1');
  assert.equal(p.dom.activeElement, failure);
});

test('a board of one has nothing to merge into, and says so instead of offering it', async (t) => {
  const p = await openOnBoard(t, home({
    ...NO_SESSION,
    'GET /board': { topics: [topic('t1', 'TLS')], suggestions: [] },
    'GET /topics/t1/pins': { pins: [] },
  }));
  const only = find(p.app, '.card');
  // Opened first, because the repair controls belong to a topic somebody is
  // looking at rather than to every row on the board.
  await clickButton(only, 'TLS');
  await clickButton(only, 'Merge into…');
  assert.equal(text(find(only, '.repair-form')), 'There is nothing else on the board to merge into yet.');
});

// ------------------------------------------------------------------- split

const PINS = { pins: [
  { id: 'p1', title: 'Handshake walkthrough', gist: 'how the keys are agreed' },
  { id: 'p2', title: 'Cert chains', gist: 'who vouches for whom' },
] };

const openSplit = async (t: TestContext, over: Table = {}): Promise<{ p: Panel; topicEl: El }> => {
  const p = await openBoardTopic(t, { 'GET /topics/t1/pins': PINS, ...over });
  const topicEl = find(p.app, '.card');
  await clickButton(topicEl, 'Split…');
  return { p, topicEl };
};

test('a split reads the topic pins before it can offer anything to move', async (t) => {
  const { p, topicEl } = await openSplit(t);
  assert.equal(paths(p)[paths(p).length - 1], 'GET /topics/t1/pins');
  assert.deepEqual(find(topicEl, '.repair-choice').querySelectorAll('.pick').map((l) => text(l)),
    ['Handshake walkthrough how the keys are agreed', 'Cert chains who vouches for whom']);
  assert.equal(p.dom.activeElement, find(topicEl, 'input[type=checkbox]'),
    'opening the split choice left focus behind the form');
});

test('cancelling a split returns focus to the topic repair control', async (t) => {
  const { p, topicEl } = await openSplit(t);
  await clickButton(topicEl, 'Cancel');
  assert.equal(text(find(topicEl, '.repair-form')), '');
  assert.equal(p.dom.activeElement, button(topicEl, 'Split…'));
});

test('a topic with one thing in it has nothing to split', async (t) => {
  const { topicEl } = await openSplit(t, { 'GET /topics/t1/pins': { pins: [PINS.pins[0]] } });
  assert.equal(text(find(topicEl, '.repair-form')),
    'A topic needs at least two things pinned before it can be split.');
});

test('a split that could not read the topic says so, and does not blame the learner', async (t) => {
  /**
   * The same distinction the card above the picker already kept, in the one
   * place under it that did not. `data?.pins ?? []` turned a service that never
   * answered into a topic with nothing in it, so a down service and a topic
   * with one pin came out of this function as the same sentence — and that
   * sentence is a claim about what the learner has pinned, made by a read that
   * had just failed to find out.
   *
   * The card's own read is answered and the picker's is not, because that is
   * how a live service falls over: between two clicks rather than before both.
   */
  let asked = 0;
  const { topicEl } = await openSplit(t, {
    'GET /topics/t1/pins': () => (asked++ === 0 ? PINS : DOWN),
  });
  const said = text(find(topicEl, '.repair-form'));
  assert.match(said, /could not read what is in this one/);
  assert.notEqual(said, 'A topic needs at least two things pinned before it can be split.',
    'a service that did not answer is being reported as an empty topic');
  // And nothing is offered to move, because nothing was read.
  assert.equal(topicEl.querySelectorAll('.repair-choice').length, 0);
});

test('the split picker names the wait rather than sitting on three dots', async (t) => {
  // The bare `…` this drew is the nothing the take screen used to sit on, on a
  // screen where somebody is repairing their own history. Read while the
  // request is in flight, which is the only moment a waiter exists.
  const p = await openBoardTopic(t);
  const topicEl = find(p.app, '.card');
  let waitedBehind = '';
  p.route(home({
    ...NO_SESSION,
    'GET /board': { ...BOARD, suggestions: [] },
    'GET /topics/t1/pins': () => {
      waitedBehind = text(find(topicEl, '.repair-form'));
      return PINS;
    },
  }));
  await clickButton(topicEl, 'Split…');
  assert.equal(waitedBehind, LOADING_SPLIT_PINS);
  assert.ok(!/^loading/i.test(LOADING_SPLIT_PINS), 'a wait that names nothing is a spinner with words on it');
});

test('the split refusals are said before the confirm step, not after it', async (t) => {
  const { p, topicEl } = await openSplit(t);
  const form = find(topicEl, '.repair-choice');
  const boxes = form.querySelectorAll('input[type=checkbox]');
  const before = paths(p).length;

  await clickButton(form, 'Continue');
  assert.equal(text(find(form, '.note')), 'Pick at least one thing to move.');

  for (const b of boxes) b.checked = true;
  await clickButton(form, 'Continue');
  assert.equal(text(find(form, '.note')), 'A split has to leave something behind. That would move everything.');

  boxes[1]!.checked = false;
  await clickButton(form, 'Continue');
  assert.equal(text(find(form, '.note')), 'The new topic needs a name. You name it, not me.');
  assert.equal(text(find(form, '.topic-name-limit')), TOPIC_LABEL_LIMIT_LINE);

  const name = find(form, '.name');
  name.value = '😀'.repeat(TOPIC_LABEL_MAX_CHARS + 1);
  await clickButton(form, 'Continue');
  assert.match(text(find(form, '.note')), /nothing was sent/);
  assert.equal(p.dom.activeElement, name);
  assert.equal(Array.from(name.value).length, TOPIC_LABEL_MAX_CHARS + 1);
  assert.equal(paths(p).length, before, 'nothing has been sent while it is being refused');
});

test('a confirmed split posts the pins and the name the learner chose', async (t) => {
  const { p, topicEl } = await openSplit(t, { 'POST /topics/t1/split': { ok: true } });
  const form = find(topicEl, '.repair-choice');
  form.querySelectorAll('input[type=checkbox]')[0]!.checked = true;
  find(form, '.name').value = '  Handshakes  ';
  await clickButton(form, 'Continue');

  const confirm = text(find(topicEl, '.confirm'));
  assert.match(confirm, /1 thing moves to a new topic called “Handshakes”/);
  assert.match(confirm, /“TLS” keeps all of its history, and 1 thing stays there/);
  assert.match(confirm, /The new topic starts fresh: nothing is known about it yet/);

  await clickButton(topicEl, 'Split');
  const req = lastWrite(p)!;
  assert.equal(req.url, `${SERVICE}/topics/t1/split`);
  assert.deepEqual(req.body, { pinIds: ['p1'], label: 'Handshakes' });
  assert.ok(paths(p).slice(-BOARD_PAINT.length).includes('GET /board'));
  assert.equal(text(find(p.app, '.board-write-receipt')), 'New topic created.');
  assert.equal(find(p.app, '.board-write-receipt').getAttribute('aria-live'), 'polite');
});

test('an exact Unicode topic name is confirmed and sent whole', async (t) => {
  const { p, topicEl } = await openSplit(t, { 'POST /topics/t1/split': { ok: true } });
  const form = find(topicEl, '.repair-choice');
  form.querySelectorAll('input[type=checkbox]')[0]!.checked = true;
  const exact = '😀'.repeat(TOPIC_LABEL_MAX_CHARS);
  find(form, '.name').value = `  ${exact}  `;
  await clickButton(form, 'Continue');
  assert.match(text(find(topicEl, '.confirm')), new RegExp(exact));
  await clickButton(topicEl, 'Split');
  assert.equal((lastWrite(p)?.body as Record<string, unknown>).label, exact);
});

test('a split that does not land says so and leaves the topic whole', async (t) => {
  const { p, topicEl } = await openSplit(t, { 'POST /topics/t1/split': DOWN });
  const form = find(topicEl, '.repair-choice');
  form.querySelectorAll('input[type=checkbox]')[0]!.checked = true;
  find(form, '.name').value = 'Handshakes';
  await clickButton(form, 'Continue');
  await clickButton(topicEl, 'Split');
  const failure = find(topicEl, '.repair-form .empty');
  assert.equal(text(failure), "That didn't go through. Nothing changed.");
  assert.equal(failure.getAttribute('role'), 'alert');
  assert.equal(failure.getAttribute('tabindex'), '-1');
  assert.equal(p.dom.activeElement, failure);
  assert.ok(!paths(p).slice(-1).includes('GET /board'));
});

test('a topic id that is not url-safe still reaches its own endpoints', async (t) => {
  const p = await openOnBoard(t, home({
    'GET /board': { topics: [topic('a/b', 'Slashes'), topic('t2', 'Other')], suggestions: [] },
    'GET /topics/a%2Fb/pins': PINS,
  }));
  // Both routes into this topic are encoded the same way: opening it, and then
  // the split picker reading it again.
  await clickButton(find(p.app, '.card'), 'Slashes');
  assert.equal(paths(p)[paths(p).length - 1], 'GET /topics/a%2Fb/pins');
  await clickButton(find(p.app, '.card'), 'Split…');
  assert.equal(paths(p)[paths(p).length - 1], 'GET /topics/a%2Fb/pins');
});

// ================================================= what it thinks of you (SB-42)

const STATEMENTS = { statements: [
  { id: 'st-1', text: 'You learn best from a worked example.', userEdited: false,
    evidenceReceipt: 'complete', evidence: [
      { type: 'answer-wrong', topic: 'Worked examples', active: true },
      { type: 'answer-wrong', topic: 'Worked examples', active: true },
      { type: 'depth-simpler', topic: 'Worked examples', active: false },
    ] },
  { id: 'st-2', text: 'You already know Python.', userEdited: true },
] };

const openModel = async (t: TestContext, over: Table = {}): Promise<Panel> => {
  const p = await open(t, home({ 'GET /model': STATEMENTS, ...over }));
  await clickButton(p.app, 'Insights');
  return p;
};

/**
 * The two rows in `STATEMENTS`, found by the section each one belongs in.
 *
 * Since the room became five sections its rows are no longer in the order the
 * service listed them: they are ordered by who said a thing, and their own
 * words come first. Reaching for these by position would make every test below
 * a test of the ordering as well as of the control it is actually about.
 */
const machineRead = (p: Panel): El => find(p.app, '[data-section="patterns"] .statement');
const ownWords = (p: Panel): El => find(p.app, '[data-section="told"] .statement');

test('the model screen is sentences in the order it wrote them, with no scores', async (t) => {
  const p = await openModel(t);
  assert.equal(text(find(p.app, '.model-intro')),
    'These are the things I can carry into future lessons. Your words come first, and you can challenge any read.');
  assert.ok(button(p.app, 'Tell Virgil something'));
  // Their own words first, because the room is ordered by who said a thing and
  // theirs outrank the read below them. Both rows are unchanged inside.
  assert.deepEqual(p.app.querySelectorAll('.statement .text').map((s) => text(s)),
    ['You already know Python.', 'You learn best from a worked example.']);
  assert.deepEqual(p.app.querySelectorAll('.state').map((s) => text(s)), ['your words', 'my read']);
  const first = p.app.querySelectorAll('.statement')[1]!;
  const own = p.app.querySelectorAll('.statement')[0]!;
  assert.equal(button(first, 'Correct it').getAttribute('aria-label'),
    'Correct it: You learn best from a worked example.');
  assert.equal(button(first, 'Reject it').getAttribute('aria-label'),
    'Reject it: You learn best from a worked example.');
  assert.equal(button(own, 'Edit my words').getAttribute('aria-label'),
    'Edit my words: You already know Python.');
  assert.equal(button(own, 'Delete').getAttribute('aria-label'),
    'Delete: You already know Python.');
  const evidence = find(first, '.statement-evidence');
  assert.equal(text(find(evidence, 'summary')), 'What this came from');
  assert.equal(find(evidence, 'summary').getAttribute('aria-label'),
    'What this came from: You learn best from a worked example.');
  assert.deepEqual(evidence.querySelectorAll('li').map((item) => text(item)), [
    'Worked examples: answers I marked wrong',
    'Worked examples: times you asked me to go simpler (no longer counts)',
  ]);
  assert.equal(own.querySelectorAll('.statement-evidence').length, 0,
    'learner words do not pretend to be a machine evidence receipt');
});


