test('Insights draws its five sections in one order, and only the ones with something in them', async (t) => {
  const p = await openModel(t, { 'GET /model': GROUPED });
  assert.deepEqual(p.app.querySelectorAll('.insight-section').map((s) => s.dataset['section']),
    ['questions', 'told', 'confirmed', 'patterns', 'subjects']);
  assert.deepEqual(p.app.querySelectorAll('.insight-section .section-toggle .name').map((n) => text(n)),
    ['Questions for you', 'Things you told me', 'Things you confirmed',
      "Patterns I'm seeing", 'Where each subject stands']);
  assert.deepEqual(p.app.querySelectorAll('.insight-section .section-toggle .count').map((n) => text(n)),
    ['1 to answer', '1 from you', '1 confirmed', '1 to review', '3 to review']);
  assert.equal(find(p.app, '[data-section="confirmed"] .section-toggle').getAttribute('aria-expanded'),
    'false', 'settled reads begin compact');
  assert.equal(find(p.app, '[data-section="patterns"] .section-toggle').getAttribute('aria-expanded'),
    'true', 'unanswered reads lead visibly');
  assert.deepEqual(
    p.app.querySelectorAll('.insight-section').map(
      (section) => section.querySelectorAll('.statement .text').map((n) => text(n)),
    ),
    [
      ['Does notation heavy material go less smoothly for you?'],
      ['You already know Python.'],
      ['You settle faster after one worked example.'],
      ['You come back to things in the evening rather than the morning.'],
      ['You reach for the mechanism before the definition.',
        'In that area you settle once you have written one out by hand.',
        'Bayes gets skipped whenever something else is available.'],
    ],
    'the question draws as a question card, and the rest land by who said them',
  );
  // The question is in its own section, drawn as the card SB-282 built.
  assert.equal(find(p.app, '.insight-section .statement.modality').dataset['modality'],
    'notation-heavy|logic-structure');
  // Stored order survives inside a subject, because the night writes chains.
  assert.deepEqual(p.app.querySelectorAll('.insight-section .alt-label .name').map((n) => text(n)),
    ['Systems Design', 'Bayes rule']);
  // A quiet label, in the treatment the rails and the lesson already use for
  // one. The accent on this screen is not spent on saying what a pile is.
  assert.equal(find(p.app, '.statement-group .alt-label').tagName, 'H2');
});

