/**
 * WHAT A SENTENCE ON THIS SCREEN HAS ALREADY CAUSED.
 *
 * The night scout records which gap each proposal was built on, and two of its
 * six kinds are built on a statement: `statement:<id>` is the comfort-gated
 * read and `read:<id>` is the shortfall the board wrote. Where one of those is
 * still waiting on an answer, the row it came from says so and offers the door
 * to the room the answer is waiting in. Every other kind of gap cites a signal,
 * a topic or a count, and nothing on this screen claims otherwise.
 */
const proposal = (evidenceKey: string, over: Record<string, unknown> = {}) => ({
  id: `p-${evidenceKey}`, subject: 'A gentler introduction to quorums',
  reason: 'Because the board says this is not settled yet.',
  evidenceKind: 'shaky-statement', evidenceKey,
  evidenceDetail: 'On "Quorums": you reach for the mechanism first.', ...over,
});

test('a statement a waiting suggestion stands on says so, and opens the room it waits in', async (t) => {
  const p = await openModel(t, {
    'GET /prospects': { proposals: [proposal('statement:st-1')] },
    'GET /courses': { courses: [], unattached: { commitments: [], topics: [] } },
    'GET /course-intakes': { drafts: [] },
    'GET /outcomes': { outcomes: [] },
  });
  const cited = find(p.app, '[data-section="patterns"] .statement');
  const uncited = find(p.app, '[data-section="told"] .statement');
  assert.equal(text(find(cited, '.statement-consequence .meta')),
    'This is behind a suggestion waiting in My studies.');
  assert.equal(uncited.querySelectorAll('.statement-consequence').length, 0,
    'a line about a suggestion appeared over a statement no suggestion cites');

  await clickButton(find(cited, '.statement-consequence'), 'My studies');
  assert.equal(p.app.dataset.room, 'courses');
});

test('the shortfall kind cites its statement too, and one row says it once', async (t) => {
  const p = await openModel(t, {
    'GET /prospects': { proposals: [
      proposal('read:st-1', { evidenceKind: 'shortfall-read' }),
      proposal('statement:st-1'),
      proposal('avoided:t-1', { evidenceKind: 'avoided-topic' }),
    ] },
  });
  assert.equal(p.app.querySelectorAll('.statement-consequence').length, 1,
    'two proposals on one sentence is still one thing waiting on this row');
});

