/**
 * SB-282 — THE MODALITY QUESTION, THROUGH THE PANEL'S OWN DOORS.
 *
 * `insights-view.test.ts` proves the card. What is proved here is the wiring
 * the claim-discipline law actually depends on: which endpoint each answer
 * hits, that a question is not drawn with the controls that would let somebody
 * correct a sentence nobody has agreed to yet, and that a confirmed one is an
 * ordinary confirmed read with the ordinary controls back.
 */
const MODALITY_TEXT =
  'Recent checks suggest notation heavy material goes less smoothly for you than'
  + ' logic and structure work: 1 of 5 checks went well on notation heavy material,'
  + ' against 5 of 6 on logic and structure work. Does that match how it feels?';

const modalityRow = (confirmed: boolean) => ({
  id: 'mod-1', text: MODALITY_TEXT, userEdited: false, evidenceReceipt: 'complete',
  evidence: [{ type: 'answer-wrong', topic: 'Laplace transforms', active: true }],
  // `confirmed` on the row is what the service sends about any sentence the
  // learner has agreed with, and an answered question is one of those.
  ...(confirmed ? { confirmed: true } : {}),
  modality: { key: 'notation-heavy|logic-structure', confirmed },
});

test('an unanswered modality read is drawn as a question, not as a read to correct', async (t) => {
  const p = await openModel(t, { 'GET /model': { statements: [modalityRow(false)] } });
  const card = find(p.app, '.statement.modality');
  assert.equal(text(find(card, '.text')), MODALITY_TEXT);
  assert.equal(text(find(card, '.state')), 'a question, not a read');
  assert.equal(text(find(card, '.statement-evidence li')),
    'Laplace transforms: answers I marked wrong');
  assert.ok(button(card, 'Yes, that matches'));
  assert.ok(button(card, 'No, that is not it'));
  assert.equal(card.querySelectorAll('[data-edit]').length, 0,
    'Correct it would offer to rewrite a sentence nobody has agreed to yet');
  assert.equal(card.querySelectorAll('[data-delete]').length, 0);
});

test('yes goes to the confirm door and no goes to the ordinary rejection', async (t) => {
  for (const [label, expected] of [
    ['Yes, that matches', 'POST /model/mod-1/confirm'],
    ['No, that is not it', 'DELETE /model/mod-1'],
  ] as const) {
    const p = await openModel(t, {
      'GET /model': { statements: [modalityRow(false)] },
      'POST /model/mod-1/confirm': { ok: true },
      'DELETE /model/mod-1': { ok: true, rejected: true, quietForDays: 30 },
    });
    await clickButton(find(p.app, '.statement.modality'), label);
    assert.equal(paths(p)[paths(p).length - 1], expected);
  }
});

test('a confirmed modality read is an ordinary confirmed statement', async (t) => {
  const p = await openModel(t, { 'GET /model': { statements: [modalityRow(true)] } });
  assert.equal(p.app.querySelectorAll('.statement.modality').length, 0,
    'the question is answered, so it stops being drawn as one');
  const row = find(p.app, '.statement');
  assert.equal(text(find(row, '.text')), MODALITY_TEXT);
  assert.equal(text(find(row, '.state')), 'confirmed');
  assert.notEqual(text(find(row, '.state')), 'your words',
    'agreeing with a read did not make it their words');
  assert.equal(row.querySelectorAll('[data-confirm]').length, 0,
    'a sentence they have already agreed with was offered the same agreement again');
  assert.ok(button(row, 'Correct it'));
  assert.ok(button(row, 'Reject it'));
  assert.equal(text(find(row, '.statement-evidence li')),
    'Laplace transforms: answers I marked wrong');
});

test('a denied question is simply absent, with no trace of it on the screen', async (t) => {
  // The service drops rejected statements from `GET /model`, so the panel's
  // whole job here is to say nothing: no placeholder, no note that a question
  // was asked and answered, and no empty block where one used to be.
  const p = await openModel(t, { 'GET /model': { statements: [] } });
  assert.equal(p.app.querySelectorAll('.statement.modality').length, 0);
  assert.doesNotMatch(text(p.app), /notation heavy|Does that match/,
    'a denial is taken, and taking it means the screen stops mentioning it');
});

/**
 * WHAT KEEPS SLIPPING, ON THE SCREEN AND NOWHERE ELSE.
 *
 * Three assertions and they are the three promises: the numbers the service
 * wrote are the numbers on screen, the control writes the learner's own
 * decision through the door built for it, and a board with nothing slipping
 * draws no block rather than a compliment.
 */
const SLIPPING_ROW = {
  key: 'commitment:late-1',
  title: 'Stats problem set 3',
  standingLine: 'Past its date, and you have not touched it for 12 days.',
  elsewhereLine: 'In that time you finished 9 other things on your board.',
  activationLine: '1 minute of it counts.',
  passedOverLine: 'Offered and passed over 3 times since 14 August 2026.',
};

test('Insights names what keeps slipping, with the evidence in numbers beside it', async (t) => {
  const p = await openModel(t, {
    'GET /model': { statements: [], slipping: [SLIPPING_ROW] },
    'POST /model/slipping/set-aside': { ok: true },
  });
  const block = find(p.app, '.slipping-block');
  assert.equal(text(find(block, 'h2')), 'What keeps slipping');
  assert.deepEqual(block.querySelectorAll('.slipping').map((row) => text(find(row, 'h3'))),
    ['Stats problem set 3']);
  assert.equal(text(find(block, '.standing')),
    'Past its date, and you have not touched it for 12 days.');
  assert.equal(text(find(block, '.elsewhere')),
    'In that time you finished 9 other things on your board.');
  assert.equal(text(find(block, '.passed-over')),
    'Offered and passed over 3 times since 14 August 2026.');
  assert.equal(text(find(block, '.activation')), '1 minute of it counts.');
  assert.equal(text(p.app).includes('avoid'), false,
    'the noun on this screen is slipping; avoidance is a diagnosis and is never rendered');

  await clickButton(block, 'Setting this aside on purpose');
  assert.equal(lastWrite(p)?.url.slice(SERVICE.length), '/model/slipping/set-aside');
  assert.deepEqual(lastBody(p), { key: 'commitment:late-1' });
  assert.match(text(find(block, '.note')), /^Set aside\./);
});

test('a board with nothing slipping draws no block, and no praise in its place', async (t) => {
  const p = await openModel(t, { 'GET /model': { statements: [], slipping: [] } });
  assert.equal(p.app.querySelectorAll('.slipping-block').length, 0);
  assert.equal(p.app.querySelectorAll('.slipping').length, 0);
});

test('starting something else marks what was passed over, and a render marks nothing', async (t) => {
  const primary = {
    id: 'commitment:late-1', kind: 'commitment', targetId: 'late-1',
    title: 'Stats problem set 3', detail: 'Assignment.', minutes: 1,
    destination: 'plan', cta: 'Show me where this sits', rank: 900,
    reasons: [{ code: 'deadline', text: 'This is still open past its date.' }],
  };
  const alternative = {
    id: 'material:k1:m1', kind: 'course-material', targetId: 'k1',
    title: 'Agent lecture', detail: 'Use this minute to begin it.', minutes: 1,
    destination: 'courses', url: 'https://example.test/lecture', materialId: 'm1',
    cta: 'Open material', rank: 340,
    reasons: [{ code: 'next-material', text: 'It is next.' }],
  };
  const p = await open(t, railed({
    'GET /today': { next: { availableMinutes: 1, primary, alternatives: [alternative] } },
    'POST /model/slipping/passed-over': { ok: true },
  }));
  assert.equal(paths(p).some((path) => path.includes('passed-over')), false,
    'nothing is written by drawing the rail: reading a list is not choosing off it');

  const block = find(p.app, '[data-rail=instead]');
  await click(block.querySelectorAll('.alt')[block.querySelectorAll('.alt').length - 1]!);
  const written = p.requests.find((r) => r.url.includes('passed-over'));
  assert.ok(written, 'starting an alternative is the press this ledger is written on');
  assert.deepEqual(written?.body, {
    offeredId: 'commitment:late-1',
    chosenId: 'material:k1:m1',
    offeredReason: 'deadline',
  });
});

test('the learner can write the first authoritative insight without waiting for a machine read', async (t) => {
  const p = await openModel(t, {
    'GET /model': { statements: [], hasLearningMaterial: false },
    'POST /model': { statement: { id: 'own-1', text: 'I need diagrams before formulas.' } },
    'GET /today': { next: NEXT_EMPTY },
    'GET /session': { session: null, card: null, upcoming: [] },
  });
  const launcher = button(p.app, 'Tell Virgil something');
  await clickButton(p.app, 'Tell Virgil something');
  const textarea = find(p.app, '.model-add textarea');
  assert.equal(textarea.getAttribute('aria-label'), 'What should Virgil remember for future lessons?');
  assert.match(textarea.getAttribute('placeholder') ?? '', /concrete example/);
  assert.equal(launcher.getAttribute('hidden'), '', 'the launch control does not compete with its open editor');
  assert.equal(p.dom.activeElement, textarea);

  textarea.value = '   ';
  const before = paths(p).length;
  await clickButton(find(p.app, '.model-add'), 'Save');
  assert.equal(text(find(p.app, '.model-add .note')), 'Say what Virgil should know first.');
  assert.equal(find(p.app, '.model-add .note').getAttribute('role'), 'status');
  assert.equal(paths(p).length, before);

  textarea.value = '  I need diagrams before formulas.  ';
  await clickButton(find(p.app, '.model-add'), 'Save');
  const req = [...p.requests].reverse().find((request) =>
    request.url === `${SERVICE}/model` && request.method === 'POST')!;
  assert.equal(req.url, `${SERVICE}/model`);
  assert.equal(req.method, 'POST');
  const body = req.body as Record<string, unknown>;
  assert.equal(body.text, 'I need diagrams before formulas.');
  assert.match(String(body.clientRef), /^[A-Za-z0-9_-]{8,160}$/);
  assert.match(text(find(p.app, '.model-correction-receipt')), /Saved as your words/);
  assert.equal(text(find(p.app, '.model-correction-receipt .model-next .title')),
    'Collect anything. Virgil finds your next move.');
  assert.equal(p.dom.activeElement, button(p.app, 'Add course material'));

  await clickButton(p.app, 'Add course material');
  assert.equal(text(find(p.app, 'h1')), 'My studies');
  assert.ok(button(p.app, 'Add'));

  assert.ok(launcher !== p.dom.activeElement, 'the removed launcher retained focus after Save');
});

