test('an unreachable Insight keeps one exact receipt and focused retry', async (t) => {
  const attempts: Record<string, unknown>[] = [];
  let calls = 0;
  const p = await openModel(t, {
    'GET /model': { statements: [] },
    'POST /model': (init: RequestInit | undefined) => {
      attempts.push(JSON.parse(String(init?.body)) as Record<string, unknown>);
      calls += 1;
      return calls === 1 ? DOWN : { statement: { id: 'own-1' } };
    },
  });
  await clickButton(p.app, 'Tell Virgil something');
  const form = find(p.app, '.model-add');
  const field = find(form, 'textarea');
  await typeInto(field, 'Show me the diagram before the formula.');
  await clickButton(form, 'Save');
  assert.equal(text(find(form, '.note')),
    'I could not save that. Your new insight is still here; try again.');
  assert.equal(field.value, 'Show me the diagram before the formula.');
  assert.equal(p.dom.activeElement, button(form, 'Save'));

  await clickButton(form, 'Save');
  assert.equal(attempts.length, 2);
  assert.equal(attempts[0]?.clientRef, attempts[1]?.clientRef);
  assert.equal(attempts[0]?.text, attempts[1]?.text);
});

test('authored writes distinguish invalid input, answered refusal and unreachable service', async (t) => {
  for (const [tag, route, expected] of [
    ['invalid', status(400), 'I could not use that input. Check your new insight; nothing was recorded.'],
    ['refused', status(500), 'I could not save that. Your new insight is still here; nothing was recorded.'],
    ['unreachable', DOWN, 'I could not save that. Your new insight is still here; try again.'],
  ] as const) {
    const p = await openModel(t, { 'GET /model': { statements: [] }, 'POST /model': route });
    await clickButton(p.app, 'Tell Virgil something');
    const form = find(p.app, '.model-add');
    await typeInto(find(form, 'textarea'), `A ${tag} attempt I still own.`);
    await clickButton(form, 'Save');
    assert.equal(text(find(form, '.note')), expected, tag);
    assert.equal(p.dom.activeElement, button(form, 'Save'), tag);
  }
});

