type ModelFixture = {
  schemaVersion?: number;
  providers?: Record<string, Record<string, unknown>>;
  routes?: Record<string, string>;
  limits?: Record<string, unknown> | null;
};

/**
 * What a paste may be, in characters, as the service publishes it.
 *
 * The numbers are `core`'s and the service returns them so the panel does not
 * have to hold a second copy of "12,000" that drifts. `model-config-endpoints.
 * test.ts` in the runner is what holds these to the constants they came from;
 * this fixture is what the Check screen's meter reads.
 */
const CHECK_LIMITS = {
  markWorkChars: 12_000, reviewDraftChars: 6_000, contextChars: 4_000,
  markWorkMinChars: 200, reviewDraftMinChars: 80,
  rubricCriteria: 24, rubricCriterionChars: 400,
};

const modelConfig = (over: ModelFixture = {}): Record<string, unknown> => {
  const providers: Record<string, Record<string, unknown>> = {
    cloud: {
      enabled: true, readiness: 'ready', detail: 'Google is configured.',
      // What a call on this connection would go to, and how much it could read.
      // A token budget rather than a credential, and the only number on this
      // receipt that is a property of the model rather than of the product.
      models: { deep: { modelId: 'gemini-3.7-flash', maxInputTokens: 1_048_576 } },
      setup: { editable: true, managed: false, credential: 'configured', check: 'available' },
    },
    local: {
      enabled: false, readiness: 'ready', detail: 'The local endpoint answered.',
      endpoint: 'http://127.0.0.1:11434',
      // Null on purpose: a local model is whatever the operator pulled, and
      // inventing a window for it would be worse than saying nothing.
      models: { deep: { modelId: 'qwen3.8:27b-mlx', maxInputTokens: null } },
      setup: { editable: true, managed: false, credential: 'not-required', check: 'available' },
    },
    cli: {
      enabled: false, readiness: 'not-checked', detail: 'The Agent CLI endpoint has not been checked.',
      endpoint: 'http://127.0.0.1:8798',
      models: { deep: { modelId: null, maxInputTokens: null } },
      setup: { editable: false, managed: true, credential: 'configured', check: 'available' },
    },
  };
  return {
    schemaVersion: over.schemaVersion ?? 1,
    providers: { ...providers, ...over.providers },
    routes: { quick: 'cloud', deep: 'cloud', images: 'cloud', ...over.routes },
    limits: over.limits === undefined ? CHECK_LIMITS : over.limits,
  };
};

const healthReceipt = (over: Record<string, unknown> = {}): Record<string, unknown> => ({
  ok: true,
  compatibility: {
    protocol: 'virgil-browser-service', serviceSchema: 1,
    minClientSchema: 1, maxClientSchema: 1, modelConfigSchema: 1,
  },
  ...over,
});

const modelConfigWithoutCloudKey = (over: ModelFixture = {}): Record<string, unknown> =>
  modelConfig({
    ...over,
    providers: {
      cloud: {
        enabled: true, readiness: 'needs-setup',
        detail: 'Google credentials are still needed. Non-model parts of Virgil continue to work.',
        models: { deep: { modelId: 'gemini-3.7-flash', maxInputTokens: 1_048_576 } },
        setup: { editable: true, managed: false, credential: 'missing', check: 'available' },
      },
      ...(over.providers ?? {}),
    },
  });

/**
 * The spend receipt, computed the way the service computes it.
 *
 * The status is derived here from the limit and the cloud row rather than
 * passed in, for the same reason `modelConfig` carries real numbers: a fixture
 * that let a test say `status: 'exhausted'` with 12 tokens used against a limit
 * of 50,000 would let the panel pass a test against a receipt the service can
 * never send. `model-budget-endpoints.test.ts` in the runner is what holds the
 * real state machine to these rules.
 */
const BUDGET_SINCE = minutesAgo(30);

const spendRow = (over: Record<string, number> = {}): Record<string, number> =>
  ({ calls: 0, inputTokens: 0, outputTokens: 0, issuedNotReturned: 0, ...over });

const budgetReceipt = (over: {
  limit?: number | null;
  cloud?: Record<string, number>;
  local?: Record<string, number>;
  cli?: Record<string, number>;
  since?: string | null;
} = {}): Record<string, unknown> => {
  const connections = {
    cloud: spendRow(over.cloud), local: spendRow(over.local), cli: spendRow(over.cli),
  };
  const tokens = (row: Record<string, number>): number => row['inputTokens']! + row['outputTokens']!;
  // Only the guarded connection counts against the limit. Local and CLI are on
  // the receipt and are never in `used` — the panel must not add them in.
  const used = tokens(connections.cloud);
  const totalTokens = tokens(connections.cloud) + tokens(connections.local) + tokens(connections.cli);
  const limit = over.limit ?? null;
  const status = limit === null ? 'off'
    : used >= limit ? 'exhausted'
      : used >= limit * 0.8 ? 'warning' : 'ok';
  const since = over.since === undefined ? BUDGET_SINCE : over.since;
  return {
    budget: limit === null ? null
      : { limit, unit: 'tokens', window: 'total', setAt: BUDGET_SINCE },
    state: {
      status, limit, unit: 'tokens', window: 'total', used,
      remaining: limit === null ? null : Math.max(0, limit - used),
      fraction: limit === null ? null : Math.round((used / limit) * 10_000) / 10_000,
      warnAtFraction: 0.8, guards: ['cloud'],
      setAt: limit === null ? null : BUDGET_SINCE, since,
    },
    spend: { since, connections },
    totalTokens,
    notes: [
      'Spend is counted in tokens, not money. This build carries no price table, so a currency figure would be invented.',
      'The limit guards the Cloud/API connection, which is the only one that costs money. Local and Agent CLI calls are counted here and are never stopped by it.',
    ],
  };
};

const openModels = async (
  t: TestContext, over: Table = {}, store: Record<string, unknown> = {},
  browser: Omit<ChromeStubOptions, 'store'> = {},
): Promise<Panel> => {
  const p = await openSettings(t, {
    'GET /model-config': modelConfig(), 'GET /model-budget': budgetReceipt(), ...over,
  }, store, browser);
  await clickButton(p.app, 'Advanced');
  return p;
};

