test('Settings hydration is not unsent work until trusted input differs from service truth', async (t) => {
  const p = await openModels(t, { 'GET /model-budget': budgetReceipt({ limit: 500_000 }) });
  const field = find(p.app, '#model-budget-limit');
  assert.equal(field.value, '500000');

  field.value = '600000';
  await field.fireEvent('input', { isTrusted: false });
  const hydrated = await p.dom.fireWindowEvent('beforeunload');
  assert.equal(hydrated.defaultPrevented, false,
    'programmatic Settings hydration created a false unsent-work warning');

  await field.fireEvent('input');
  const edited = await p.dom.fireWindowEvent('beforeunload');
  assert.equal(edited.defaultPrevented, true, 'a person’s unsaved budget edit was not protected');

  field.value = '500000';
  await field.fireEvent('input');
  const restored = await p.dom.fireWindowEvent('beforeunload');
  assert.equal(restored.defaultPrevented, false,
    'returning to the authoritative value still counted as unsent work');
});

/** The budget section alone, which is what every test below reads. */
const budgetSection = (p: Panel): El => find(p.app, '.model-budget-settings');

/** `GET /usage`, in the shape defined by the usage-accounting contract. */
const usageReport = (over: Record<string, unknown> = {}): Record<string, unknown> => ({
  runAt: '2026-08-24T12:00:00.000Z',
  llm: {
    totals: { calls: 10, inputTokens: 12_421, outputTokens: 3_101 },
    byLane: {
      taps: { calls: 2, inputTokens: 900, outputTokens: 120 },
      runs: { calls: 7, inputTokens: 11_500, outputTokens: 2_980 },
      setup: { calls: 1, inputTokens: 21, outputTokens: 1 },
    },
    rows: [],
  },
  embed: {
    totals: { calls: 3, inputs: 21, inputChars: 4_000 },
    byLane: {
      taps: { calls: 1, inputs: 4, inputChars: 400 },
      runs: { calls: 2, inputs: 17, inputChars: 3_600 },
    },
    rows: [],
  },
  notes: [],
  ...over,
});

