test('SB-250: Models separates startup work from learner taps and board runs', async (t) => {

  const p = await openModels(t, { 'GET /usage': usageReport() });
  const usage = find(p.app, '.model-usage-settings');
  const rows = usage.querySelectorAll('.usage-row').map((r) => text(r));
  assert.equal(rows.length, 4, 'the split is three honest lanes and one total');
  assert.match(rows[0]!, /Things you pressed/);
  assert.match(rows[0]!, /2 calls · 1,020 tokens/);
  assert.match(rows[1]!, /Board runs/);
  assert.match(rows[1]!, /7 calls · 14,480 tokens/);
  assert.match(rows[2]!, /Starting Virgil/);
  assert.match(rows[2]!, /1 call · 22 tokens/);
  assert.match(rows[3]!, /Everything/);
  assert.match(rows[3]!, /10 calls · 15,522 tokens/);
  assert.match(text(usage), /not something you pressed/i);
  // The count is a property of the running service and is not written down, so
  // the screen says so rather than letting it read as a lifetime total.
  assert.match(text(find(usage, '.usage-since')), /since I started up/);
  // Tokens and calls, never a price: this build carries no price table.
  assert.ok(!/[£$€]/.test(text(usage)), text(usage));
  // Reading the board costs embedding calls, and they are not tokens.
  assert.match(text(find(usage, '.usage-embed')), /3 embedding calls over 21 pieces of text/);
  assert.match(text(find(usage, '.usage-embed')), /no token count/);
  // And which of these has a bill behind it, said once.
  assert.match(text(find(usage, '.usage-bills')), /Only Cloud\/API work can bill you/);
});

