test('Settings has five sub-boards and describes the complete model-routing map', async (t) => {
  const receipt = modelConfig();
  const p = await openSettings(t, {
    'GET /health': healthReceipt(), 'GET /model-config': receipt,
  });
  assert.equal(text(find(p.app, '.room-board h1')), 'Settings');
  // "Your data" joined them on 2026-08-29, when the backup, restore and
  // deletion controls stopped being a door of their own in the masthead.
  assert.deepEqual(find(p.app, '.settings-tabs').querySelectorAll('button').map((b) => text(b)),
    ['General', 'Connections', 'Privacy', 'Your data', 'Advanced']);
  const workspace = find(p.app, '.settings-workspace');
  assert.deepEqual(workspace.children.map((child) => child.className),
    ['settings-tabs', 'settings-subboard'],
    'tabs and their sub-board are one board region, not two gap-separated blocks');
  assert.equal(find(p.app, '.settings-tab[aria-current="page"]').textContent, 'General');
  assert.deepEqual(p.app.querySelectorAll('.settings-section h2').map((h) => text(h)),
    ['Boards', 'Processing what you pin']);

  assert.equal(p.app.querySelector('.motion-toggle'), null,
    'the parked animation still has a live Settings control');
  assert.equal(p.c.store['sb_board_motion'], undefined,
    'opening Settings wrote the retired animation preference');

  await clickButton(p.app, 'Advanced');
  const switches = p.app.querySelectorAll('input[name="model-provider"]');
  assert.deepEqual(switches.map((choice) => choice.value), ['cloud', 'local', 'cli']);
  assert.deepEqual(switches.map((choice) => choice.getAttribute('role')), ['switch', 'switch', 'switch']);
  assert.deepEqual(switches.map((choice) => choice.getAttribute('aria-label')),
    ['Turn Cloud/API off', 'Turn Local on', 'Turn Agent CLI on']);
  assert.deepEqual(switches.map((choice) => choice.checked), [true, false, false]);
  assert.match(text(find(p.app, '[data-model-choice="cloud"]')), /Google · Recommended/);
  assert.match(text(find(p.app, '[data-model-choice="cloud"]')), /recommended setup for most people/);
  assert.match(text(find(p.app, '[data-model-choice="local"]')), /Runs on your computer/);
  assert.match(text(find(p.app, '[data-model-choice="cli"]')), /Agent CLI.*Quick setup \/ testing/);
  assert.match(text(find(p.app, '[data-model-choice="cli"]')),
    /installed agent or harness.*real model work.*not Virgil's general default/);
  assert.match(text(find(p.app, '[data-model-choice="cli"]')),
    /Agent work.*computer tools.*bulk imports become drafts.*Sorting returns a preview.*\/agent\/capabilities/);
  assert.equal(find(p.app, '[data-endpoint-for="cli"] input').getAttribute('readonly'), '');
  assert.equal(p.app.querySelectorAll('select[data-model-route]').length, 3,
    'each workload has one assignment control rather than three repeated provider groups');
  for (const route of ['quick', 'deep', 'images']) {
    const choice = find(p.app, `select[data-model-route="${route}"]`);
    assert.equal(choice.value, 'cloud');
    assert.deepEqual(choice.querySelectorAll('option').map((option) => option.value), ['cloud', 'local', 'cli']);
  }
  assert.equal(button(p.app, 'Save changes').disabled, true, 'an unchanged receipt is not saveable');
  assert.match(text(find(p.app, '.recommended-model')), /token backstop, not a currency bill/);
  assert.equal((button(p.app, 'Use recommended settings') as unknown as { hidden: boolean }).hidden, true,
    'the already-active preset still asks to be applied');
  assert.equal(p.app.querySelector('.subboard-intro'), null,
    'Settings explanations became loose gap-separated blocks again');
  assert.doesNotMatch(text(find(p.app, '[data-settings-panel="models"]')), /hackathon/i,
    'internal submission context leaked into learner-facing Settings copy');
  assert.equal(find(p.app, '#cloud-api-key').getAttribute('type'), 'password');
  assert.equal(find(p.app, '#cloud-api-key').value, '', 'the service receipt never returns the saved key');
  assert.doesNotMatch(text(find(p.app, '[data-settings-panel="models"]')),
    /Virgil can use more than one model source|Every kind of work has one home/i);
  assert.equal(p.app.querySelector('[name="shell-command"]'), null, 'Settings exposed a command field');

  await clickButton(p.app, 'Privacy');
  assert.deepEqual(p.app.querySelectorAll('.settings-section h2').map((h) => text(h)),
    ['Page activity', 'Excluded sites']);
  assert.equal(text(find(p.app, '.setting-state-line')), 'Watching for what you keep coming back to.');
  assert.deepEqual(find(p.app, '[data-choices]').querySelectorAll('button').map((b) => text(b)),
    ['For an hour', 'For four hours', 'Until tomorrow', 'Until I turn it back on']);

  await clickButton(p.app, 'Connections');
  assert.deepEqual(p.app.querySelectorAll('.connection-group h2').map((h) => text(h)),
    ['Virgil account', 'Virgil service']);
  assert.match(text(find(p.app, '[data-settings-panel="connections"]')),
    /Virgil account.*Not available in this build.*Virgil service.*Connected/);
  assert.equal(p.app.querySelector('.subboard-intro'), null,
    'Connections explanation became a loose gap-separated block again');
});

test('model switches and exactly-one route controls save one atomic map', async (t) => {
  const initial = modelConfig({
    providers: { local: {
      enabled: true, readiness: 'ready', detail: 'The local endpoint answered.',
      endpoint: 'http://127.0.0.1:11434',
    } },
  });
  const p = await openModels(t, {
    'GET /model-config': initial,
    'PUT /model-config': (init: RequestInit | undefined) => {
      const body = JSON.parse(String(init?.body)) as ModelFixture;
      return modelConfig({
        providers: {
          cloud: { enabled: body.providers?.cloud?.enabled, readiness: 'ready', detail: 'Google is configured.' },
          local: { ...body.providers?.local, readiness: 'ready', detail: 'The local endpoint answered.' },
          cli: { ...body.providers?.cli, readiness: 'ready', detail: 'The Agent CLI endpoint answered.' },
        },
        routes: body.routes ?? { quick: 'cloud', deep: 'cloud', images: 'cloud' },
      });
    },
  });

  const cliSwitch = find(p.app, 'input[name="model-provider"][value="cli"]');
  cliSwitch.checked = true;
  await cliSwitch.fireEvent('change');
  const localQuick = find(p.app, 'select[data-model-route="quick"]');
  localQuick.value = 'local';
  await localQuick.fireEvent('change');
  assert.equal(localQuick.value, 'local');
  const cliDeep = find(p.app, 'select[data-model-route="deep"]');
  cliDeep.value = 'cli';
  await cliDeep.fireEvent('change');
  await typeInto(find(p.app, '[data-endpoint-for="local"] input'), 'http://localhost:11434 ');
  await typeInto(find(p.app, '[data-endpoint-for="cli"] input'), 'http://localhost:8798 ');
  assert.equal(button(p.app, 'Save changes').disabled, false);

  await clickButton(p.app, 'Save changes');
  const saved = p.requests.findLast((request) => request.method === 'PUT' && request.url.endsWith('/model-config'));
  assert.deepEqual(saved?.body, {
    providers: {
      cloud: { enabled: true },
      local: { enabled: true, endpoint: 'http://localhost:11434' },
      cli: { enabled: true, endpoint: 'http://localhost:8798' },
    },
    routes: { quick: 'local', deep: 'cli', images: 'cloud' },
  });
  assert.equal(text(find(p.app, '.model-status')), 'Saved. New model work will follow this map.');
  assert.equal(button(p.app, 'Save changes').disabled, true, 'the returned receipt becomes authoritative');
  assert.equal(button(p.app, 'Use recommended settings').disabled, false,
    'a successful custom save left the recovery preset disabled');
});

