test('removing a Cloud key names every saved route before one confirmed write', async (t) => {
  const removed = modelConfigWithoutCloudKey();
  const p = await openModels(t);
  const cloud = find(p.app, '[data-cloud-credential]');
  await clickButton(cloud, 'Remove saved key');

  const confirm = find(cloud, '.credential-remove-confirm');
  assert.match(text(confirm), /Quick tasks, Deep tasks and Images are routed here/);
  assert.match(text(confirm), /will stop until you save another key or move those routes/);
  assert.match(text(confirm), /routing map, board, waiting captures and saved work stay/);
  assert.match(text(confirm), /will not fall back/);
  assert.equal(paths(p).filter((path) => path === 'DELETE /model-connections/cloud/credential').length, 0);
  assert.equal(p.dom.activeElement, button(confirm, 'Remove key'));

  await clickButton(confirm, 'Keep key');
  assert.equal(p.dom.activeElement, button(cloud, 'Remove saved key'));
  assert.equal(paths(p).filter((path) => path === 'DELETE /model-connections/cloud/credential').length, 0);

  await clickButton(cloud, 'Remove saved key');
  const nextRoutes = home({
    'GET /model-config': removed, 'GET /model-budget': budgetReceipt(),
    'DELETE /model-connections/cloud/credential': removed,
  });
  const immediate = serve(nextRoutes);
  let release!: (response: FakeResponse) => void;
  const delayed = new Promise<FakeResponse>((resolve) => { release = resolve; });
  p.c.fetchHandler = (url, init) => {
    const path = url.startsWith(SERVICE) ? url.slice(SERVICE.length) : url;
    if (`${init?.method ?? 'GET'} ${path}` === 'DELETE /model-connections/cloud/credential') return delayed;
    return immediate(url, init);
  };
  const finalConfirm = find(cloud, '.credential-remove-confirm');
  const remove = button(finalConfirm, 'Remove key');
  const pending = remove.fireEvent('click');
  await Promise.resolve();
  assert.equal(remove.disabled, true);
  assert.equal(button(finalConfirm, 'Keep key').disabled, true);
  assert.equal(finalConfirm.getAttribute('aria-busy'), 'true');
  release(jsonResponse(removed));
  await pending;
  await settle();

  assert.equal(paths(p).filter((path) => path === 'DELETE /model-connections/cloud/credential').length, 1);
  assert.match(text(find(p.app, '.model-status')), /Quick tasks, Deep tasks and Images are still routed to Cloud\/API/);
  assert.equal(text(find(p.app, '[data-model-provider="cloud"] .model-readiness')), 'Needs setup');
  assert.deepEqual(p.app.querySelectorAll('select[data-model-route]').map((route) => route.value),
    ['cloud', 'cloud', 'cloud']);
  assert.equal(p.dom.activeElement, find(p.app, '#cloud-api-key'));
});

