/**
 * NOTEBOOK_SEAM_V2.md §7 — the Drive block, drawn once and then never again.
 *
 * The two facts worth a machine's opinion. **Absent is off**: a service with no
 * Drive lane answers 404, and the screen has to draw nothing rather than a
 * greyed-out block advertising an unmade choice as a missing feature. And **the
 * screen does not move on until the documents exist** (§7 step 2), so the folder
 * link only appears once the service says it has written them.
 *
 * No credential is in this file. `test-client` and `test-secret` are what a
 * pasted OAuth client looks like to a stub.
 */
const DRIVE_DOCS = [
  { key: 'learn-now', title: 'Virgil: learn now' },
  { key: 'on-the-board', title: 'Virgil: on the board' },
  { key: 'archive', title: 'Virgil: archive' },
];

/** The ordinary case: a build that carries a Google sign in, so the learner has
 *  one button and nothing to fill in. Pass `client: { configured: false, … }`
 *  for the only other state there is. */
const driveStatus = (over: Record<string, unknown> = {}): Record<string, unknown> => ({
  available: true,
  client: { configured: true, source: 'shipped' },
  connection: { connected: false, connectedAt: null, scope: null },
  folder: null,
  connect: { state: 'idle', detail: '' },
  documents: DRIVE_DOCS,
  lastWrite: null,
  ...over,
});

const openConnections = async (
  t: TestContext, over: Table = {}, store: Record<string, unknown> = {},
  browser: Omit<ChromeStubOptions, 'store'> = {},
): Promise<Panel> => {
  const p = await openSettings(t,
    { 'GET /health': healthReceipt(), 'GET /model-config': modelConfig(), ...over }, store, browser);
  await clickButton(p.app, 'Connections');
  return p;
};

