test('with a Google sign in present, the block leads with value and offers one control', async (t) => {
  const p = await openConnections(t, { 'GET /notebook/drive': driveStatus() });
  const block = find(p.app, '.drive-settings');
  assert.deepEqual(p.app.querySelectorAll('.connection-group h2').map((h) => text(h)),
    ['Virgil account', 'Your documents, in your own Drive', 'Virgil service']);

  assert.match(text(find(block, '.drive-value')), /Virgil keeps three documents in a folder in your Drive/);
  assert.match(text(find(block, '.drive-consent')), /create and open files that Virgil creates/);
  assert.match(text(find(block, '.drive-consent')), /does not reach anything else in your Drive/);
  // §2's law on the surface: Google's claim as Google's, and what Virgil can
  // actually tell them instead.
  assert.match(text(find(block, '.drive-notebook')), /Virgil cannot see your notebook/);

  // Exactly one control, and it is the one that does the thing.
  assert.deepEqual(block.querySelectorAll('button').map((b) => text(b)), ['Connect Drive']);
  assert.equal(text(find(block, '.drive-badge')), 'Not connected');
});

