test('Connect opens Google\'s own consent screen and waits rather than claiming anything', async (t) => {
  let asked = 0;
  const p = await openConnections(t, {
    'GET /notebook/drive': () => {
      asked += 1;
      return asked === 1
        ? driveStatus({ client: { configured: true, source: 'saved', editable: true, managed: false } })
        : driveStatus({
          client: { configured: true, source: 'shipped' },
          connect: { state: 'waiting', detail: 'Waiting for you to give permission in your browser.' },
        });
    },
    'POST /notebook/drive/connect': { ok: true, url: 'https://accounts.google.com/o/oauth2/v2/auth?x=1' },
  });
  const block = find(p.app, '.drive-settings');
  await clickButton(block, 'Connect Drive');

  assert.deepEqual(p.dom.openedTabs.filter((tab) => !tab.closed).map((tab) => tab.url),
    ['https://accounts.google.com/o/oauth2/v2/auth?x=1']);
  assert.deepEqual(p.c.tabsCreated, [],
    'the service-hosted page still depended on the extension-only tabs API');
  // The folder cannot be shown yet, because it does not exist yet.
  assert.equal(block.querySelector('.drive-folder a'), null);
  // Three states, and they are three different facts: waiting on a consent
  // screen, writing the documents, and done. The badge says which.
  assert.equal(text(find(block, '.drive-badge')), 'Waiting for Google');
  assert.match(text(find(block, '.drive-detail')), /permission in your browser/);

  // Leaving the screen stops the asking. A learner who walks away mid-consent
  // must not leave a request going to their own service every second for the
  // rest of the consent window.
  const askedWhileWatching = asked;
  await clickButton(p.app, 'General');
  assert.equal(p.app.querySelector('.drive-settings'), null);
  await settle();
  assert.equal(asked, askedWhileWatching, 'the block went on polling after it left the screen');
});

