test('once the service says it has written them, the folder and the three titles appear', async (t) => {
  const p = await openConnections(t, {
    'GET /notebook/drive': driveStatus({
      client: { configured: true, source: 'shipped' },
      connection: { connected: true, connectedAt: '2026-08-25T03:00:00.000Z', scope: 'x' },
      folder: { link: 'https://drive.google.com/drive/folders/folder-1' },
      connect: { state: 'connected', detail: 'I rewrote all 3 documents in your Google Drive.' },
      lastWrite: {
        ok: true,
        line: 'I rewrote all 3 documents in your Google Drive, in a folder called Virgil.',
        docs: DRIVE_DOCS.map((d) => ({ ...d, written: true, at: 'file-1', bytes: 10, error: null })),
      },
    }),
  });
  const block = find(p.app, '.drive-settings');

  assert.equal(text(find(block, '.drive-badge')), 'Connected');
  assert.equal(find(block, '.drive-folder a').getAttribute('href'),
    'https://drive.google.com/drive/folders/folder-1');
  // §7 step 4 is theirs, and it is an instruction about another product.
  assert.match(text(block), /In Gemini Notebook: make a notebook, choose Google Drive as the source/);
  assert.deepEqual(block.querySelectorAll('.drive-documents li').map((li) => text(li)),
    DRIVE_DOCS.map((d) => d.title));
  // §11, and §2's law: Virgil may say when it last wrote and nothing else.
  assert.match(text(find(block, '.drive-last-write')), /I rewrote all 3 documents/);
  for (const banned of [/up to date/i, /\bsynced\b/i, /\bintegrated\b/i, /\blinked\b/i]) {
    assert.doesNotMatch(text(block), banned, `the Drive block claimed ${banned}`);
  }
});

test('a document that did not get written says which one and why, in plain words', async (t) => {
  const p = await openConnections(t, {
    'GET /notebook/drive': driveStatus({
      client: { configured: true, source: 'shipped' },
      connection: { connected: true, connectedAt: '2026-08-25T03:00:00.000Z', scope: 'x' },
      folder: { link: 'https://drive.google.com/drive/folders/folder-1' },
      connect: { state: 'connected', detail: 'done' },
      lastWrite: {
        ok: false,
        line: 'I rewrote 2 of 3 documents in your Google Drive, in a folder called Virgil. '
          + 'I could not write: Virgil: archive. Those are still there, and what they say is out of date.',
        docs: DRIVE_DOCS.map((d) => (d.key === 'archive'
          ? { ...d, written: false, at: null, bytes: 0, error: 'There is no room left in your Google Drive, so I could not write it.' }
          : { ...d, written: true, at: 'file-1', bytes: 10, error: null })),
      },
    }),
  });
  const block = find(p.app, '.drive-settings');
  const rows = block.querySelectorAll('.drive-write-rows li');
  assert.equal(rows.length, 3, 'one row per document offered, always');
  const failed = rows.filter((li) => li.getAttribute('data-written') === 'no');
  assert.equal(failed.length, 1);
  assert.match(text(failed[0]!), /no room left in your Google Drive/);
  // The failure mode this seam has that nothing else does is that failure looks
  // exactly like success. It may not be rounded to either.
  assert.doesNotMatch(text(block), /up to date/i);
});

test('forgetting a Drive says the documents stay, and only then asks the service', async (t) => {
  const p = await openConnections(t, {
    'GET /notebook/drive': driveStatus({
      client: { configured: true, source: 'shipped' },
      connection: { connected: true, connectedAt: '2026-08-25T03:00:00.000Z', scope: 'x' },
      folder: { link: 'https://drive.google.com/drive/folders/folder-1' },
      connect: { state: 'connected', detail: 'done' },
      lastWrite: null,
    }),
    'POST /notebook/drive/disconnect': driveStatus({
      client: { configured: true, source: 'shipped' },
    }),
  });
  const block = find(p.app, '.drive-settings');
  await clickButton(block, 'Forget my Drive');

  // §13: nothing in Drive is touched, and the learner is told that before they
  // press it rather than after.
  const confirm = text(find(block, '.confirm'));
  assert.match(confirm, /The three documents stay exactly where they are/);
  assert.match(confirm, /does not delete anything of yours/);
  assert.equal(p.requests.some((r) => r.url.endsWith('/notebook/drive/disconnect')), false,
    'the disconnect fired before the sentence about it was shown');

  await clickButton(find(block, '.confirm'), 'Forget it');
  assert.ok(p.requests.some((r) => r.method === 'POST' && r.url.endsWith('/notebook/drive/disconnect')));
  assert.equal(text(find(block, '.drive-badge')), 'Not connected');
  assert.equal(block.querySelector('.drive-folder a'), null);
});

