  // a guess typed over a blank.
  assert.equal(find(section, '#model-budget-limit').value, '50000');
  assert.equal(find(section, '.budget-clear').getAttribute('data-visible'), 'true');
  assert.match(text(find(section, '.budget-window')), /This window opened 30 min ago\./);
