test('the budget warns in the one colour this product warns in, and draws no bar', () => {
  /**
   * Amber is the only alarm colour in this stylesheet. A budget is the first
   * thing in the product with a genuine threshold in it, which makes it the
   * first thing that could plausibly grow a red — and the moment a red exists
   * beside `--warn`, neither colour means anything definite.
   *
   * The other half is the bar. SB-33 refuses progress bars and the Check room's
   * meter note says why: a thing that fills up reads as a countdown. A budget
   * bar would be worse than the Check room's, because at the end of this one
   * something really does stop — and it would still be the wrong picture, since
   * what stops is one connection out of three.
   */
  const css = readFileSync(fileURLToPath(new URL('../../panel.css', import.meta.url)), 'utf8');
  const block = css.slice(css.indexOf('--- the spend limit'), css.indexOf('.repair-choice textarea.domains'));
  assert.ok(block.length > 400, 'the budget stylesheet block moved and this assertion stopped reading it');

  // The comments in the block say the words "progress bar" and "meter" on
  // purpose, so the rules are read without them.
  // The slice starts inside the block's own opening comment, so the tail of it
  // goes first and the inner comments go after.
  const rules = block.slice(block.indexOf('*/') + 2).replace(/\/\*[\s\S]*?\*\//g, '');

  assert.deepEqual([...rules.matchAll(/#[0-9a-fA-F]{3,8}\b|\b(?:red|crimson|tomato|orange)\b/g)].map((m) => m[0]), [],
    'a literal colour in the budget block is a second alarm colour by another name');
  assert.match(rules, /\.budget-state\[data-budget-status="warning"\],\s*\n\.budget-state\[data-budget-status="exhausted"\] \{[^}]*var\(--warn\)/,
    'the two states that need looking at do not use the house warning block');
  assert.doesNotMatch(rules, /\.budget-state\[data-budget-status="ok"\]/,
    'an ordinary state was given a colour, which makes not-warning into an achievement');
  assert.doesNotMatch(rules, /(?:^|[\s,{}])(?:progress|meter)\b/,
    'the budget grew a bar element');
  // The other way a bar gets drawn: a box whose width is the fraction.
  assert.deepEqual([...rules.matchAll(/(?:^|[\s;{])width:\s*([^;]+);/g)].map((m) => m[1]!.trim())
    .filter((value) => value !== '100%'), [],
    'something in the budget block is sized by anything other than its container');

  // A line with nothing to say occupies nothing, the way the Check room's do.
  assert.match(block, /\.budget-unreturned:empty \{[^}]*display:\s*none/);
  assert.match(block, /\.budget-status:empty \{[^}]*display:\s*none/);
});

test('the off switch has no deadline on it, and sends one the detector will honour (the collection-pause contract)', async (t) => {
  const p = await openPrivacy(t, { 'PUT /prefs': prefs({ pausedUntil: PAUSE_INDEFINITELY }) });
  await clickButton(find(p.app, '[data-choices]'), 'Until I turn it back on');

  const req = p.requests[p.requests.length - 2]!;
  assert.equal(req.method, 'PUT');
  assert.deepEqual(req.body, { pausedUntil: PAUSE_INDEFINITELY });
  // Same breath as every other pause: the service is the authority, the worker
  // holds a cache, and a pause the cache has not heard about is a pause the
  // detector ignores.
  assert.deepEqual(p.pushed, [{ kind: PREFS_CHANGED }]);
});

test('an untimed pause reads as off rather than as a countdown nobody can parse', async (t) => {
  const p = await openPrivacy(t, {
    'GET /prefs': prefs({ pausedUntil: PAUSE_INDEFINITELY }), 'PUT /prefs': prefs(),
  });
  assert.equal(text(find(p.app, '.setting-state-line')), 'Paused until you turn it back on.');
  assert.deepEqual(find(p.app, '[data-choices]').querySelectorAll('button').map((b) => text(b)),
    ['Start again now']);
  await clickButton(find(p.app, '[data-choices]'), 'Start again now');
  assert.deepEqual(p.requests[p.requests.length - 2]!.body, { pausedUntil: null });
});

// ------------------------------------------- the paused banner, on the main page

/**
 * The collection-pause contract's other half, and the reason the off switch could be given at all.
 *
 * The privacy screen is two taps behind a link at the bottom of the panel, so
 * before this the only way to find out that collection was off was to go looking
 * for it — which is fine for an hour's pause that ends by itself and useless for
 * one that does not. The state now lives where the learner already is.
 */
test('a paused panel says so on the first screen, above the session, with the way back on it', async (t) => {
  const p = await open(t, home({ 'GET /prefs': prefs({ pausedUntil: PAUSE_INDEFINITELY }) }));
  const banner = find(p.app, '[data-zone="paused"]');
  assert.equal(text(find(banner, 'h2')), 'Paused until you turn it back on.');
  assert.match(text(banner), /Pinning something yourself still works\./);

  // Not buried: §5's rule is that nothing may push zone 1 DOWN the page, and
  // this is the one thing that outranks it — while collection is off, "is it
  // off?" is a more urgent fact than what is on this run, and it is one line.
  const zones = p.app.querySelectorAll('[data-zone]').map((z) => z.getAttribute('data-zone'));
  assert.equal(zones[0], 'paused');
  // The next move is still there underneath it, and it is still the session.
  assert.equal(text(find(p.app, '.next-action h1')), lineupNow());
});

test('resuming from the banner is one tap, and it is the same write the privacy screen makes', async (t) => {
  // The service remembers, because the assertion is that the panel re-reads it
  // rather than assuming its own write landed.
  let pausedUntil: string | null = PAUSE_INDEFINITELY;
  const p = await open(t, home({
    'GET /prefs': () => prefs({ pausedUntil }),
    'PUT /prefs': (init: RequestInit | undefined) => {
      pausedUntil = (JSON.parse(String(init?.body)) as { pausedUntil: string | null }).pausedUntil;
      return prefs({ pausedUntil });
    },
  }));
  await clickButton(find(p.app, '[data-zone="paused"]'), 'Start again now');

  assert.deepEqual(p.requests.filter((r) => r.method === 'PUT')[0]!.body, { pausedUntil: null });
  assert.deepEqual(p.pushed, [{ kind: PREFS_CHANGED }]);
  // The screen re-reads the authority rather than assuming its own write, and
  // the banner is gone because the authority says it is gone.
  assert.equal(p.app.querySelectorAll('[data-zone="paused"]').length, 0);
});

