test('pausing writes to the service and tells the worker in the same breath', async (t) => {
  const p = await openPrivacy(t, { 'PUT /prefs': prefs({ pausedUntil: '2026-08-20T13:00:00.000Z' }) });
  const at = Date.now();
  await clickButton(find(p.app, '[data-choices]'), 'For an hour');

  const req = p.requests[p.requests.length - 2]!;
  assert.equal(req.url, `${SERVICE}/prefs`);
  assert.equal(req.method, 'PUT');
  const until = Date.parse((req.body as { pausedUntil: string }).pausedUntil);
  assert.ok(Math.abs(until - (at + 60 * 60_000)) < 5_000, 'an hour from now');
  // The service is the authority and `sb_prefs` is a cache of it. Pressing
  // Pause and having the next page observed anyway is exactly the kind of thing
  // that makes a control worthless, so the worker is told rather than waiting
  // for its refresh alarm.
  assert.deepEqual(p.pushed, [{ kind: PREFS_CHANGED }]);
  assert.equal(paths(p)[paths(p).length - 1], 'GET /prefs', 'the screen re-reads the authority');
});

