// ============================================ the worker's half of PREFS_CHANGED

test('the panel is the only side that speaks: it pushes, and never listens', async (t) => {
  const p = await openPrivacy(t, { 'PUT /prefs': prefs() });
  await clickButton(find(p.app, '[data-choices]'), 'For an hour');
  assert.deepEqual(p.pushed, [{ kind: PREFS_CHANGED }]);
  // Documenting a real gap rather than asserting a virtue. `panel.ts` registers
  // no `runtime.onMessage` listener at all, so a prefs change made anywhere else
  // — the alarm refresh, a second panel, a future setting — does not reach an
  // open panel. Today nothing else writes prefs, so nothing is wrong on screen;
  // the moment something does, this screen will be confidently stale.
  const listeners = (globalThis as unknown as {
    chrome: { runtime: { onMessage: { listeners: unknown[] } } };
  }).chrome.runtime.onMessage.listeners;
  assert.equal(listeners.length, 1, 'only the stand-in worker installed by the test');
});

