// ====================================== everything on this screen came off a page

/**
 * The panel builds itself out of template strings, and almost every value in
 * them came from a web page the learner was reading, a title the site chose, or
 * a name they typed themselves. `esc()` is unit-tested next door as a string
 * function; these are the assertions that it is actually reached — in text
 * position and in attribute position — because a real parser is on the other
 * side of it here rather than an equality check.
 */
const NASTY = '<img src=x onerror="boom()">';

test('a topic label out of a page title is text, not markup', async (t) => {
  const p = await openOnBoard(t, home({
    'GET /board': { topics: [topic('t1', NASTY), topic('t2', 'Other')], suggestions: [] },
  }));
  assert.equal(text(find(p.app, '.card .label')), NASTY);
  assert.equal(p.app.querySelectorAll('img').length, 0);
});

test('a passage lifted off a page is quoted, not executed', async (t) => {
  const p = await openOnBoard(t, home({
    'GET /board': { topics: [], suggestions: [{ ...suggestion, passage: NASTY, reason: NASTY }] },
  }));
  assert.equal(text(find(p.app, 'blockquote')), NASTY);
  assert.equal(p.app.querySelectorAll('img').length, 0);
});

test('a long passage is a quotation, not the whole page', async (t) => {
  const passage = `${'a'.repeat(300)}TAIL`;
  const p = await openOnBoard(t, home({
    'GET /board': { topics: [], suggestions: [{ ...suggestion, passage }] },
  }));
  const quoted = text(find(p.app, 'blockquote'));
  assert.equal(quoted.length, 240);
  assert.ok(!quoted.includes('TAIL'));
});

test('a section the model wrote is shown as prose whatever it contains', async (t) => {
  const p = await open(t, home({
    'GET /session': { session: session({ sections: [section({ heading: NASTY, body: NASTY })] }), card: card() },
  }));
  await clickButton(p.app, 'Start');
  assert.equal(text(find(p.app, '.section .lesson-area')), NASTY);
  assert.equal(text(find(p.app, '.section .body')), NASTY);
  assert.equal(p.app.querySelectorAll('img').length, 0);
});

test('an id that would break out of its own attribute comes back intact', async (t) => {
  const pinId = 'p" onclick="boom()';
  const p = await openBoardTopic(t, {
    'GET /topics/t1/pins': { pins: [
      { id: pinId, title: 'One', gist: 'g' }, { id: 'p2', title: 'Two', gist: 'g' },
    ] },
    'POST /topics/t1/split': { ok: true },
  });
  const topicEl = find(p.app, '.card');
  await clickButton(topicEl, 'Split…');
  const form = find(topicEl, '.repair-choice');
  const box = form.querySelectorAll('input[type=checkbox]')[0]!;
  assert.equal(box.getAttribute('onclick'), null, 'no attribute was smuggled in');
  box.checked = true;
  find(form, '.name').value = 'Handshakes';
  await clickButton(form, 'Continue');
  await clickButton(topicEl, 'Split');
  // The round trip is the point: escaped into the attribute, read back off it,
  // and sent to the service as the id the service gave us.
  assert.deepEqual(lastWrite(p)!.body, { pinIds: [pinId], label: 'Handshakes' });
});

test('a resumed session opens the same way a new one does', async (t) => {
  const p = await open(t, home({
    'GET /session': { session: session({ sections: [section({ completed: true }), section({ topicId: 't2', heading: 'Why forward secrecy' })] }), card: card() },
    'GET /today': {
      next: { ...NEXT_SESSION, primary: { ...NEXT_SESSION.primary, cta: 'Continue' } },
    },
  }));
  await clickButton(p.app, 'Continue');
  // It opens at the lesson they stopped on, and the one they finished is in the
  // rail rather than discarded. Nothing is re-fetched to draw either.
  assert.deepEqual(p.app.querySelectorAll('.section .lesson-area').map((h) => text(h)),
    ['Why forward secrecy']);
  assert.deepEqual(find(p.app, '.room-rail').querySelectorAll('[data-list="done"] .rail-name').map((n) => text(n)),
    ['How TLS gets its keys']);
  assert.deepEqual(paths(p), [...FIRST_PAINT, 'GET /sessions/sess-1/recap']);
});

// ================================================== the main page (UX_SPEC §5)

/**
 * SB-68 — the panel reads top to bottom as this run, momentum, flagged, door.
 *
 * The stub is a DOM without a layout, so it cannot tell you anything fits in
 * 400 pixels. What it can tell you is the thing the hierarchy actually rests
 * on: which zone comes first, that nothing unbounded is rendered above the
 * session card, and that the two zones which can be empty are absent rather
 * than present-and-empty. Those are the properties that decide whether zone 1
 * is on screen when the panel opens.
 */
const zones = (p: Panel): string[] =>
  p.app.querySelectorAll('[data-zone]').map((z) => z.getAttribute('data-zone') ?? '');

const milestone = (over: RawSection = {}): RawSection => ({
  kind: 'milestone', topicLabel: 'IAM conditions', from: 'building', to: 'fluent',
  evidence: 'Demonstrated 3 times across 2 weeks.', at: '2026-08-18T21:00:00.000Z', ...over,
});

test('SB-68: the order of the zones is the hierarchy, and it is the same every time', async (t) => {
  const p = await openOnBoard(t, home({
    'GET /progression': { strip: [milestone()] },
    'GET /flagged': { rows: [{ topicId: 't1', topicLabel: 'TLS', source: 'resurface-deeper', at: minutesAgo(60) }], more: 0 },
  }));
  // Zone 3 was a list under the board naming topics that were ON the board, so
  // it became a mark on the topic instead, and a mark is not a zone. The mark
  // is asserted here on the board; the front door's own order is asserted in
  // "nothing may be rendered above this run's session".
  assert.match(text(find(p.app, '.card .flag-note')), /you asked to go deeper/);
});

test('SB-68: nothing may be rendered above this run\'s session', async (t) => {
  /**
   * The suggestion cards used to render above it, so a learner with four
   * proposals opened the panel to four proposals and had to scroll to find the
   * one thing to do this run.
   *
   * The suggestions moved to the board room on 2026-08-23 and the rule holds
   * where it always mattered — on the screen the learner arrives at. Nothing
   * outranks the session there: not the plan, not a burst, not a proposal.
   *
   * Restated on 2026-08-24 for the shape the page actually has. The order the
   * spec rules — the session, then what is due, then five minutes — is one
   * ranking now rather than three stacked zones, and it is decided in the
   * domain where it can be reasoned about. What this asserts is what the rule
   * was always for: the session is the hero, and the rest is under it.
   */
  const p = await open(t, home({
    'GET /today': {
      next: {
        ...NEXT_SESSION,
        alternatives: [NEXT_COMMITMENT.primary, {
          id: 'burst:t1', kind: 'burst', targetId: null, title: 'Take a five-minute recall burst',
          detail: 'One quick check.', minutes: 5, destination: 'burst', cta: 'Start burst',
          reasons: [{ code: 'review-due', text: 'One topic is due for recall.' }], rank: 500,
        }],
      },
    },
  }));

  const order = find(p.app, '.room-board').children.map((c) => c.className.split(/\s+/)[0] ?? c.tagName);
  // The page-face toggle stays in the corner. Current/Lineup replaces the old
  // always-visible time row; session length now belongs inside Lineup.
  assert.equal(order.indexOf('face-toggle'), 0);
  assert.equal(order.indexOf('learn-mode-toggle'), 1);
  // And then the room itself, which is two columns since the dead-space ruling.
  // The hero did not move down the page; the things that were under it moved
  // beside it.
  assert.equal(order.indexOf('room-columns'), 2);
  assert.equal(find(p.app, '.room-main').children[0]?.className.split(/\s+/)[0], 'next-action',
    'the one thing to do is the first thing in the column you read first');
  assert.equal(text(find(p.app, '.next-action h1')), lineupNow());
  // One control at hero size, and the rest are links beside it in the order the
  // service ranked them.
  assert.equal(p.app.querySelectorAll('.primary.big').length, 1);
  // The commitment left the rail with the rework: it is dated work, it is named
  // in the hero's own line, and the Plan is a room with a door. The burst is
  // learning, so it stays.
  assert.deepEqual(p.app.querySelectorAll('.room-rail .alt .what').map((a) => text(a)), [
    'Take a five-minute recall burst · 5 min',
  ]);
  // Still inside the hero's own card: nothing about the rail may put a second
  // thing to press above the one thing to do.
  assert.equal(find(p.app, '.next-action').querySelectorAll('.alt').length, 0);
});

test('§5 zone 2: the strip is absent when nothing happened, not present and empty', async (t) => {
  const p = await open(t, home());
  // An empty momentum strip renders as nothing at all — not a heading with
  // nothing under it, which is content.
  //
  // A momentum strip with nothing in it is a claim about the past that cannot
  // be made. Nothing else on this page draws a zone at all now: the hero is the
  // page, and what used to be a stack of zones under it is one ranked answer.
  assert.deepEqual(zones(p), []);
});

