test('every mark names who put it there and when, on the topic it is about', async (t) => {
  const p = await openOnBoard(t, home({
    'GET /board': { topics: [topic('t1', 'TLS'), topic('t3', 'Firestore indexes')], suggestions: [] },
    'GET /flagged': {
      rows: [
        { topicId: 't1', topicLabel: 'TLS', source: 'resurface-deeper', at: minutesAgo(60 * 26) },
        // `t3`, deliberately: the fixture session covers t1 and t2, and a
        // regression row for a topic the session is already about is dropped by
        // the rule above.
        { topicId: 't3', topicLabel: 'Firestore indexes', source: 'regression', at: minutesAgo(60 * 26) },
      ],
      more: 2,
    },
  }));
  // On the cards, and each on ITS OWN card — which is the property the strip
  // could not have: a list of labels beside a board of the same labels.
  const marked = p.app.querySelectorAll('.card').filter((c) => c.querySelectorAll('.flag-note').length > 0)
    .map((c) => [text(find(c, '.label')), text(find(c, '.flag-note'))]);
  assert.deepEqual(marked, [
    ['TLS', 'you asked to go deeper on this, yesterday'],
    ['Firestore indexes', 'you had this and it has slipped, last seen yesterday'],
  ]);
});

