test('§5 zone 1: a withheld night is named, section by section, and offers no start', async (t) => {
  const p = await open(t, home({
    'GET /today': { next: NEXT_EMPTY },
    'GET /session': {
      session: null,
      card: card({
        state: 'withheld', sessionId: 's1', title: 'How IAM conditions evaluate', minutes: 0,
        registers: [], why: null,
        withheld: [
          { topicId: 'a', heading: 'How IAM conditions evaluate', reason: 'defective' },
          { topicId: 'b', heading: 'Composite index limits', reason: 'unverified' },
        ],
        reason: '1 section failed the check and 1 could not be checked, so they were held back rather than taught.',
      }),
    },
  }));

  assert.equal(text(find(p.app, '.ready h2')), 'Held back for checking');
  assert.deepEqual(find(p.app, '.ready').querySelectorAll('.held').map((w) => text(w)), [
    'How IAM conditions evaluate: the check found a problem',
    'Composite index limits: the check could not run',
  ]);
  assert.equal(p.app.querySelectorAll('button').filter((b) => text(b) === 'Start').length, 0);
  // Named as the product working, not apologised for.
  assert.ok(!/sorry|apolog|unfortunately|failed to/i.test(text(find(p.app, '.ready'))));
  // And the sentence that finishes it. Withholding returns the topic to the
  // pool — `pipeline.ts`: an unshipped section never advances `lastExposedAt` —
  // so a screen that stops at "held back" leaves a learner at a dead end
  // wondering whether their subject is gone.
  assert.match(text(find(p.app, '.ready .next')), /the next time you process/);
});

test('material waiting is on the board, with the control at its foot', async (t) => {

  const p = await openOnBoard(t, home({
    'GET /board': {
      topics: [], suggestions: [],
      unfiled: Array.from({ length: 9 }, (_, i) => ({ id: `p${i}`, title: `Pin ${i}`, gist: '' })),
    },
    'GET /session': {
      session: null,
      card: card({
        state: 'building', sessionId: null, title: 'Being built', minutes: 0,
        registers: [], why: null, withheld: [],
        reason: '9 things on your board, waiting for you to process them.',
      }),
    },
    'GET /batch': {
      run: false, because: 'manual-only', line: '9 things waiting. Press Process when you want them worked through.',
      unprocessedPins: 9, estimatedCalls: 15, autoAfter: null,
    },
  }));
  // No session, so no session zone at all — and no hero announcing its absence.
  assert.equal(p.app.querySelectorAll('[data-zone=session]').length, 0);
  assert.match(text(find(p.app, '[data-area=get-started]')), /Pin 0/);
  const build = button(p.app, 'Process');
  const control = find(p.app, '[data-zone=process]');
  assert.equal(build.parentElement?.parentElement, control);
  assert.equal(control.parentElement?.className, 'board');
  assert.equal(control.parentElement?.children.at(-1), control,
    'the control is not the last thing on the board');
  assert.equal(
    find(find(p.app, '[data-area=get-started]'), '.head').querySelectorAll('[data-zone=process]').length,
    0, 'the control is back on the Get Started heading, which the board face cannot hold');

  await click(build);
  assert.ok(paths(p).includes('POST /batch'), 'pressing it asked for nothing');
});

test('§5 zone 1: the registers present are on the rows, and each row keeps its own reason', async (t) => {
  const p = await open(t, home({
    'GET /session': {
      session: session({
        sections: [
          section({ depth: 'from-nothing', why: 'you have been struggling with this' }),
          section({
            topicId: 't2', heading: 'Why forward secrecy', depth: 'fluent', question: null,
            why: 'due a quick check so it stays put',
          }),
        ],
      }),
      // A colon, never a dash: The learner-controlled lineup contract's copy law, which this fixture used
      // to be the one place in the suite still breaking.
      card: card({ registers: ['from-nothing', 'fluent'], why: 'TLS: you had this, and something recent suggests it has slipped' }),
    },
  }));
  const hero = find(p.app, '.next-action');
  assert.deepEqual(hero.querySelectorAll('.lineup-item .register').map((r) => text(r)),
    ['new to you', 'fluent']);
  // §5's why-line was one sentence about the whole night. It is one sentence
  // per row now, behind the row's own disclosure, so nothing on the screen is
  // a claim about a topic the learner cannot trace to that topic.
  const rows = hero.querySelectorAll('.lineup-item');
  await pressIcon(rows[1] as El, 'Why this?');
  assert.match(text(find(rows[1] as El, '.lineup-why')), /^Due a quick check so it stays put\./);
});

test('the search answers with the board, and costs one read of My studies', async (t) => {
  /**
   * It used to live on the front door: a learner typed on one screen to filter
   * another one they had not seen yet, and pressing the button was the only way
   * to find out what the words had done. Searching the thing in front of you is
   * the ordinary shape.
   *
   * What changed on 2026-08-24 is what "the thing in front of you" means. The
   * box says *"Search what you're learning"* and searched the board's topics
   * alone, so it could not find an unfiled pin printed directly underneath it,
   * and could not reach a course or a piece of material at all. The price of
   * fixing that is one `GET /courses`, taken the first time somebody types and
   * never again — not on arrival, because a learner who never uses the box
   * should not pay for it.
   */
  const p = await openOnBoard(t, home({
    'GET /board': { topics: [topic('t1', 'TLS'), topic('t2', 'Bread hydration')], suggestions: [] },
    'GET /courses': { courses: [] },
  }));
  const before = paths(p).length;
  await typeInto(find(p.app, '.search'), 'bread');

  assert.deepEqual(p.app.querySelectorAll('.card .label').map((l) => text(l)), ['Bread hydration']);
  assert.deepEqual(paths(p).slice(before), ['GET /courses'],
    'the search costs more than the one index it needs');

  // And a second query answers from what it already read.
  await typeInto(find(p.app, '.search'), 'tls');
  assert.deepEqual(paths(p).slice(before), ['GET /courses'],
    'the index is being re-read per keystroke');
});

test('SB-265: search shows only matching destinations and one scoped empty result', async (t) => {
  /**
   * "You have nothing" and "nothing matched that" are different sentences about
   * somebody's own work, and the second must never read as the first.
   *
   * A successful search must not lead with a stack of failures from unrelated
   * destinations. When there is no result anywhere, one sentence names the
   * complete scope so it cannot be mistaken for an empty Board.
   */
  const p = await openOnBoard(t, home({
    'GET /board': { topics: [topic('t1', 'TLS')], suggestions: [] },
    'GET /courses': { courses: [] },
  }));
  await typeInto(find(p.app, '.search'), 'sourdough');

  assert.deepEqual(p.app.querySelectorAll('.found').map((group) => text(group)), []);
  assert.equal(text(find(p.app, '.search-empty')),
    'I couldn’t find “sourdough” on your board, in your courses or in your plan. Try a different word.');
  assert.ok(!text(p.app).includes('Nothing here yet.'), 'and it does not read as an empty board');
});

test('the search finds the pin printed underneath it, and the course material it never could', async (t) => {
  /**
   * Maya's blocker, in one test. She typed "tides" while two cards reading
   * "Spring and neap tides" and "Solar and lunar tides" were on the screen
   * beneath the box, and was told nothing matched: both were unfiled pins, and
   * the search filtered topics. Her own week 3 video, added by hand and sitting
   * in My studies, was not reachable from this box at all.
   */
  const p = await openOnBoard(t, home({
    'GET /board': {
      topics: [topic('t1', 'TLS')], suggestions: [],
      unfiled: [{ id: 'p1', title: 'Spring and neap tides', gist: '' }],
    },
    'GET /courses': { courses: [{
      id: 'k1', title: 'Tides and the moon', provider: '', url: '',
      material: [{ id: 'm1', title: 'Week 3 video, tides', url: '', kind: 'video', minutes: 12, doneAt: null }],
      progress: { covered: 0, materialCount: 1, learnt: 0, topicCount: 0 },
    }] },
  }));
  await typeInto(find(p.app, '.search'), 'tides');

  const board = find(p.app, '.found[data-found="board"]');
  assert.equal(text(find(board, 'h2')), 'On your board');
  assert.deepEqual(board.querySelectorAll('.pin-card .label').map((l) => text(l)),
    ['Spring and neap tides'], 'the two cards under the box are still unreachable');

  const courses = find(p.app, '.found[data-found="courses"]');
  assert.equal(text(find(courses, 'h2')), 'In your courses');
  assert.deepEqual(courses.querySelectorAll('.study-hit .label').map((l) => text(l)),
    ['Tides and the moon', 'Week 3 video, tides']);
  // The material hit says which course it came out of: a title on its own
  // answers half the question she asked.
  assert.deepEqual(courses.querySelectorAll('.study-hit .where').map((w) => text(w)),
    ['', 'Tides and the moon']);

  // SB-18: the headings are the names of the two places, never a tally of what
  // is in them.
  for (const h of p.app.querySelectorAll('.found h2')) {
    assert.doesNotMatch(text(h), /\d/, 'a search heading grew a count');
  }
});

