test('the courses group says it is still reading rather than reporting a miss it has not checked', async (t) => {
  /**
   * The index is read on the first keystroke, so there is a moment where the
   * board half of the answer is on screen and the courses half is in flight. A
   * group that said "nothing in your courses" during it would be reporting a
   * result it does not have, about the room the learner is most likely to be
   * looking for.
   */
  const p = await openOnBoard(t, home({
    'GET /board': { topics: [], suggestions: [] },
    'GET /courses': { courses: [] },
  }));
  const box = find(p.app, '.search');
  box.value = 'tides';
  // The input handler draws before it asks, which is the frame this is about.
  box.fireEvent('input');
  assert.equal(text(find(p.app, '.found[data-found="courses"] .bare')),
    'Still reading your courses.');
  await settle();
  assert.equal(text(find(p.app, '.search-empty')),
    'I couldn’t find “tides” on your board, in your courses or in your plan. Try a different word.');
});

test('a failed course search says it could not read, then retries the same query', async (t) => {
  let reads = 0;
  const p = await openOnBoard(t, home({
    'GET /board': { topics: [], suggestions: [] },
    'GET /courses': () => {
      reads += 1;
      return reads === 1 ? DOWN : { courses: [{
        id: 'k1', title: 'Ocean systems', provider: '', url: '',
        material: [{ id: 'm1', title: 'Spring tides', url: '', kind: 'video', minutes: 8, doneAt: null }],
        progress: { covered: 0, materialCount: 1, learnt: 0, topicCount: 0 },
      }] };
    },
  }));
  const search = find(p.app, '.search');
  await typeInto(search, 'tides');
  const courses = find(p.app, '.found[data-found="courses"]');
  assert.match(text(courses), /could not read your courses/i);
  assert.doesNotMatch(text(courses), /Nothing in your courses matches/);
  const unreadable = find(courses, '.search-unreadable');
  assert.equal(unreadable.getAttribute('role'), 'status');
  assert.equal(unreadable.getAttribute('aria-live'), 'polite');

  await clickButton(courses, 'Try courses again');
  assert.equal(reads, 2);
  assert.equal(search.value, 'tides', 'retry cleared the query it was retrying');
  assert.deepEqual(find(p.app, '.found[data-found="courses"]')
    .querySelectorAll('.study-hit .label').map((n) => text(n)), ['Spring tides']);
});

test('a signed-out learner\u2019s course index cannot appear in the next account\u2019s search', async (t) => {
  const authPath = 'POST http://127.0.0.1:9099/identitytoolkit.googleapis.com/v1/accounts'
    + ':signInWithIdp?key=fake-api-key';
  const aliceCourse = {
    id: 'alice-course', title: 'Alice private ocean notes', provider: '', url: '', material: [],
    progress: { covered: 0, materialCount: 0, learnt: 0, topicCount: 0 },
  };
  const bobCourse = {
    id: 'bob-course', title: 'Bob private orchard notes', provider: '', url: '', material: [],
    progress: { covered: 0, materialCount: 0, learnt: 0, topicCount: 0 },
  };
  const p = await open(t, home({
    'GET /courses': { courses: [aliceCourse] },
  }), true, { sb_auth_config: CONFIG, sb_session: SESSION });
  await toBoardFace(p);
  await typeInto(find(p.app, '.search'), 'alice private');
  assert.deepEqual(p.app.querySelectorAll('.study-hit .label').map((n) => text(n)),
    ['Alice private ocean notes']);

  await clickButton(p.app, 'alice@example.com');
  await clickButton(p.app, 'Sign out');
  p.route(home({
    'GET /courses': { courses: [bobCourse] },
    [authPath]: {
      idToken: 'bob-live-token', refreshToken: 'bob-refresh', expiresIn: '3600',
      localId: 'bobUid', email: 'bob@example.com',
    },
  }));
  await clickButton(p.app, 'Continue with Google');
  await toBoardFace(p);
  const readsBefore = paths(p).filter((path) => path === 'GET /courses').length;
  await typeInto(find(p.app, '.search'), 'alice private');

  assert.equal(paths(p).filter((path) => path === 'GET /courses').length, readsBefore + 1,
    'Bob searched Alice\u2019s cached index without a service read');
  assert.equal(p.app.querySelectorAll('.study-hit').length, 0,
    'Alice\u2019s course title crossed the account boundary');
  assert.equal(text(find(p.app, '.search-empty')),
    'I couldn’t find “alice private” on your board, in your courses or in your plan. Try a different word.');
});

