const finished = (over: RawSection = {}): RawSection => session({
  sections: [section({ completed: true }), section({ topicId: 't2', question: null, completed: true })],
  ...over,
});

/**
 * A finished session, opened again.
 *
 * The close screen is normally reached by finishing the last section in the
 * room; these tests open the room directly, which is what the panel does when
 * `/today` hands it a session destination. The awards read is a property of
 * the room, and this is the cheapest honest way in to assert it.
 */
const reopen = async (p: Panel): Promise<void> => { await clickButton(p.app, 'Continue'); };
const finishedHome = (over: Table = {}): Table => home({
  'GET /session': { session: finished(), card: card() },
  'GET /today': {
    next: { ...NEXT_SESSION, primary: { ...NEXT_SESSION.primary, cta: 'Continue' } },
  },
  ...over,
});

test('§5: the award moment is session close, and it reads the awards for THAT session', async (t) => {
  const p = await open(t, finishedHome({ 'GET /sessions/sess-1/awards': { awards: [milestone()] } }));
  await reopen(p);

  assert.equal(paths(p)[paths(p).length - 1], 'GET /sessions/sess-1/awards');
  assert.equal(text(find(p.app, '.awards h2')), 'What that session moved');
  assert.equal(text(find(p.app, '.awards .fact')),
    'IAM conditions: building → fluent. Demonstrated 3 times across 2 weeks.');
});

test('§5: a session still in progress is not a close screen', async (t) => {
  const p = await open(t, home({ 'GET /sessions/sess-1/awards': { awards: [milestone()] } }));
  await startSession(p);
  assert.equal(p.app.querySelectorAll('.awards').length, 0);
  assert.ok(!paths(p).includes('GET /sessions/sess-1/awards'),
    'and it does not even ask — an award offered halfway through is the lobby the spec refuses');
});

test('§5: a session that moved nothing says nothing — there is no award for turning up', async (t) => {
  const p = await open(t, finishedHome({ 'GET /sessions/sess-1/awards': { awards: [] } }));
  await reopen(p);
  assert.equal(p.app.querySelectorAll('.awards').length, 0);
});

test('a finished session has one clear way back to the live next move', async (t) => {
  const p = await open(t, finishedHome({ 'GET /sessions/sess-1/awards': { awards: [] } }));
  await reopen(p);
  const next = find(p.app, '[data-after-session]');
  assert.equal(text(next), 'See what’s next');
  const before = paths(p).filter((path) => path === 'GET /today').length;
  await clickButton(p.app, 'See what’s next');
  assert.ok(paths(p).filter((path) => path === 'GET /today').length > before,
    'the close button did not re-read the live next move');
});

test('§5: an award screen the service could not supply is absent, not blank', async (t) => {
  const p = await open(t, finishedHome({ 'GET /sessions/sess-1/awards': DOWN }));
  await reopen(p);
  assert.equal(p.app.querySelectorAll('.awards').length, 0);
  // A finished session has no lesson left to show, so what must survive is the
  // close itself and the way back into the material.
  assert.equal(p.app.querySelectorAll('.session-close').length, 1);
  assert.ok(find(p.app, '.room-rail').querySelectorAll('.rail-name').length > 0,
    'and the session itself is untouched');
});

// ======================================================= SB-38: check my work

/**
 * The QC cameo, wired.
 *
 * One screen, one request, and a hard rule the screen has to hold as firmly as
 * the agent does: The learner-work review boundary — this reviews the learner's own work
 * and never produces submittable content. The agent holds it in its schema, its
 * prompt and a tripwire. Here it is held by there being nothing on the screen
 * that offers to do the writing.
 *
 * The draft is pasted rather than read off the page. A side-panel button is not
 * one of the gestures that grants `activeTab`, and the manifest asks for no
 * host permissions beyond the loopback service, so the panel cannot reach into
 * the tab's textarea — and a screen that promised to would be promising
 * something the extension cannot do.
 */

const finding = (over: RawSection = {}): RawSection => ({
  quote: 'it will eventually arrive',
  problem: 'Stated as a guarantee the delivery semantics do not give you.',
  relatedTopicId: 't1',
  relatedTopicLabel: 'TLS',
  pinSuggestion: 'Retry semantics',
  ...over,
});

/**
 * The check screen, opened, with the receipt the size meter reads behind it.
 *
 * `/model-config` is on this table rather than left to 404 because the caps the
 * meter warns against are the service's, and a screen that fell back to its own
 * copy of them in every test would be a screen whose tests never saw the wire.
 */
const checkHome = (over: Table = {}): Table =>
  home({ 'GET /model-config': modelConfig(), ...over });

/** Open the check screen from the main page. */
async function openCheck(p: Panel): Promise<void> {
  await clickButton(p.app, 'Check');
}

/**
 * The three boxes, by the class each one carries.
 *
 * These used to be `find(p.app, 'textarea')`, which is the FIRST textarea on
 * the screen. That held for exactly as long as the screen had one box on it.
 * The third box landed and every one of those selectors silently kept pointing
 * at the draft — which is the shape of test that passes while the feature it is
 * named after does nothing. Named, now, so a box moving is a failure rather
 * than a coincidence.
 */
const draftBox = (p: Panel): El => find(p.app, 'textarea.draft');
const rubricBox = (p: Panel): El => find(p.app, 'textarea.rubric');
const contextBox = (p: Panel): El => find(p.app, 'textarea.context');

const DRAFT = 'Retries are handled by the queue, so once a message is published it will eventually arrive. '
  + 'The receiver records the delivery key before applying the change, and a retry finds that receipt instead of applying the same change twice. '
  + 'This makes redelivery safe without pretending the queue delivers only once.';
const RUBRIC = 'Names the delivery guarantee\nCites a source';
const CONTEXT = 'The brief asks for 500 words on message delivery.';

test('SB-38: the check is a door on the main page, and drawing it costs one receipt', async (t) => {
  /**
   * It used to cost nothing, and the honest thing to say about the change is
   * that it costs one GET the first time and nothing after that.
   *
   * The receipt is what the size meter warns against: the caps live in `core/`
   * where they are enforced, and a panel carrying its own copy of "12,000" is a
   * copy that drifts — the first anybody would hear of it being a learner told
   * their work fits on the day the marker cuts it. Asked once and memoised for
   * the life of the panel, because it is a receipt rather than a reading.
   */
  const p = await open(t, checkHome());
  assert.deepEqual(paths(p), FIRST_PAINT);
  await openCheck(p);
  assert.deepEqual(paths(p), [...FIRST_PAINT, 'GET /model-config'],
    'opening the screen asks for the caps and nothing else');
  // The room's title is the door's words. Two names for one place is a place
  // the learner has to work out they have already arrived at (2026-08-24).
  assert.equal(text(find(p.app, 'h1')), 'Check');

  // And leaving and coming back does not ask again. The main page pays for its
  // own zones on the way back, which is what it has always done; what must not
  // grow is the receipt.
  await clickButton(p.app, 'Virgil');
  await openCheck(p);
  assert.equal(paths(p).filter((r) => r === 'GET /model-config').length, 1,
    'the receipt is being re-fetched per render');
});

test('SB-38: the screen says what it will not do before the learner asks it to', async (t) => {
  const p = await open(t, checkHome());
  await openCheck(p);
  assert.ok(text(p.app).includes('I don’t rewrite it. That part stays yours.'),
    'The learner-work review boundary, on the screen, where the learner reads it rather than in a comment');
});

test('SB-38: three boxes, in the order the gesture happens in', async (t) => {
  const p = await open(t, checkHome());
  await openCheck(p);
  // The order is the design: what you wrote, what you are marked against, and
  // then anything else. A context box above the criteria would read as a form.
  const boxes = find(p.app, '.check-form').querySelectorAll('textarea')
    .map((b) => b.className.replace('statement-edit', '').trim());
  assert.deepEqual(boxes, ['draft', 'rubric', 'context']);
  // Short noun phrases, all three, with the voice one line down. The labels
  // used to be conversational sentences styled as headings.
  assert.deepEqual(
    find(p.app, '.check-form').querySelectorAll('label').map((l) => text(l)),
    ['Your work', 'Marking criteria (optional)', 'Extra context (optional)'],
  );
  assert.ok(text(p.app).includes('Whatever you are about to hand in or send.'));
  assert.ok(text(p.app).includes('Add anything else you would like me to know.'));
  assert.ok(text(p.app).includes('I read it as background, never as part of the work.'));
});

test('Check opens as one work area with optional detail kept quiet', async (t) => {
  const p = await open(t, checkHome());
  await openCheck(p);
  const form = find(p.app, '.check-form');
  assert.equal(text(find(form, '.check-ready-line')), 'Add your work to begin.');
  assert.equal(find(form, '[data-option="rubric"]').getAttribute('open'), null);
  assert.equal(find(form, '[data-option="context"]').getAttribute('open'), null);
  assert.equal(text(find(find(form, '[data-option="rubric"]'), 'summary')), 'Marking criteriaOptional');
  assert.equal(text(find(find(form, '[data-option="context"]'), 'summary')), 'Extra contextOptional');

  await typeInto(draftBox(p), 'a'.repeat(200));
  await typeInto(rubricBox(p), 'Explain the evidence used in the conclusion.');
  assert.equal(text(find(form, '.check-ready-line')), 'Ready · 200 characters · 1 criterion');
  assert.equal(text(find(find(form, '.check-handoff'), 'summary')), 'Check details');
});

test('Check discloses the active text minimum before submit and recomputes it with the mode', async (t) => {
  const p = await open(t, checkHome());
  await openCheck(p);

  await typeInto(draftBox(p), 'a'.repeat(151));
  await typeInto(rubricBox(p), RUBRIC);
  assert.equal(button(p.app, 'Check it').disabled, true,
    'a known too-short mark was allowed to fail after the press');
  assert.match(text(find(p.app, '.check-handoff')),
    /151 of 200 characters needed for a criteria-led mark.*Add 49 characters more/);

  await typeInto(draftBox(p), 'a'.repeat(200));
  assert.equal(button(p.app, 'Check it').disabled, false,
    'the exact marker minimum did not become ready');

  await typeInto(rubricBox(p), '   ');
  await typeInto(draftBox(p), 'a'.repeat(79));
  assert.equal(button(p.app, 'Check it').disabled, true);
  assert.match(text(find(p.app, '.check-handoff')),
    /79 of 80 characters needed for a board-informed review.*Add 1 character more/);
  await typeInto(draftBox(p), 'a'.repeat(80));
  assert.equal(button(p.app, 'Check it').disabled, false,
    'the exact reviewer minimum did not become ready');
});

test('SB-128: every check box has its visible label and the two upload actions have distinct names', async (t) => {
  const p = await open(t, checkHome());
  await openCheck(p);
  const form = find(p.app, '.check-form');
  for (const [selector, expected] of [
    ['textarea.draft', 'Your work'],
    ['textarea.rubric', 'Marking criteria (optional)'],
    ['textarea.context', 'Extra context (optional)'],
  ] as const) {
    const field = find(form, selector);
    const id = field.getAttribute('id');
    assert.ok(id, `${selector} has no id for its visible label`);
    const label = form.querySelectorAll('label').find((candidate) => candidate.getAttribute('for') === id);
    assert.equal(label ? text(label) : null, expected);
  }
  assert.equal(find(form, '[data-pick="draft"]').getAttribute('aria-label'),
    'Add a document or screenshot');
  assert.ok(button(form, 'Add criteria from a file'));
  assert.equal(form.querySelectorAll('button').filter((b) => text(b) === 'Upload a file').length, 0);
});

