test('a budget stop on the check screen is never dressed up as a broken service', async (t) => {
  /**
   * 402 is the only route to that status in this service and it means one
   * thing: the learner's own limit stopped the call before it was sent.
   *
   * Every other refusal sentence on this screen ends in some form of "this is
   * mine to fix, not yours", and here that clause is false twice over — nothing
   * is broken, and the person reading it is the only person who can change it.
   * Told the generic sentence, somebody goes and checks an API key that is
   * working perfectly, over a limit they set themselves.
   */
  for (const route of ['POST /review', 'POST /mark'] as const) {
    const p = await open(t, checkHome());
    await openCheck(p);
    p.route(checkHome({
      [route]: {
        status: 402,
        body: {
          error: 'Your model budget stopped this before anything was sent.',
          stoppedBy: 'model-budget', connection: 'cloud',
          freeConnections: [
            { connection: 'local', enabled: true, readiness: 'ready' },
            { connection: 'cli', enabled: false, readiness: 'ready' },
          ],
        },
      },
    }));
    draftBox(p).value = DRAFT;
    // `/mark` is the route only when there are criteria in the second box.
    if (route === 'POST /mark') rubricBox(p).value = 'One: it has a thesis.';
    await clickButton(p.app, 'Check it');

    const said = text(find(p.app, '.failed'));
    assert.match(said,
      /Your budget stopped this before anything was sent\. Nothing about your draft has changed\./,
      route);
    assert.equal(text(find(p.app, '.budget-free-recovery')),
      'Local is ready to use. Agent CLI is available but turned off. I did not move any model work. Open Models to choose which work to move.',
      route);
    // The two sentences this screen may never say about a budget stop.
    assert.doesNotMatch(said, /mine to fix/, route);
    assert.doesNotMatch(said, /not running on this computer/, route);
    // The invariant every branch of this line keeps, kept here too.
    assert.equal(draftBox(p).value, DRAFT, route);
  }
});

