// ------------------------------------------------ the marker branch (backfill)

/**
 * A mark, as the service answers it.
 *
 * `/mark` shipped with the second box and nothing in this file had ever pressed
 * the button with criteria in it: the whole marker branch — the verdict, the
 * rows, the truncation note, the quarantine — was rendered by code no test had
 * evaluated. The row-by-row verdict is the half of this screen a learner would
 * act on, so it is the half most worth holding.
 */
const criterion = (over: RawSection = {}): RawSection => ({
  criterionId: 'c1',
  criterion: 'Names the delivery guarantee',
  verdict: 'does-not-meet',
  evidence: 'it will eventually arrive',
  fix: 'Say which guarantee, and what it does not promise.',
  relatedTopicId: 't1',
  relatedTopicLabel: 'TLS',
  ...over,
});

const mark = (over: RawSection = {}): RawSection => ({
  outcome: 'marked',
  verdict: 'send-back',
  summary: 'One criterion out of two is not met.',
  rows: [criterion(), criterion({ criterionId: 'c2', criterion: 'Cites a source', verdict: 'meets', fix: null, relatedTopicId: null, relatedTopicLabel: null })],
  quarantined: [],
  truncated: false,
  contextTruncated: false,
  ...over,
});

