// ------------------------------------------------ SB-39: the pin offer (new)

test('every finding is offered to the board, but none is written without confirmation', async (t) => {
  /**
   * The deliberate-capture precedence, on the screen where breaking it would be cheapest: a review of
   * a long essay produces five findings at once, and a check that filed all
   * five would have made somebody's board about an afternoon's proofreading.
   */
  const p = await open(t, checkHome({
    'POST /review': { outcome: 'reviewed', findings: [finding(), finding({
      quote: 'q2', relatedTopicId: null, relatedTopicLabel: null, pinSuggestion: null,
    })] },
    'POST /pins': { id: 'pin-9', label: 'Retry semantics' },
  }));
  await openCheck(p);
  draftBox(p).value = DRAFT;
  await clickButton(p.app, 'Check it');

  const offers = p.app.querySelectorAll('.finding .offer').filter((o) => o.children.length > 0);
  assert.equal(offers.length, 2, 'a useful finding still depended on a model-authored label');
  assert.ok(offers.some((offer) => text(offer).includes('This connects to TLS.')));
  assert.ok(
    offers.some((offer) => text(offer).includes('Keep this finding so it can shape a later lesson.')),
    JSON.stringify(offers.map((offer) => text(offer))),
  );
  assert.equal(paths(p).filter((r) => r === 'POST /pins').length, 0, 'the pin was written without being asked for');
});

test('a finding without a model label can still become a learner-confirmed struggle', async (t) => {
  const p = await open(t, checkHome({
    'POST /review': { outcome: 'reviewed', findings: [finding({
      relatedTopicId: null, relatedTopicLabel: null, pinSuggestion: null,
    })] },
    'POST /pins': { id: 'pin-9', label: 'Retry semantics' },
  }));
  await openCheck(p);
  draftBox(p).value = DRAFT;
  await clickButton(p.app, 'Check it');
  await clickButton(p.app, 'Keep it on the board');

  const body = lastBody(p) as { type: string; clientRef: string; envelope: Record<string, unknown> };
  // A finding is by construction the thing they did not get right.
  assert.equal(body.type, 'struggle');
  // A finding carries no url, but the service requires one: `url: null` is a
  // 400 from `pinRequestFrom` — found live, after this test had blessed a body
  // the real service refuses. The opaque scheme is the documented "no site
  // here" shape; `originOf` buckets it under its own `url:` prefix and both
  // deep-link builders answer null for it.
  assert.equal(body.envelope['selection'], 'Stated as a guarantee the delivery semantics do not give you.');
  assert.equal(body.envelope['surroundingText'], 'it will eventually arrive');
  assert.equal(body.envelope['url'], 'virgil:check-draft');
  assert.deepEqual(body.envelope['headingPath'], []);
  assert.match(body.clientRef, /^[A-Za-z0-9_-]{8,160}$/);
  assert.doesNotMatch(body.clientRef, /delivery semantics|^check-\d+-/,
    'a later review could recreate this receipt for a different finding');

  assert.ok(text(p.app).includes('On your board.'));
  assert.ok(button(find(p.app, '.finding .offer'), 'Learn this now'),
    'the saved weakness still has no route into learning');
  assert.equal(p.app.querySelectorAll('button').filter((b) => text(b) === 'Keep it on the board').length, 0,
    'the control that has already been pressed is still there to press again');
});

test('a saved finding can become an exact lesson now without losing the draft', async (t) => {
  /**
   * The reviewer found the gap while the learner was revising. “I will build
   * something for it” asked them to leave that moment, wait for an unspecified
   * run and find the subject again later, even though exact-pin quick lessons
   * already exist. The save stays explicit, and so does this second move: a
   * review with several findings must not navigate on the first board write.
   */
  const p = await open(t, checkHome({
    'POST /review': { outcome: 'reviewed', findings: [finding()] },
    'POST /pins': { id: 'pin-9', label: 'Retry semantics' },
    'POST /pins/pin-9/quick-take': take({
      label: 'Retry semantics', body: 'A retry is safe only when the operation is idempotent.',
    }),
  }));
  await openCheck(p);
  await typeInto(draftBox(p), DRAFT);
  await clickButton(p.app, 'Check it');
  await clickButton(p.app, 'Keep it on the board');

  assert.ok(p.app.querySelector('.findings'), 'saving silently navigated away from the other findings');
  await clickButton(find(p.app, '.finding .offer'), 'Learn this now');

  assert.equal(p.app.dataset.room, 'today');
  assert.equal(text(find(p.app, '.foreground-lesson .lesson-area')), 'Retry semantics');
  assert.match(text(find(p.app, '.foreground-lesson .body')), /operation is idempotent/);
  assert.ok(paths(p).includes('POST /pins/pin-9/quick-take'),
    'the lesson did not stay on the finding the learner saved');

  await openCheck(p);
  assert.equal(draftBox(p).value, DRAFT, 'the lesson detour cleared the work being revised');
});

test('SB-39: a pin that did not land says so, and the button stays usable', async (t) => {
  const attempts: Record<string, unknown>[] = [];
  let calls = 0;
  const p = await open(t, checkHome({
    'POST /review': { outcome: 'reviewed', findings: [finding()] },
    'POST /pins': (init: RequestInit | undefined) => {
      attempts.push(JSON.parse(String(init?.body)) as Record<string, unknown>);
      calls += 1;
      return calls === 1 ? DOWN : { id: 'pin-9', label: 'Retry semantics' };
    },
  }));
  await openCheck(p);
  draftBox(p).value = DRAFT;
  await clickButton(p.app, 'Check it');
  await clickButton(p.app, 'Keep it on the board');

  assert.ok(text(p.app).includes("That didn't go through. Nothing is on the board."));
  const again = button(p.app, 'Keep it on the board');
  assert.equal(again.disabled, false, 'a pin that did not land is a thing to try again, not a thing to lose');
  assert.equal(p.dom.activeElement, again);
  await click(again);
  await settle();
  assert.equal(attempts.length, 2);
  assert.equal(attempts[1]?.clientRef, attempts[0]?.clientRef,
    'retry became a different board gesture instead of recovering the first write');
  assert.match(text(find(p.app, '.finding .offer')), /On your board/);
});

