test('the meter says nothing at all until there is something worth saying', async (t) => {
  /**
   * This product counts nothing it does not have to. A character counter that
   * is always on turns a box somebody is thinking in into a form with a limit.
   * The rubric's standing whole-input contract is not a live meter: it is the
   * boundary the learner needs before deciding what to paste.
   */
  const p = await open(t, checkHome());
  await openCheck(p);
  assert.equal(p.app.querySelectorAll('.size-note').every((node) => text(node) === ''), true);
  assert.match(text(find(p.app, '.rubric-limit')), /400 Unicode characters each/);

  await typeInto(draftBox(p), 'a'.repeat(4_000));
  assert.equal(p.app.querySelectorAll('.size-note').filter((n) => text(n) !== '').length, 0,
    'two thirds of the way is not a warning');
});

test('the meter warns at 80% of the cap, names the number, and says what happens past it', async (t) => {
  const p = await open(t, checkHome());
  await openCheck(p);

  // The reviewer's cap, because there are no criteria in the other box.
  await typeInto(draftBox(p), 'a'.repeat(5_000));
  const note = find(p.app, '.paste-box[data-box="draft"] .size-note');
  assert.ok(text(note).includes('5,000 characters of 6,000'), text(note));
  assert.ok(text(note).includes('I read the first 6,000 and tell you I stopped'), text(note));

  // Over it, and still not blocked: the work is theirs, and a check of the
  // first 6,000 characters is worth having as long as nobody is told it was a
  // check of all of it.
  await typeInto(draftBox(p), 'a'.repeat(7_000));
  assert.ok(text(note).includes('That is 7,000 characters.'), text(note));
  assert.equal(button(p.app, 'Check it').disabled, false, 'a warning became a block');

  // And back down again: the line goes away rather than sticking.
  await typeInto(draftBox(p), 'short');
  assert.equal(text(note), '');
});

test('pasting criteria changes which cap the draft is measured against', async (t) => {
  /**
   * The learner never picks a mode, so the cap moves under them: with criteria
   * the work is marked (12,000) and without them it is reviewed (6,000). A
   * meter that kept warning about 6,000 after the criteria went in would be
   * telling somebody to cut an essay that fits.
   */
  const p = await open(t, checkHome());
  await openCheck(p);
  await typeInto(draftBox(p), 'a'.repeat(7_000));
  const note = find(p.app, '.paste-box[data-box="draft"] .size-note');
  assert.ok(text(note).includes('7,000 characters'), text(note));

  await typeInto(rubricBox(p), RUBRIC);
  assert.equal(text(note), '', 'the draft is still being measured against the reviewer cap');

  await typeInto(rubricBox(p), '   ');
  assert.ok(text(note).includes('7,000 characters'), 'and back, when the criteria are cleared');
});

