  const draftPicker = find(p.app, 'input[data-file="draft"]');
  const rubricPicker = find(p.app, 'input[data-file="rubric"]');
  assert.match(draftPicker.getAttribute('accept') ?? '', /\.png/);
  assert.doesNotMatch(rubricPicker.getAttribute('accept') ?? '', /\.png/,
    'the criteria parser started pretending it can extract a screenshot');

  await dropFile(draftBox(p), stubFile('architecture.png', new Uint8Array([1, 2, 3]), 'image/png'));

  assert.equal(text(find(chip(p), '.what')),
    'architecture.png, 1 image. I send it as a picture.');
  assert.deepEqual(chip(p).querySelectorAll('button').map((b) => text(b)), ['Take it off']);
  assert.match(text(find(p.app, '.check-handoff')), /architecture\.png: 1 image, sent as a picture/);
  assert.equal(draftBox(p).value, '', 'the screenshot was treated as extracted draft text');

