test('the side panel keeps a receipt when a picker outcome has no single lesson', async (t) => {
  const p = await open(t, home(), true, { [HANDOFF_KEY]: null }, {
    activeTab: { id: 73, windowId: 4, url: 'https://example.test/lesson' },
  });
  const runtime = (globalThis as unknown as { chrome: { runtime: { onMessage: {
    addListener(fn: (m: unknown, s: unknown, respond: (r: unknown) => void) => boolean): void;
  } } } }).chrome.runtime;
  runtime.onMessage.addListener((m: unknown, _s: unknown, respond: (r: unknown) => void) => {
    if ((m as { kind?: string }).kind !== OPEN_SELECTOR) return false;
    respond({ ok: true });
    return false;
  });

  await clickButton(p.app, 'Pick what to pin');
  assert.equal(text(find(p.app, '[role="status"]')),
    'Picker open on the page. Choose what to keep, then confirm it.');

  await p.c.send({ kind: SELECT_STATUS, tabId: 73, state: 'saving', count: 1, queued: 0 }).catch(() => {});
  assert.equal(text(find(p.app, '[role="status"]')), 'Saving your selection…');
  assert.equal(find(p.app, '[role="status"]').getAttribute('data-state'), 'working');

  await p.c.send({ kind: SELECT_STATUS, tabId: 73, state: 'saved', count: 1, queued: 0 }).catch(() => {});
  assert.equal(text(find(p.app, '[role="status"]')), 'Pinned. It is on your board.');
  assert.equal(find(p.app, '[role="status"]').getAttribute('data-state'), 'done');

  await p.c.send({ kind: SELECT_STATUS, tabId: 99, state: 'failed', count: 0, queued: 0 }).catch(() => {});
  assert.equal(text(find(p.app, '[role="status"]')), 'Pinned. It is on your board.',
    'another window changed the receipt in this panel');
});

