const capturedPinDetail = (id: string, label: string) => ({
  id, type: 'interest', note: null, label,
  capturedAt: '2026-08-31T10:00:00.000Z', topicId: null,
  requestedRegister: null, requestedMinutes: null,
  source: {
    text: label, kind: 'selection', pageTitle: 'A browser page',
    url: 'https://example.test/page', headingPath: [], availability: null,
  },
});

test('the panel reopens on the newest pin and lets This session switch or dismiss shortcuts', async (t) => {
  const held: CaptureSessionPin[] = [
    { pinId: 'p-new', label: 'Bobby Robson', at: 20, ownerUid: null },
    { pinId: 'p-old', label: 'Ipswich Rugby Club', at: 10, ownerUid: null },
  ];
  const p = await open(t, quickTakeRoutes({
    'GET /pins/p-new': capturedPinDetail('p-new', 'Bobby Robson'),
    'GET /pins/p-old': capturedPinDetail('p-old', 'Ipswich Rugby Club'),
  }), true, { [HANDOFF_KEY]: null }, {
    sessionStore: { [CAPTURE_SESSION_KEY]: held },
  });

  assert.equal(text(find(p.app, '.capture-result h1')), 'Bobby Robson');
  assert.ok(!paths(p).some((path) => path.includes('quick-take')),
    'opening the panel on a captured pin spent a Tutor call');
  assert.equal(text(find(p.app, '.capture-session summary')), 'This session · 2');
  assert.deepEqual(find(p.app, '.capture-session-list').querySelectorAll('.capture-session-pin')
    .map((node) => text(node)), ['Bobby Robson', 'Ipswich Rugby Club']);

  await clickButton(find(p.app, '.capture-session-list'), 'Ipswich Rugby Club');
  await settle();
  assert.equal(text(find(p.app, '.capture-result h1')), 'Ipswich Rugby Club');

  const current = p.app.querySelectorAll('.capture-session-row')
    .find((row) => row.getAttribute('data-current') === 'true');
  assert.ok(current);
  await clickButton(current!, '×');
  await settle(20);

  assert.deepEqual((p.c.sessionStore[CAPTURE_SESSION_KEY] as CaptureSessionPin[])
    .map((row) => row.pinId), ['p-new']);
  assert.equal(text(find(p.app, '.capture-result h1')), 'Bobby Robson');
  assert.equal(text(find(p.app, '.capture-session summary')), 'This session · 1');
  assert.equal(p.requests.some((request) => request.method === 'DELETE'), false,
    'dismiss from this session deleted the permanent pin');
});

