/**
 * SB-283: the third answer, and the reason the walkthrough asked for it.
 *
 * *Got it* and *Still fuzzy* are both readings of the take. Neither covers *I
 * read it and I am not doing this now*, which before this slice could only be
 * said with the back button, and the ledger does not hear back buttons. It
 * lands as `lineup-not-now`, the mark the session X already writes, so the
 * Gardener's hold window and the night scout's avoided-topic read both see it
 * without anything new being built for them.
 */
test('SB-283: not now is an answer, and the receipt names the window it bought', async (t) => {
  const p = await open(t, quickTakeRoutes({
    'POST /pins/p-42/quick-take/verdict': (init: RequestInit | undefined) => ({
      ok: true, verdict: JSON.parse(String(init?.body ?? '{}')).verdict, backAfterDays: 7,
    }),
  }), true, waiting());

  await clickButton(find(p.app, '.quick-take .verdict'), 'Not now');
  assert.deepEqual(lastBody(p), { verdict: 'not-now' });
  assert.equal(p.app.dataset.room, 'today');
  assert.equal(p.app.querySelectorAll('.quick-take').length, 0);
  // The service's number, not the panel's copy of it: one place decides how
  // long "not now" lasts and the sentence reads it back.
  assert.match(text(p.app), /Put down\. It comes back in about 7 days\./);
});

