/**
 * Asking, which is the thing that was missing.
 *
 * The screen had two buttons and no way to say anything. What replaced the
 * register ladder is a box, and what is asserted is that a question reaches
 * the service with the exchange behind it, that the answer lands where a
 * reader can see both, and that the screen does not close on either.
 */
const askRoutes = (over: Table = {}): Table => quickTakeRoutes({
  'POST /pins/p-42/ask': { outcome: 'ready', body: 'Because the index is sorted by the first field.', offerAsPin: null },
  ...over,
});

test('a question is asked, answered, and both stay on screen', async (t) => {
  const p = await open(t, askRoutes(), true, waiting());
  const box = find(p.app, '.ask-box');
  box.value = 'why does the order matter?';
  await clickButton(find(p.app, '.ask .field'), 'Ask');

  assert.deepEqual(lastBody(p), { question: 'why does the order matter?', exchange: [] },
    'the first question carries no history, because there is none');
  const turns = p.app.querySelectorAll('.exchange .turn');
  assert.equal(turns.length, 2, 'their question and the answer are both on screen');
  assert.match(text(turns[0]!), /why does the order matter\?/);
  assert.match(text(turns[1]!), /sorted by the first field/);
  assert.equal(box.value, '', 'the box is cleared for the next one');
  assert.ok(p.app.querySelectorAll('.quick-take .verdict').length,
    'asking is not answering: the screen stays open');
});

test('the second question carries the first exchange, and no more than the cap', async (t) => {
  const p = await open(t, askRoutes(), true, waiting());
  const box = find(p.app, '.ask-box');

  box.value = 'first?';
  await clickButton(find(p.app, '.ask .field'), 'Ask');
  box.value = 'and then?';
  await clickButton(find(p.app, '.ask .field'), 'Ask');

  const sent = lastBody(p) as { question: string; exchange: { who: string; text: string }[] };
  assert.equal(sent.question, 'and then?');
  assert.deepEqual(sent.exchange.map((t2) => t2.who), ['learner', 'virgil'],
    'the answer has to travel too, or a follow-up is answered blind');
  assert.equal(sent.exchange[0]!.text, 'first?');
});

test('a shortcut asks, in one press', async (t) => {
  // It used to fill the box and wait for a second press so the question could
  // be read first. A shortcut that costs two presses is not one, and what was
  // sent lands on screen as their own turn a moment later, which is where it
  // can be read.
  const p = await open(t, askRoutes(), true, waiting());
  await clickButton(find(p.app, '.ask .shortcuts'), 'Simpler');

  assert.ok(paths(p).includes('POST /pins/p-42/ask'), 'the shortcut did not ask anything');
  assert.match(String((lastBody(p) as { question: string }).question), /more simply/);
  assert.match(text(p.app.querySelectorAll('.exchange .turn')[0]!), /more simply/,
    'and what it sent is on screen as their turn');
  assert.equal(find(p.app, '.ask-box').value, '', 'the box is left for their own words');
});

test('SB-209: a pending lesson question owns every question and closing control', async (t) => {
  const p = await open(t, askRoutes(), true, waiting());
  const immediate = serve(askRoutes());
  let release!: (response: FakeResponse) => void;
  const delayed = new Promise<FakeResponse>((resolve) => { release = resolve; });
  p.c.fetchHandler = (url, init) => {
    const path = url.startsWith(SERVICE) ? url.slice(SERVICE.length) : url;
    if (`${init?.method ?? 'GET'} ${path}` === 'POST /pins/p-42/ask') return delayed;
    return immediate(url, init);
  };

  await button(find(p.app, '.ask .shortcuts'), 'Example').fireEvent('click');
  await new Promise<void>((resolve) => { setTimeout(resolve, 0); });
  assert.equal(find(p.app, '.quick-take').getAttribute('aria-busy'), 'true');
  assert.equal(find(p.app, '.ask-box').disabled, true);
  assert.equal(button(find(p.app, '.ask .field'), 'Ask').disabled, true);
  for (const label of ['Simpler', 'Go deeper', 'Example', 'Got it', 'Still fuzzy', 'Not now']) {
    assert.equal(button(p.app, label).disabled, true, `${label} could race the pending answer`);
  }
  assert.equal(paths(p).filter((path) => path === 'POST /pins/p-42/ask').length, 1);
  assert.equal(paths(p).filter((path) => path === 'POST /pins/p-42/quick-take/verdict').length, 0);

  release(jsonResponse({ outcome: 'ready', body: 'Here is the worked example.', offerAsPin: null }));
  await settle();
  assert.equal(find(p.app, '.quick-take').getAttribute('aria-busy'), null);
  for (const label of ['Simpler', 'Go deeper', 'Example', 'Got it', 'Still fuzzy', 'Not now']) {
    assert.equal(button(p.app, label).disabled, false, `${label} did not return after the answer`);
  }
});

