test('SB-173: a quick-take pin offer owns one opaque retryable receipt', async (t) => {
  const attempts: Record<string, unknown>[] = [];
  let calls = 0;
  const p = await open(t, askRoutes({
    'POST /pins/p-42/ask': {
      outcome: 'ready', body: 'Briefly: it is about write amplification.',
      offerAsPin: 'Write amplification',
    },
    'POST /pins': (init: RequestInit | undefined) => {
      attempts.push(JSON.parse(String(init?.body)) as Record<string, unknown>);
      calls += 1;
      return calls === 1 ? DOWN : { id: 'p-99', label: 'Write amplification' };
    },
  }), true, waiting());
  find(p.app, '.ask-box').value = 'how does this affect writes?';
  await clickButton(find(p.app, '.ask .field'), 'Ask');

  const offer = find(p.app.querySelectorAll('.exchange .turn')[1]!, '.offer');
  await clickButton(offer, 'Put it on the board');
  assert.equal(attempts.length, 1);
  assert.match(String(attempts[0]?.clientRef), /^[A-Za-z0-9_-]{8,160}$/);
  assert.doesNotMatch(String(attempts[0]?.clientRef), /^ask-p-42-\d+$/,
    'reopening the pin could recreate the receipt for a different offered subject');
  assert.match(text(offer), /didn't go through.*Nothing changed/i);
  const retry = button(offer, 'Put it on the board');
  assert.equal(p.dom.activeElement, retry);

  await click(retry);
  await settle();
  assert.equal(attempts.length, 2);
  assert.equal(attempts[1]?.clientRef, attempts[0]?.clientRef,
    'a lost-success retry became a second pin gesture');
  assert.match(text(offer), /On the board/);
  assert.throws(() => button(offer, 'Put it on the board'));
});

