test('SB-203: a take withheld by its source check is never shown or scored', async (t) => {
  const p = await open(t, quickTakeRoutes({
    'POST /pins/p-42/quick-take': take({
      outcome: 'unverified', body: '', label: 'Gemma Model Architecture',
      pinned: {
        text: 'Gemma', kind: 'selection',
        pageTitle: 'Run Gemma content generation and inferences | Google AI for Developers',
        url: 'https://ai.google.dev/gemma/docs/run', note: null,
      },
    }),
  }), true, waiting());

  const recovery = find(p.app, '.quick-take .body');
  const said = text(recovery);
  assert.deepEqual(recovery.querySelectorAll('p').map((line) => text(line)), [
    'I wrote a draft, but its source check did not clear it, so I held it back. Your credit limit did not stop this.',
    'Your source is still on your board as “Gemma Model Architecture”.',
  ]);
  assert.equal((said.match(/on your board/g) ?? []).length, 1,
    'the saved-source fact is still repeated');
  assert.equal(recovery.querySelectorAll('.recovery-note').length, 0,
    'the controls still have an explanatory spiel above them');
  assert.deepEqual(recovery.querySelectorAll('button').map((control) => text(control)), [],
    'the withheld state invited another paid model call');
  assert.equal(p.app.querySelectorAll('.quick-take .verdict').length, 0,
    'the learner could mark confidence against teaching they never saw');

  const elsewhere = find(p.app, '.quick-take .quick-take-routes');
  assert.deepEqual(elsewhere.querySelectorAll('.routes button').map((control) => text(control)),
    ['Gemini · New tab', 'Gemini · Pop out', 'Google Notebook']);
  assert.deepEqual(paths(p), ['POST /pins/p-42/quick-take'],
    'showing free destinations after verification failure made another request');

  await clickButton(elsewhere, 'Gemini · New tab');
  await settle();
  const prompt = new URL(String(p.c.tabsCreated.at(-1)?.url)).searchParams.get('q') ?? '';
  assert.match(prompt, /Run Gemma content generation and inferences/);
  assert.match(prompt, /https:\/\/ai\.google\.dev\/gemma\/docs\/run/);
  assert.deepEqual(paths(p), ['POST /pins/p-42/quick-take', 'POST /external'],
    'the free handoff repeated the paid quick-take call');
});

