test('§5d: the Notebook hand-off stays single-flight until its fallback destination resolves', async (t) => {
  const routes = home();
  const p = await open(t, routes);
  await startSession(p);
  const immediate = serve(routes);
  let release!: (response: FakeResponse) => void;
  let reachedDestination!: () => void;
  const delayed = new Promise<FakeResponse>((resolve) => { release = resolve; });
  const destinationAsked = new Promise<void>((resolve) => { reachedDestination = resolve; });
  const calls: string[] = [];
  p.c.fetchHandler = (url, init) => {
    const path = url.startsWith(SERVICE) ? url.slice(SERVICE.length) : url;
    const call = `${init?.method ?? 'GET'} ${path}`;
    calls.push(call);
    if (call === 'GET /notebook/drive/hosted-setup') {
      reachedDestination();
      return delayed;
    }
    return immediate(url, init);
  };

  const notebook = button(find(p.app, '.gemini-routes .routes'), NOTEBOOK_BUTTON);
  const pending = notebook.fireEvent('click');
  await destinationAsked;
  assert.equal(notebook.disabled, true,
    'a second press could race the clipboard/Drive fallback before its first receipt landed');
  assert.equal(calls.filter((path) => path === 'POST /notebook/export').length, 1);

  release(jsonResponse({ notebookUrl: NOTEBOOK_ROOT }));
  await pending;
  assert.equal(notebook.disabled, false);
});

