test('the waiter names its own work rather than saying Loading', async () => {
  // Three waits of three different lengths. A learner who knows which one they
  // are in can decide whether to stay, and "Loading" tells them nothing.
  assert.equal(LOADING_HOME, 'Getting your board…');
  assert.equal(LOADING_TAKE, 'Reading what you pinned…');
  assert.equal(LOADING_GUIDE, 'Working out the steps…');
  assert.equal(LOADING_CHECK, 'Reading your draft…');
  for (const line of [LOADING_HOME, LOADING_TAKE, LOADING_GUIDE, LOADING_STUCK, LOADING_CHECK]) {
    assert.ok(!/^loading/i.test(line), 'a wait that names nothing is a spinner with words on it');
  }
  // Only the model calls carry the caveat. Reading the board is a fetch.
  assert.equal(LOADING_SLOW_NOTE, 'This can take a minute or two.');
});

