test('the first run says how to pin, not only that pinning is the thing to do', async (t) => {
  /**
   * The empty arrival page told a first-time learner "Pin something and I will
   * build a session from it" and stopped. The gesture lives in a context menu
   * on some other page, which is exactly where somebody who has never used this
   * product is not looking.
   */
  const p = await openOnBoard(t, home({
    'GET /board': { topics: [], suggestions: [] },
    'GET /session': { session: null, card: { state: 'nothing-ready', reason: 'Nothing pinned yet. Pin something and I will build a session from it.', registers: [], withheld: [] } },
  }));
  // On the board now, because the arrival page it used to live on is gone.
  const said = text(find(p.app, '.firstrun'));
  assert.match(said, /right-click/i, 'nothing on the first screen says how to pin');
  assert.match(said, /Alt\+P/);
});

test('a board with something on it is due a session that has already been built', async (t) => {
  // The counterpart: the instruction is for the first run and must not follow a
  // learner around once they know it.
  const p = await open(t, home());
  assert.doesNotMatch(text(find(p.app, '.next-action')), /right-click/i);
});

test('a board with no topics is still their board, and is not offered a search over nothing', async (t) => {
  /*
   * This was `the door to the board survives a board with no topics yet`, and
   * removing that door was a mistake this suite caught once already: topics
   * arrive from a run, pins do not, so a learner who pinned three things this
   * afternoon has no topics and the board is the only place they can confirm
   * the pins landed.
   *
   * The board-as-page layout contract makes that structural rather than a control to protect — the
   * board IS the page, so it cannot be unreachable. What is still worth
   * asserting is the other half: nothing at all means the first-run screen
   * rather than a search field over an empty board.
   */
  const p = await openOnBoard(t, home({ 'GET /board': { topics: [], suggestions: [] } }));
  assert.ok(p.app.querySelector('.firstrun'), 'a board with nothing on it says how to start');
  assert.equal(p.app.querySelectorAll('.search').length, 1,
    'and the search is the page\u2019s, not a field over nothing');
});

test('there is one search, on the page that holds what it searches', async (t) => {
  const p = await openOnBoard(t, home());
  // One search, on the page that has the things being searched.
  assert.equal(p.app.querySelectorAll('.search').length, 1);
});

test('a session sets the code the Composer indented as code', async (t) => {
  // End to end, because the split is only worth anything if the section
  // renderer uses it — and the depth control has its own path into the body.
  const withCode = 'Your query was, in effect:\n\n  where("status", "==", "active")\n\nFirestore rejected it.';
  const p = await open(t, home({
    'GET /session': { session: session({ sections: [section({ body: withCode })] }), card: card() },
  }));
  await clickButton(p.app, 'Start');

  const first = find(p.app, '.section');
  assert.equal(first.querySelectorAll('.body .code').length, 1, 'the indented line is not set as code');
  assert.equal(text(find(first, '.body .code')), 'where("status", "==", "active")');
  assert.equal(first.querySelectorAll('.body .para').length, 2, 'the prose around it is not paragraphs');
});

