test('the learner picks the theme in Settings, and the choice writes it on the document', async (t) => {
  const p = await openSettings(t);
  const control = find(p.app, '.appearance-setting [data-theme]');
  assert.equal(control.value, 'system');
  control.value = 'light';
  await control.fireEvent('change');
  // Modelled in the stub on purpose: this is the one place a control could
  // look wired and do nothing at all.
  assert.equal(p.dom.root.attrs.get('data-theme'), 'light');
  assert.equal(p.c.store['sb_theme'], 'light');
  control.value = 'dark';
  await control.fireEvent('change');
  assert.equal(p.dom.root.attrs.get('data-theme'), 'dark');
  assert.equal(p.c.store['sb_theme'], 'dark');
});

