/** Backup, restore and deletion, where they live since 2026-08-29: a section
 *  of Settings rather than a door of its own in the masthead. */
const openData = async (p: Panel): Promise<void> => {
  await clickButton(p.app, 'Settings');
  await clickButton(p.app, 'Your data');
};
const CONFIG = { apiKey: 'fake-api-key', projectId: 'virgil-506009', emulatorHost: '127.0.0.1:9099' };
const SESSION = {
  idToken: 'a.b.', refreshToken: 'r', expiresAt: Date.now() + 3600_000,
  uid: 'aliceUid', email: 'alice@example.com',
};

