test('what you just pinned is on the board before any run has filed it', async (t) => {
  // The defect this closes: sign in, pin one thing, open the board, and it
  // said "Nothing here yet." three times — on the screen every failure message
  // in this product sends a learner to with the words "it is on your board".
  const p = await openOnBoard(t, home({
    'GET /board': {
      topics: [], suggestions: [],
      unfiled: [{ id: 'p1', title: 'Composite Indexes', gist: 'A composite index pre-sorts fields.' }],
    },
  }));
  const area = find(p.app, '[data-area=get-started]');
  assert.equal(text(find(area, 'h2')), 'Get Started');
  // The note is what keeps a pin distinguishable from a topic beside it, now
  // that they share an area.
  assert.match(text(find(area, '.note')), /Just pinned, and not filed into subjects yet\./);
  assert.equal(text(find(area, '.pin-card .label')), 'Composite Indexes');
  // Not a backlog: nothing counted but their own work, and nothing that clears.
  assert.ok(!/left|remaining|to clear|unread/i.test(text(find(p.app, '.board'))));
  // The pin remains the one direct lesson action. Details inspects or repairs
  // its receipt; neither control files, dismisses or empties anything.
  assert.equal(area.querySelectorAll('button').length, 2);
  assert.equal(text(find(area, '.pin-card .label')), 'Composite Indexes');
  assert.ok(button(area, 'Details'));
});

