test('SB-117: a source must be opened before its availability can be recorded, and the quote survives', async (t) => {
  let sent: unknown = null;
  const checked = {
    ...PIN_DETAIL,
    source: {
      ...PIN_DETAIL.source,
      availability: {
        status: 'unavailable' as const,
        checkedAt: '2026-08-27T04:00:00.000Z',
        checkedBy: 'learner' as const,
      },
    },
  };
  const p = await openOnBoard(t, home({
    'GET /board': PIN_ON_BOARD,
    'GET /pins/p1': PIN_DETAIL,
    'PUT /pins/p1/source-availability': (init: RequestInit | undefined) => {
      sent = JSON.parse(String(init?.body));
      return checked;
    },
  }));
  await clickButton(find(p.app, '.pin-card'), 'Details');

  const question = find(p.app, '.source-availability-question');
  assert.equal((question as unknown as HTMLElement).hidden, true);
  assert.equal(text(find(p.app, '.source-availability-state')), 'No link check saved.');
  assert.match(text(find(p.app, '.pinned blockquote')), /pre-sorts fields in the order/);

  await find(p.app, '.pinned .from a').fireEvent('click');
  assert.equal((question as unknown as HTMLElement).hidden, false);
  assert.match(text(find(p.app, '.source-availability-state')), /opened in a new tab/i);
  await clickButton(question, 'No, unavailable');

  assert.deepEqual(sent, { status: 'unavailable' });
  assert.equal((question as unknown as HTMLElement).hidden, true);
  assert.equal(text(find(p.app, '.source-availability-state')),
    'You could not open this link on 27 Aug. Your saved quote is still here.');
  assert.match(text(find(p.app, '.pinned blockquote')), /pre-sorts fields in the order/);
  assert.equal(find(p.app, '.pinned .from a').getAttribute('href'),
    'https://cloud.example.test/indexes');
  assert.ok(!paths(p).some((path) => path.includes('quick-take')),
    'checking source availability invoked the Tutor');
});

