test('SB-111: pin metadata edits preserve the receipt and send only learner-owned fields', async (t) => {
  let sent: Record<string, unknown> | null = null;
  const p = await openOnBoard(t, home({
    'GET /board': PIN_ON_BOARD,
    'GET /pins/p1': PIN_DETAIL,
    'PUT /pins/p1': (init: RequestInit | undefined) => {
      sent = JSON.parse(String(init?.body)) as Record<string, unknown>;
      return { ...PIN_DETAIL, ...sent, changed: true };
    },
  }));
  await clickButton(find(p.app, '.pin-card'), 'Details');
  const intent = find(p.app, '.pin-intent');
  intent.value = 'struggle';
  await intent.fireEvent('change');
  const level = find(p.app, '.pin-level');
  level.value = 'refresher';
  await level.fireEvent('change');
  await typeInto(find(p.app, '.pin-note'), 'I cannot explain the ordering rule.');
  await clickButton(p.app, 'Save changes');

  assert.deepEqual(sent, {
    type: 'struggle', note: 'I cannot explain the ordering rule.',
    requestedRegister: 'fluent', requestedMinutes: 1,
  });
  assert.match(text(find(p.app, '.pin-edit-status')), /original source and saved time did not change/i);
  assert.match(text(find(p.app, '.pinned blockquote')), /pre-sorts fields in the order/);
  assert.equal((find(p.app, '.pin-intent') as unknown as { value: string }).value, 'struggle');
  assert.equal((find(p.app, '.pin-level') as unknown as { value: string }).value, 'refresher');
  assert.equal(button(p.app, 'Save changes').disabled, true);
  assert.equal(p.dom.activeElement, find(p.app, '.pin-edit-status'));
});

