test('a pin-note edit states its Unicode boundary and sends exact text whole', async (t) => {
  const p = await openOnBoard(t, home({
    'GET /board': PIN_ON_BOARD,
    'GET /pins/p1': PIN_DETAIL,
    'PUT /pins/p1': { ...PIN_DETAIL, changed: true },
  }));
  await clickButton(find(p.app, '.pin-card'), 'Details');
  const form = find(p.app, '.pin-edit');
  const note = find(form, '.pin-note');
  const statusLine = find(form, '.pin-edit-status');
  assert.match(text(form), /Up to 1,000 characters\. I save the whole note\./);
  assert.equal(note.getAttribute('maxlength'), null);
  const writesBefore = paths(p).filter((path) => path === 'PUT /pins/p1').length;

  await typeInto(note, '📝'.repeat(1_001));
  await clickButton(form, 'Save changes');
  assert.equal(paths(p).filter((path) => path === 'PUT /pins/p1').length, writesBefore);
  assert.equal(note.value, '📝'.repeat(1_001));
  assert.equal(p.dom.activeElement, note);
  assert.equal(text(statusLine),
    'That note is 1,001 characters. Keep it to 1,000 so I can save all of it. Nothing was sent.');

  const exact = '📝'.repeat(1_000);
  await typeInto(note, exact);
  await clickButton(form, 'Save changes');
  const sent = p.requests.filter((request) =>
    request.method === 'PUT' && request.url.endsWith('/pins/p1'))[0]!;
  assert.equal((sent.body as Record<string, unknown>).note, exact);
});

test('the take on the page is a lesson in Learn, and Board remains its way back', async (t) => {
  // The compact extension still owns a one-column quick-take screen. On the
  // full page, a lesson opened from the board belongs in the same two-column
  // Learn shell as every prepared lesson. The face toggle is the way back.
  const p = await openOnBoard(t, home({
    'GET /board': PIN_ON_BOARD,
    'POST /pins/p1/quick-take': take({
      label: 'Composite Indexes', topicLabel: 'Composite Indexes',
      heading: 'Why composite field order matters', topicId: 't-index',
      pinned: {
        text: 'A composite index pre-sorts fields.', kind: 'selection',
        pageTitle: 'Index notes', url: 'https://example.test/indexes', note: null,
      },
    }),
    'POST /external': { entry: { id: 'e-foreground' } },
  }));
  const columns = find(p.app, '.room-columns');
  const main = find(p.app, '.room-main');
  const rail = find(p.app, '.room-rail');
  await clickButton(find(p.app, '.pin-card'), 'Composite Indexes');
  assert.equal(p.app.dataset.room, 'today');
  assert.equal(p.app.dataset.measure, 'wall', 'the foreground lesson keeps Learn\'s canonical measure');
  assert.equal(p.app.querySelectorAll('.masthead').length, 1, 'the page keeps its top bar');
  assert.equal(p.app.querySelectorAll('.room-board').length, 1, 'and the room is on the canvas');
  assert.equal(find(p.app, '.room-columns'), columns, 'the two-column shell was rebuilt');
  assert.equal(find(p.app, '.room-main'), main, 'the lesson moved to another main column');
  assert.equal(find(p.app, '.room-rail'), rail, 'the teaching rail was rebuilt');
  assert.ok(find(p.app, '.next-action'), 'the lesson did not enter the anchored Learn card');
  assert.ok(find(p.app, '.foreground-lesson'));
  assert.equal(text(find(p.app, '.foreground-lesson [data-lesson-part="family"]')),
    'Composite Indexes');
  assert.equal(text(find(p.app, '.foreground-lesson [data-lesson-part="area"]')),
    'Why composite field order matters');
  assert.deepEqual(
    find(p.app, '.foreground-lesson [data-lesson-part="controls"]')
      .querySelectorAll('button').map((control) => text(control)),
    ['Got it', 'Refresh later', 'Explain another way', 'Go deeper', 'Not now'],
  );
  assert.equal(find(p.app, '.foreground-lesson-rail').querySelectorAll('[data-verdict]').length, 0);
  assert.deepEqual(find(p.app, '.gemini-routes .routes').querySelectorAll('button').map((control) => text(control)),
    ['New tab', 'Pop out', 'Side panel', 'Google Notebook']);
  assert.equal(find(p.app, '.foreground-source').getAttribute('open'), null,
    'foreground source evidence should use the canonical folded treatment');

  const foreground = find(p.app, '.foreground-lesson');
  await clickButton(find(p.app, '.learn-mode-toggle'), 'Lineup');
  assert.equal(p.app.querySelectorAll('.foreground-lesson').length, 0);
  assert.equal(text(find(p.app, '.time-choice [data-time-label]')), 'Session length');
  await clickButton(find(p.app, '.learn-mode-toggle'), 'Current');
  assert.equal(find(p.app, '.foreground-lesson'), foreground,
    'a pin lesson was rebuilt after inspecting its lineup');

  await clickButton(find(p.app, '.gemini-routes'), 'Google Notebook');
  await settle();
  assert.ok(paths(p).includes('POST /notebook/export'),
    'the foreground lesson did not offer its exact document to the managed Drive writer');
  const notebookWrite = p.requests.find((request) => request.url.endsWith('/notebook/export'))!;
  const sentForeground = (notebookWrite.body as {
    foreground?: { key?: string; title?: string; body?: string };
  }).foreground;
  assert.deepEqual({ key: sentForeground?.key, title: sentForeground?.title },
    { key: 'learn-now', title: 'Virgil: learn now' });
  assert.match(sentForeground?.body ?? '', /Composite Indexes/);
  assert.match(sentForeground?.body ?? '', /An index covers a query/);
  assert.match(p.c.clipboard.at(-1) ?? '', /Composite Indexes/);
  assert.match(p.c.clipboard.at(-1) ?? '', /An index covers a query/);
  const external = p.requests.find((request) => request.url.endsWith('/external'))!;
  assert.equal(typeof (external.body as { clientRef?: unknown }).clientRef, 'string');
  assert.deepEqual({ ...external.body as object, clientRef: '<client>' }, {
    kind: 'lesson', label: 'Why composite field order matters', destination: 'notebook',
    topicId: 't-index', sessionId: null, clientRef: '<client>',
  });

  await clickButton(find(p.app, '.face-toggle'), 'Board');
  assert.equal(p.app.dataset.room, 'today');
  assert.ok(p.app.querySelector('.board'));
  assert.equal(text(find(p.app, '.pin-card .label')), 'Composite Indexes',
    'and the pin they came from is where they left it');
});

test('a foreground lesson survives face switches and protects its typed question', async (t) => {
  const p = await openOnBoard(t, home({
    'GET /board': PIN_ON_BOARD,
    'POST /pins/p1/quick-take': take({ label: 'Composite Indexes' }),
  }));
  await clickButton(find(p.app, '.pin-card'), 'Composite Indexes');
  const lesson = find(p.app, '.foreground-lesson');
  const box = find(p.app, '.foreground-lesson-rail .ask-box');
  await typeInto(box, 'Can you compare the two index orders?');

  await clickButton(find(p.app, '.face-toggle'), 'Board');
  assert.ok(find(p.app, '.unsent-warning'), 'the face toggle discarded a typed quick-lesson question');
  assert.equal(find(p.app, '.room-columns').getAttribute('data-face'), 'learn');
  await clickButton(p.app, 'Keep editing');
  assert.equal(p.dom.activeElement, box);

  await typeInto(box, '');
  await clickButton(find(p.app, '.face-toggle'), 'Board');
  await clickButton(find(p.app, '.face-toggle'), 'Up next');
  assert.equal(find(p.app, '.foreground-lesson'), lesson,
    'returning to Learn rebuilt and lost the generated foreground lesson');
  assert.match(text(find(lesson, '.body')), /index covers a query/i);
});

