test('SB-283: a take the learner walks away from writes nothing at all', async (t) => {
  /**
   * The half of the check-in that is a promise rather than a feature. The
   * close is optional, and leaving is a legitimate way to answer it: a read
   * that produced no tap is a read that produced no tap, and inventing a mark
   * out of somebody navigating away would be the ledger reporting behaviour
   * nobody performed. It is also the difference between a check-in and a
   * gate, which is the line PRODUCT_SHAPE.md's second surface is drawn on.
   */
  const p = await openOnBoard(t, home({
    'GET /board': PIN_ON_BOARD,
    'POST /pins/p1/quick-take': take({ label: 'Composite Indexes' }),
    'POST /pins/p1/quick-take/verdict': { ok: true, verdict: 'got-it' },
  }));
  await clickButton(find(p.app, '.pin-card'), 'Composite Indexes');
  assert.deepEqual(find(p.app, '.foreground-lesson').querySelectorAll('[data-verdict]').map((node) => text(node)),
    ['Got it', 'Refresh later', 'Not now'],
    'the close was not offered, so walking past it proves nothing');
  assert.equal(find(p.app, '.foreground-lesson-rail').querySelectorAll('[data-verdict]').length, 0);

  await clickButton(p.app, 'Learn');
  assert.equal(p.app.querySelectorAll('.quick-take').length, 0, 'the room did not close');
  assert.deepEqual(paths(p).filter((path) => path.endsWith('/quick-take/verdict')), [],
    'a read the learner never closed became a mark they never made');
});

