// ============================================================== the Process button


const batch = (over: Record<string, unknown> = {}): Record<string, unknown> => ({
  run: false, because: 'nothing-new', line: 'Nothing new to process.',
  unprocessedPins: 0, estimatedCalls: 6, autoAfter: null, ...over,
});

test('the board says what is waiting and what running it would cost', async (t) => {
  const p = await openOnBoard(t, home({
    'GET /batch': batch({
      because: 'waiting-for-more', unprocessedPins: 3, estimatedCalls: 9,
      line: '3 things waiting. Press Process when you want them worked through.',
    }),
  }));
  const bar = find(p.app, '[data-zone=process]');
  assert.equal(bar.getAttribute('data-guide-section'), 'process');
  assert.match(text(bar), /3 things waiting/);
  // The cost is on the screen, because "saves money" is a claim a learner
  // should be able to check rather than take.
  assert.match(text(bar), /9/);
  assert.match(text(bar), /Cloud\/API · ready/);
  assert.ok(button(p.app, 'Process').listenerCount > 0);
});

