/**
 * A CHECKED LESSON IS WAITING, WHICH IS NOT NOTHING.
 *
 * The rule already existed — a checked lesson must not compete with a fresh
 * seven-call build before it has been opened — and it hung off the run receipt,
 * which only the visit that started the run ever sees. Come back the next
 * evening and the strip offered to build another one over the top of a lesson
 * that was built, checked and untouched.
 */
test('a built lesson nobody has begun owns the strip on any visit, not only after the run', async (t) => {
  const p = await openOnBoard(t, home({
    'GET /board': {
      topics: [{ ...topic('t1', 'TLS', 'settled', 2), area: 'learnt' }], suggestions: [],
    },
    'GET /batch': batch(),
  }));
  const bar = find(p.app, '[data-zone=process]');
  assert.match(text(bar), /Your lesson is ready when you are/);
  assert.doesNotMatch(text(bar), /Nothing new is waiting/);
  assert.ok(button(bar, 'Open the lesson').listenerCount > 0);
  assert.throws(() => button(bar, 'Build a refresh'),
    'the ready lesson competed with a fresh build on the next visit');
  assert.throws(() => button(bar, 'Build a lesson'));
  assert.throws(() => button(bar, 'Process'));
  assert.equal(bar.querySelectorAll('button').length, 1, 'one action per strip');
  assert.doesNotMatch(text(bar), /model calls/,
    'a lesson that has already been paid for was priced a second time');
  await clickButton(bar, 'Open the lesson');
  assert.equal(text(find(p.app, '.section .lesson-area')), 'How TLS gets its keys',
    'the strip named a lesson and opened something else');
});

test('a lesson the learner has already started leaves the ordinary strip alone', async (t) => {
  /**
   * There is no record anywhere of a lesson being opened, and there must not be
   * one: drawing a screen writes nothing. What the store keeps is the resume
   * pointer and what has been done, which is the same fact `/today` reads to
   * say Start rather than Continue. A session with work in it is a session
   * somebody is in the middle of, and the strip goes back to its own business.
   */
  const p = await openOnBoard(t, home({
    'GET /session': {
      session: session({
        sections: [
          section({ completed: true, completionEvidence: 'answer', question: null }),
          section({ topicId: 't2', heading: 'Why forward secrecy', question: null }),
        ],
        currentSectionIndex: 1,
      }),
      card: card(),
    },
    'GET /board': {
      topics: [{ ...topic('t1', 'TLS', 'settled', 2), area: 'learnt' }], suggestions: [],
    },
    'GET /batch': batch(),
  }));
  const bar = find(p.app, '[data-zone=process]');
  assert.match(text(bar), /Nothing new is waiting/);
  assert.ok(button(bar, 'Build a refresh'));
  assert.throws(() => button(bar, 'Open the lesson'));
});

/**
 * SB-280's proposals are waiting on somebody too.
 *
 * `GET /batch` knows about pins and knows nothing about the night scout, so a
 * board with three unanswered proposals on it was told that nothing new was
 * waiting. The offer under that clause is still true and stays; the clause goes,
 * and one quiet sentence says where the three actually are.
 */
const proposed = (n: number): { proposals: Record<string, unknown>[] } => ({
  proposals: Array.from({ length: n }, (_, i) => ({
    id: `pr${i + 1}`,
    subject: `An introduction to eigenvalues ${i + 1}`,
    reason: 'Two of your sources assume it and nothing on your board covers it.',
    evidenceKind: 'prerequisite-hole',
    evidenceDetail: '2 of your sources assume you already know: eigenvalues',
    lead: null,
  })),
});

const SETTLED_BOARD_WITH_PROPOSALS: Table = {
  ...NO_SESSION,
  'GET /board': {
    topics: [{ ...topic('t1', 'TLS', 'settled', 2), area: 'learnt' }], suggestions: [],
  },
  'GET /batch': batch(),
  'GET /prospects': proposed(3),
};

test('proposals waiting in My studies stop the strip saying nothing is waiting', async (t) => {
  const p = await openOnBoard(t, home(SETTLED_BOARD_WITH_PROPOSALS));
  const bar = find(p.app, '[data-zone=process]');
  assert.doesNotMatch(text(bar), /Nothing new is waiting/,
    'three unanswered proposals were reported as nothing');
  assert.match(text(bar), /I have 3 suggestions waiting in My studies/);
  assert.match(text(bar), /short refresh/, 'the clause that was false went; the offer that was true stayed');
  // One accent, and it is still the build. The sentence is a quiet door beside
  // it rather than a second offer.
  assert.equal(bar.querySelectorAll('.primary').length, 1);
  p.route(studies(SETTLED_BOARD_WITH_PROPOSALS));
  await clickButton(bar, 'I have 3 suggestions waiting in My studies.');
  assert.equal(text(find(p.app, '.room-head h1')), 'My studies');
});

test('one proposal is one suggestion, said as a person would say it', async (t) => {
  const p = await openOnBoard(t, home({ ...SETTLED_BOARD_WITH_PROPOSALS, 'GET /prospects': proposed(1) }));
  assert.match(text(find(p.app, '[data-zone=process]')), /I have a suggestion waiting in My studies/);
});

test('a service too old to know about proposals leaves the strip exactly as it was', async (t) => {
  // A missing capability is not a fault. The route answers 404 here, which is
  // what a service that predates SB-280 does, and the board must not notice.
  const table = home(SETTLED_BOARD_WITH_PROPOSALS);
  delete table['GET /prospects'];
  const p = await openOnBoard(t, table);
  const bar = find(p.app, '[data-zone=process]');
  assert.match(text(bar), /Nothing new is waiting/);
  assert.match(text(bar), /short refresh/);
  assert.ok(button(bar, 'Build a refresh'));
  assert.doesNotMatch(text(bar), /My studies|suggestion/);
  assert.equal(bar.querySelector('.empty'), null, 'an absent endpoint was drawn as a failure');
});

test('the built lesson owns the action and the proposals stay a sentence beside it', async (t) => {
  // Both true at once: one action per strip, and it is the lesson. The
  // proposals are still said, because they are still waiting, and they lose
  // their door rather than the lesson losing its press.
  const p = await openOnBoard(t, home({
    'GET /board': {
      topics: [{ ...topic('t1', 'TLS', 'settled', 2), area: 'learnt' }], suggestions: [],
    },
    'GET /batch': batch(),
    'GET /prospects': proposed(3),
  }));
  const bar = find(p.app, '[data-zone=process]');
  assert.match(text(bar), /Your lesson is ready when you are/);
  assert.match(text(bar), /I have 3 suggestions waiting in My studies/,
    'the proposals stopped being said because a lesson was ready');
  assert.equal(bar.querySelectorAll('button').length, 1);
  assert.equal(text(button(bar, 'Open the lesson')), 'Open the lesson');
  assert.ok(find(bar, '.waiting-said'), 'the sentence kept a door and competed with the lesson');
});

test('a run already going is said on arrival, not only to whoever started it', async (t) => {
  /**
   * Found live on 2026-08-24. `POST /batch` has always answered "one is already
   * being built" and only the button that had just been pressed could hear it.
   * A night is minutes of model work, so a learner who starts one, walks away
   * and comes back was told nothing at all — and pressing again looked like it
   * had done something.
   */
  const p = await openOnBoard(t, home({
    'GET /batch': batch({
      unprocessedPins: 2, building: true, currentStage: 'forage',
      activity: {
        state: 'running', startedAt: '2026-08-26T00:00:00.000Z', finishedAt: null,
        currentStage: 'forage', outcome: null, remaining: 0, withheld: 0, failure: null,
        reports: [{ stage: 'intake', ms: 240, failed: false, degradeReason: null }],
      },
    }),
  }));
  const bar = find(p.app, '[data-zone=process]');
  assert.match(text(bar), /Reading 2 saved items/);
  assert.match(text(bar), /do not have to wait/);
  assert.match(text(bar), /1 step finished/);
  assert.match(text(bar), /Course sources reviewed/);
  // No control, because there is nothing left to press: a second press answers
  // "already" and a button that does nothing is worse than no button.
  assert.throws(() => button(p.app, 'Process'));
});

