test('Demo Advanced is a read-only allowance receipt and judge-only controls stay hidden', async (t) => {
  const demoSession = {
    ...SESSION, idToken: 'virgil-judge-v1.9999999999999.signature', refreshToken: '',
    uid: 'judge-workspace-v1', email: null,
  };
  const p = await openSettings(t, {
    'GET /judge/access': {
      active: true, dailyCloudTokens: 500_000, resets: '00:00 UTC',
      isolatedBoard: true, personalConnections: false,
    },
    'GET /tenant/members': {
      role: 'judge', editable: false, members: null,
      sharedModelSetup: true, isolatedBoard: true,
    },
  }, { sb_auth_config: CONFIG, sb_session: demoSession });

  const addPerson = find(p.app, '.tenant-add');
  assert.equal((addPerson as unknown as { hidden: boolean }).hidden, true,
    'the judge can see the owner-only Add person form');
  const css = readFileSync(fileURLToPath(new URL('../../panel.css', import.meta.url)), 'utf8');
  assert.match(css, /\[hidden\]\s*\{[^}]*display:\s*none\s*!important/,
    'a component display rule can still override the hidden attribute');

  const before = p.requests.length;
  await clickButton(p.app, 'Advanced');
  const advanced = find(p.app, '[data-settings-panel="models"]');
  assert.match(text(advanced), /read-only receipt/i);
  assert.match(text(advanced), /500,000 tokens per UTC day/);
  assert.match(text(advanced), /routing, connection checks, credentials and budget changes are held/i);
  assert.equal(advanced.querySelectorAll('button').length, 0);
  assert.equal(advanced.querySelectorAll('input').length, 0);
  assert.equal(advanced.querySelectorAll('select').length, 0);
  assert.deepEqual(p.requests.slice(before).map((request) => request.url.slice(SERVICE.length)),
    ['/judge/access'], 'Demo Advanced reached editable model endpoints while drawing its receipt');
});

