test('time changes are serialized inside Lineup without replacing Current', async (t) => {
  const p = await open(t, lined());
  await clickButton(p.app, 'Start');
  assert.equal(p.app.querySelectorAll('.time-choice').length, 0);
  await clickButton(find(p.app, '.learn-mode-toggle'), 'Lineup');
  const chips = find(p.app, '.time-choice');
  assert.equal(text(find(chips, '[data-time-label]')), 'Session length');

  let release!: (response: FakeResponse) => void;
  const pending = new Promise<FakeResponse>((resolve) => { release = resolve; });
  const base = serve(lined({ 'PUT /prefs': prefs({ availableMinutes: 1 }) }));
  p.c.fetchHandler = (url, init) => init?.method === 'PUT' && new URL(url).pathname === '/prefs'
    ? pending
    : base(url, init);

  const before = p.requests.length;
  const first = button(chips, '1 min').fireEvent('click');
  await settle();
  assert.equal(chips.getAttribute('aria-busy'), 'true');
  assert.ok(chips.querySelectorAll('button').every((control) => control.disabled),
    'a second budget could race the one already saving');
  const second = button(chips, '5 min').fireEvent('click');
  release(jsonResponse(prefs({ availableMinutes: 1 })));
  await Promise.all([first, second]);
  await settle();

  assert.equal(p.requests.slice(before).filter((request) => request.method === 'PUT').length, 1);
  assert.equal(button(chips, '1 min').getAttribute('aria-pressed'), 'true');
  assert.equal(button(chips, '5 min').getAttribute('aria-pressed'), 'false');
  assert.equal(chips.getAttribute('aria-busy'), null);
  assert.ok(chips.querySelectorAll('button').every((control) => !control.disabled));

  await clickButton(find(p.app, '.learn-mode-toggle'), 'Current');
  assert.equal(text(find(p.app, '.section .lesson-area')), 'How TLS gets its keys');
  assert.equal(p.app.querySelectorAll('.time-choice').length, 0);
});

/**
 * The due strip and the five-minute offer are gone from this page.
 *
 * Not because what is due stopped mattering: because `/today` already ranks it.
 * Both were drawn in a branch that ran only when `/today` was missing, and no
 * live service has ever been missing it, so the five tests that used to stand
 * here asserted the ordering, the counting rule and the tick of a strip nobody
 * saw. What is due leads the page whenever it is the most urgent thing, as the
 * hero, and the tick that scores it is in the Plan where the card is.
 */
test('the plan room states the score in words, at the foot of what is finished', async (t) => {
  const p = await open(t, home({
    'GET /plan': planTable({ points: 68, stars: 1 }),
    'POST /commitments': { commitment: COMMITMENT },
  }));
  await clickButton(p.app, 'Plan');
  // Stars and the points behind them. A star nobody can explain is a badge, and
  // this product does not ship badges nobody can check.
  assert.equal(text(find(p.app, '.score')), '1 star · 68 points');
  // Where it is, which is the change: it used to be the first sentence in the
  // learner's own plan. It is a record of what is behind them now, and it sits
  // at the foot of the record.
  assert.equal(find(p.app, '.score').parentElement, find(p.app, '.plan-done'),
    'the score climbed back out of the Done strip');

  // The form is behind Add, like every other way in (SB-80's inversion, applied
  // to the second room that opened with a form above what it knew).
  assert.equal(p.app.querySelectorAll('.add-commitment').length, 0,
    'the Plan still opens with a data-entry form in its body');
  await clickButton(p.app, 'Add');
  await typeInto(find(p.app, '.add-commitment .title'), 'Read chapter 4');
  await typeInto(find(p.app, '.add-commitment .due'), '2026-09-04');
  await clickButton(find(p.app, '.add-commitment'), 'Add it');
  const sent = lastWrite(p)!;
  assert.equal(sent.url, `${SERVICE}/commitments`);
  // `courseId` on the wire, and null here because this table's
  // `/outcome-context` answers with no courses to attach to. It was omitted
  // entirely until 2026-08-24, which is how every hand-typed deadline came to
  // belong to no course.
  assert.deepEqual(sent.body, {
    title: 'Read chapter 4', kind: 'assignment', dueAt: '2026-09-04', plannedFor: null,
    courseId: null, topicIds: [],
  });
});

