// --------------------------------------------------------------- the burst

const BURST = {
  minutes: 5,
  items: [{
    topicId: 't1', label: 'TLS', reason: 'due',
    prompt: 'Without opening your sources, explain TLS in your own words. What is the most important idea you remember?',
  }],
};

/**
 * `/today` offering the five minutes, which is the door to this room now.
 *
 * It used to be a zone of its own on the front page, drawn in the branch that
 * ran when `/today` was absent. Five minutes IS one of the things `/today`
 * ranks, so the offer and the ranking were the same decision made twice.
 */
const NEXT_BURST = {
  availableMinutes: 5,
  primary: {
    id: 'burst:t1', kind: 'burst', targetId: null, title: 'Take a five-minute recall burst',
    detail: 'One quick check from things you have already met.',
    minutes: 5, destination: 'burst', cta: 'Start burst',
    reasons: [{ code: 'review-due', text: 'At least one topic is due for recall.' }], rank: 500,
  },
  alternatives: [],
};

/** Into the burst room the way a learner gets there: the next move says so. */
const openBurst = async (p: Panel): Promise<void> => { await clickButton(p.app, 'Start burst'); };

test('a burst asks for written retrieval, one prompt at a time', async (t) => {
  const p = await open(t, home({
    'GET /burst': BURST,
    'POST /burst/answer': {
      ok: true, verdict: 'got-it',
      feedback: 'You recalled that TLS protects data in transit.',
    },
    'GET /today': { next: NEXT_BURST },
  }));
  await openBurst(p);
  assert.equal(text(find(p.app, '.burst-progress')), 'Recall 1 of 1');
  assert.match(text(find(p.app, '.burst-item .why')), /spaced review says today/);
  assert.match(text(find(p.app, '.burst-prompt')), /Without opening your sources/);
  assert.equal(p.dom.activeElement, find(p.app, '.burst-item textarea'));
  assert.equal(p.app.querySelectorAll('[data-yes]').length, 0,
    'a confidence tap cannot mint a positive recall signal');

  await clickButton(find(p.app, '.burst-item'), 'Check my recall');
  assert.match(text(find(p.app, '.burst-item .said')), /Write what you remember/);
  assert.equal(p.requests.filter((r) => r.url.endsWith('/burst/answer')).length, 0);

  find(p.app, '.burst-item textarea').value = 'TLS encrypts data moving between a client and server.';
  await clickButton(find(p.app, '.burst-item'), 'Check my recall');
  const answer = p.requests.filter((r) => r.url.endsWith('/burst/answer')).pop()!;
  const body = answer.body as Record<string, unknown>;
  assert.equal(body.topicId, 't1');
  assert.equal(body.answer, 'TLS encrypts data moving between a client and server.');
  assert.match(String(body.clientRef), /^[A-Za-z0-9_-]{8,160}$/);
  assert.equal(text(find(p.app, '.burst-item .said')),
    'You recalled that TLS protects data in transit.');
  assert.ok(find(p.app, '.burst-item textarea').disabled);
  assert.equal(text(find(p.app, '[data-next]')), 'Finish burst');
});

test('a burst answer is checked whole or kept for editing, never silently shortened', async (t) => {
  const p = await open(t, home({
    'GET /burst': BURST,
    'POST /burst/answer': { ok: true, verdict: 'got-it', feedback: 'I read the whole recall.' },
    'GET /today': { next: NEXT_BURST },
  }));
  await openBurst(p);
  const card = find(p.app, '.burst-item');
  const box = find(card, 'textarea');
  await typeInto(box, '🙂'.repeat(1_501));
  await clickButton(card, 'Check my recall');
  assert.equal(p.requests.filter((r) => r.url.endsWith('/burst/answer')).length, 0);
  assert.match(text(find(card, '.said')), /1,501 characters.*keep it to 1,500.*nothing was sent/i);
  assert.equal(box.value, '🙂'.repeat(1_501));
  assert.equal(p.dom.activeElement, box);

  await typeInto(box, '🙂'.repeat(1_500));
  await clickButton(card, 'Check my recall');
  const body = p.requests.filter((r) => r.url.endsWith('/burst/answer')).pop()!.body as Record<string, unknown>;
  assert.equal(body.answer, '🙂'.repeat(1_500), 'the Unicode boundary recall was shortened before send');
});

test('not remembering is useful evidence and needs no invented answer', async (t) => {
  const p = await open(t, home({
    'GET /burst': BURST,
    'POST /burst/answer': { ok: true, verdict: 'not-really', feedback: null },
    'GET /today': { next: NEXT_BURST },
  }));
  await openBurst(p);

  await clickButton(find(p.app, '.burst-item'), "I don't remember");
  const answer = p.requests.filter((r) => r.url.endsWith('/burst/answer')).pop()!;
  const body = answer.body as Record<string, unknown>;
  assert.equal(body.topicId, 't1');
  assert.equal(body.verdict, 'not-really');
  assert.match(String(body.clientRef), /^[A-Za-z0-9_-]{8,160}$/);
  // Saying “I don't remember” is what makes the next session useful. A product that
  // sounds disappointed by it is one people stop saying it to.
  assert.match(text(find(p.app, '.burst-item .said')), /bring it back sooner/);
  assert.ok(!/wrong|incorrect|failed/i.test(text(find(p.app, '.burst-item'))));
});

test('finishing a burst describes checked topics without rewarding participation', async (t) => {
  const p = await open(t, home({
    'GET /burst': BURST,
    'POST /burst/answer': { ok: true, verdict: 'not-really', feedback: null },
    'GET /today': { next: NEXT_BURST },
  }));
  await openBurst(p);
  await clickButton(find(p.app, '.burst-item'), "I don't remember");
  assert.equal(p.requests.filter((r) => r.url.endsWith('/burst/done')).length, 0,
    'an accepted recall answer needs no participation write');
  await clickButton(find(p.app, '.burst-item'), 'Finish burst');
  const dones = p.requests.filter((r) => r.url.endsWith('/burst/done'));
  assert.equal(dones.length, 0, 'finishing the room manufactured a second write');
  assert.equal(text(find(p.app, '.burst-end .earned')), 'Burst finished · 1 topic checked.');
  assert.doesNotMatch(text(find(p.app, '.burst-end')), /point|star|award|\+\d/i);
  assert.equal(text(find(p.app, '[data-home]')), 'Continue in Learn');
});

test('a finished burst closes into Learn with its receipt', async (t) => {
  const p = await open(t, home({
    'GET /burst': BURST,
    'POST /burst/answer': { ok: true, verdict: 'not-really', feedback: null },
    'GET /today': { next: NEXT_BURST },
  }));
  await openBurst(p);
  await clickButton(find(p.app, '.burst-item'), "I don't remember");
  await clickButton(find(p.app, '.burst-item'), 'Finish burst');
  const receipt = text(find(p.app, '.burst-end .earned'));

  await clickButton(p.app, 'Continue in Learn');
  assert.equal(p.app.querySelectorAll('.burst').length, 0, 'the completed recall room stayed open');
  assert.equal(text(find(p.app, '.build-note')), receipt,
    'Learn dropped the recall result during the return');
});

test('a burst finish cannot lose a second write because the answers already landed', async (t) => {
  let finishes = 0;
  const p = await open(t, home({
    'GET /burst': BURST,
    'POST /burst/answer': { ok: true, verdict: 'not-really', feedback: null },
    'POST /burst/done': () => {
      finishes += 1;
      return DOWN;
    },
    'GET /today': { next: NEXT_BURST },
  }));
  await openBurst(p);
  await clickButton(find(p.app, '.burst-item'), "I don't remember");
  const finish = button(find(p.app, '.burst-item'), 'Finish burst');
  await click(finish);
  assert.equal(finishes, 0, 'the already-recorded recall gained a fallible finish request');
  assert.ok(find(p.app, '.burst-end'));
  assert.equal(text(find(p.app, '.burst-end .earned')), 'Burst finished · 1 topic checked.');
});

test('an answer that does not land is not recorded as one', async (t) => {
  const p = await open(t, home({
    'GET /burst': BURST, 'POST /burst/answer': DOWN, 'GET /today': { next: NEXT_BURST },
  }));
  await openBurst(p);
  find(p.app, '.burst-item textarea').value = 'TLS protects a connection.';
  await clickButton(find(p.app, '.burst-item'), 'Check my recall');
  assert.match(text(find(p.app, '.burst-item .said')),
    /I could not save that.*recall answer is still here/);
  assert.equal(p.app.querySelectorAll('.burst-end').length, 0, 'and the burst did not end');
});

