test('a screenshot becomes an editable course source before it can become a plan', async (t) => {
  installCanvas(t);
  installImageDecoder(t);
  const p = await open(t, home({
    'GET /courses': { courses: [] },
    'GET /course-intakes': { drafts: [] },
    'POST /transcribe-pages': {
      outcome: 'transcribed',
      text: 'Course: Distributed Systems\nAssignment due 12 September 2026',
      pageCount: 1,
    },
    'POST /course-intakes': { draft: { id: 'd-image' }, extraction: 'deterministic' },
  }));
  await clickButton(p.app, 'My studies');
  await clickButton(p.app, 'Add');

  const sourcePicker = find(p.app, 'input[data-file-source]');
  const folderPicker = find(p.app, 'input[data-folder-source]');
  assert.match(sourcePicker.getAttribute('accept') ?? '', /\.png/);
  assert.doesNotMatch(folderPicker.getAttribute('accept') ?? '', /\.png/,
    'the unattended folder reader started advertising pictures it cannot transcribe');

  const beforeReview = paths(p).filter((path) => path === 'POST /course-intakes').length;
  await pickFile(sourcePicker, stubFile('semester-plan.png', new Uint8Array([1, 2, 3]), 'image/png'));

  assert.equal(find(p.app, '.source-text').value,
    'Course: Distributed Systems\nAssignment due 12 September 2026');
  assert.equal(text(find(p.app, '.intake-start .read-note')),
    'I read the image and typed it into the source box. Check the words against the picture before you review the import.');
  assert.equal(paths(p).filter((path) => path === 'POST /course-intakes').length, beforeReview,
    'transcribing the screenshot imported it before learner review');
  const transcribe = p.requests.find((request) =>
    request.method === 'POST' && request.url.endsWith('/transcribe-pages'))!;
  const media = (transcribe.body as { media: string[] }).media;
  assert.equal(media.length, 1);
  assert.match(media[0] ?? '', /^data:image\/jpeg;base64,[A-Za-z0-9+/]+=*$/);

  await clickButton(p.app, 'Review the import');
  const review = p.requests.find((request) =>
    request.method === 'POST' && request.url.endsWith('/course-intakes'))!;
  assert.deepEqual(review.body, {
    kind: 'syllabus',
    title: '',
    text: 'Course: Distributed Systems\nAssignment due 12 September 2026',
    enhance: false,
  });
});

test('SB-156: one folder becomes board material and reviewable plan proposals in one gesture', async (t) => {
  let imported = false;
  const p = await open(t, studies({
    'GET /courses': { courses: [], unattached: { commitments: [], topics: [] } },
    'GET /course-intakes': () => ({ drafts: imported ? [INTAKE_DRAFT] : [] }),
    'POST /course-drops': () => {
      imported = true;
      return {
        read: 3, failed: 0, planned: 2,
        items: [{ draftId: 'd1' }, { draftId: 'd2' }, { draftId: null }],
        queue: { nights: 1 },
      };
    },
  }));
  await clickButton(p.app, 'My studies');
  await clickButton(p.app, 'Add');

  const picker = find(p.app, 'input[data-folder-source]');
  assert.equal(picker.getAttribute('webkitdirectory'), '');
  const files = [
    Object.assign(stubFile('unit-outline.md', 'Course: Agent Systems\nLearning outcomes\nAssessment schedule'),
      { webkitRelativePath: 'Autumn/unit-outline.md' }),
    Object.assign(stubFile('marking-rubric.md', 'Marking criteria\nEvidence: 40%'),
      { webkitRelativePath: 'Autumn/assessment/marking-rubric.md' }),
    Object.assign(stubFile('lecture-01.md', 'A lecture about tool boundaries.'),
      { webkitRelativePath: 'Autumn/notes/lecture-01.md' }),
  ];
  await pickFiles(picker, files);
  await settle();

  const sent = p.requests.find((request) => request.method === 'POST' && request.url.endsWith('/course-drops'))!;
  assert.ok(sent, 'the folder never reached the semester endpoint');
  const body = sent.body as { title: string; dropId: string; items: { kind: string; clientRef: string }[] };
  assert.equal(body.title, 'Autumn');
  assert.match(body.dropId, /^drop-[^:]+$/);
  assert.deepEqual(body.items.map((item) => item.kind),
    ['syllabus', 'rubric', 'learner-note']);
  assert.deepEqual((sent.body as { items: { name: string }[] }).items.map((item) => item.name), [
    'unit-outline.md',
    'assessment/marking-rubric.md',
    'notes/lecture-01.md',
  ]);
  assert.deepEqual(body.items.map((item) => item.clientRef), [
    'item-1',
    'item-2',
    'item-3',
  ]);
  assert.match(text(find(p.app, '.course-drop-notice')),
    /3 files are on your board.*2 plan proposals need your eye.*1 run/);
  assert.equal(find(p.app, '.intake-review').getAttribute('data-draft'), 'd1');
  assert.equal(p.dom.activeElement, find(p.app, '.intake-review'),
    'the learner did not land on the proposal the folder made');
});

test('SB-156: a failed folder import keeps one idempotent payload and one exact retry', async (t) => {
  const p = await open(t, studies({
    'GET /courses': { courses: [], unattached: { commitments: [], topics: [] } },
    'POST /course-drops': DOWN,
  }));
  await clickButton(p.app, 'My studies');
  await clickButton(p.app, 'Add');
  await pickFiles(find(p.app, 'input[data-folder-source]'), [
    Object.assign(stubFile('notes.md', 'Reliable notes'),
      { webkitRelativePath: 'Security/notes.md' }),
  ]);

  const retry = button(p.app, 'Finish folder import');
  assert.match(text(find(p.app, '.folder-status')), /could not confirm the first part.*still ready here.*will not duplicate/i);
  assert.equal(p.dom.activeElement, retry);
  const first = p.requests.find((request) => request.method === 'POST' && request.url.endsWith('/course-drops'))!;

  p.route(studies({
    'GET /courses': { courses: [], unattached: { commitments: [], topics: [] } },
    'POST /course-drops': {
      read: 1, failed: 0, planned: 0, items: [{ draftId: null }], queue: { nights: 1 },
    },
  }));
  await click(retry);
  const writes = p.requests.filter((request) => request.method === 'POST' && request.url.endsWith('/course-drops'));
  assert.equal(writes.length, 2);
  assert.deepEqual(writes[1]!.body, first.body, 'retry minted a second semester instead of resuming the first');
  assert.match(text(find(p.app, '.course-drop-notice')), /1 file is on your board.*No plan proposals/);
});

test('SB-164: folder filenames never become internal retry identities', async (t) => {
  const attempts: { clientRef: string; name: string }[][] = [];
  const p = await open(t, studies({
    'GET /courses': { courses: [], unattached: { commitments: [], topics: [] } },
    'GET /course-intakes': { drafts: [] },
    'POST /course-drops': (init: RequestInit | undefined) => {
      const sent = JSON.parse(String(init?.body)) as {
        items: { clientRef: string; name: string }[];
      };
      attempts.push(sent.items);
      if (sent.items.some((item) => item.clientRef.includes('\u200B')
        || Array.from(item.clientRef).length > 180)) return status(400);
      return {
        read: sent.items.length, failed: 0, planned: 0,
        items: sent.items.map((item) => ({ ok: true, name: item.name, draftId: null })),
        queue: { nights: 1 },
      };
    },
  }));
  await clickButton(p.app, 'My studies');
  await clickButton(p.app, 'Add');

  const longFolder = `${'reference-material/'.repeat(14)}week`;
  await pickFiles(find(p.app, 'input[data-folder-source]'), [
    Object.assign(stubFile('notes-a.md', 'First set of notes'), {
      webkitRelativePath: `Autumn/week\u200B-01/${longFolder}/notes-a.md`,
    }),
    Object.assign(stubFile('notes-b.md', 'Second set of notes'), {
      webkitRelativePath: `Autumn/week-02/${longFolder}/notes-b.md`,
    }),
  ]);
  await settle();

  assert.equal(attempts.length, 1, 'a valid folder identity was refused before import');
  assert.deepEqual(attempts[0]!.map((item) => item.clientRef), ['item-1', 'item-2']);
  assert.match(attempts[0]![0]!.name, /week\u200B-01\/.*notes-a\.md$/,
    'making retry identity safe erased the human-visible source path');
  assert.match(text(find(p.app, '.course-drop-notice')), /2 files are on your board/);
  assert.equal(p.app.querySelector('[data-send-folder]'), null,
    'the accepted folder was left behind as an impossible retry');
});

