test('SB-157: the folder chunk ceiling stays below and equal to the service ceiling', () => {
  const panelSource = readFileSync(fileURLToPath(new URL('../../src/panel.ts', import.meta.url)), 'utf8');
  const serviceSource = readFileSync(fileURLToPath(new URL('../../../runner/src/service.ts', import.meta.url)), 'utf8');
  const panel = /COURSE_DROP_REQUEST_BYTES\s*=\s*(\d+)\s*\*\s*1024\s*\*\s*1024/.exec(panelSource);
  const service = /REQUEST_BODY_LIMIT_BYTES\s*=\s*(\d+)\s*\*\s*1024\s*\*\s*1024/.exec(serviceSource);
  assert.ok(panel && service, 'one half stopped declaring the request ceiling');
  assert.equal(Number(panel[1]), 28);
  assert.equal(Number(panel[1]), Number(service[1]));
  assert.match(panelSource, /mapPayloadChunks/);
  assert.match(serviceSource, /bytes > REQUEST_BODY_LIMIT_BYTES/,
    'a lying or absent content-length can still grow without a ceiling');
});

test('SB-157: folder chunks preserve every item and include the complete JSON envelope in the ceiling', () => {
  const payloadFor = (items: string[]) => ({ dropId: 'same-drop', title: '秋', items });
  const twoItemBytes = new TextEncoder().encode(JSON.stringify(payloadFor(['α', 'β']))).byteLength;
  const chunks = chunkByPayloadBytes(['α', 'β', 'γ', 'δ', 'ε'], payloadFor, twoItemBytes);
  assert.deepEqual(chunks, [['α', 'β'], ['γ', 'δ'], ['ε']]);
  assert.deepEqual(chunks.flat(), ['α', 'β', 'γ', 'δ', 'ε']);
  for (const chunk of chunks) {
    assert.ok(new TextEncoder().encode(JSON.stringify(payloadFor(chunk))).byteLength <= twoItemBytes);
  }
  assert.throws(
    () => chunkByPayloadBytes(['too-big'], payloadFor, 1, () => new Error('named refusal')),
    /named refusal/,
  );
});

test('SB-158: folder extraction stops at each wire chunk instead of retaining the whole folder', async () => {
  const mapped: string[] = [];
  const payloadFor = (items: string[]) => ({ dropId: 'one-drop', items });
  const oneItemBytes = new TextEncoder().encode(JSON.stringify(payloadFor(['aaaa']))).byteLength;
  const chunks = mapPayloadChunks(
    ['a', 'b', 'c', 'd'],
    async (input) => { mapped.push(input); return 'aaaa'; },
    payloadFor,
    oneItemBytes,
  );
  const first = await chunks.next();
  assert.deepEqual(first.value && [...first.value.items], ['aaaa']);
  assert.deepEqual(mapped, ['a', 'b'], 'the whole folder was extracted before the first request could send');
  await chunks.return();
  assert.deepEqual(mapped, ['a', 'b'], 'abandoning a failed send still read later files');

  const allMapped: string[] = [];
  const all: string[][] = [];
  for await (const chunk of mapPayloadChunks(
    ['a', 'b', 'c'],
    async (input) => { allMapped.push(input); return input.repeat(4); },
    payloadFor,
    oneItemBytes,
  )) all.push([...chunk.items]);
  assert.deepEqual(all, [['aaaa'], ['bbbb'], ['cccc']]);
  assert.deepEqual(allMapped, ['a', 'b', 'c']);
});

