test('SB-162: partial progress survives same-account sign-in with one safe finish action', async (t) => {
  let calls = 0;
  const authPath = 'POST http://127.0.0.1:9099/identitytoolkit.googleapis.com/v1/accounts'
    + ':signInWithIdp?key=fake-api-key';
  const p = await open(t, studies({
    'GET /courses': { courses: [], unattached: { commitments: [], topics: [] } },
    'POST /course-drops': (init: RequestInit | undefined) => {
      calls += 1;
      if (calls > 1) return status(401);
      const sent = JSON.parse(String(init?.body)) as { items: unknown[] };
      return {
        read: sent.items.length, failed: 0, planned: 0,
        items: sent.items.map(() => ({ ok: true, draftId: null })),
        queue: { nights: 1 },
      };
    },
  }), true, { sb_auth_config: CONFIG, sb_session: SESSION });
  await clickButton(p.app, 'My studies');
  await clickButton(p.app, 'Add');

  // Thirty near-cap text files force two requests under the real 28 MiB wire
  // ceiling without changing production constants for a test. The generator
  // releases each extracted chunk; the original File handles remain retryable.
  const body = 'a'.repeat(980_000);
  const files = Array.from({ length: 30 }, (_, index) => Object.assign(
    stubFile(`notes-${index + 1}.md`, body),
    { webkitRelativePath: `Autumn/week-${index + 1}/notes.md` },
  ));
  await pickFiles(find(p.app, 'input[data-folder-source]'), files);
  await settle();

  const writes = p.requests.filter((request) => request.method === 'POST' && request.url.endsWith('/course-drops'));
  assert.equal(writes.length, 2, 'the fixture stopped exercising the cross-request failure boundary');
  const confirmed = (writes[0]!.body as { items: unknown[] }).items.length;
  assert.ok(confirmed > 0 && confirmed < files.length);
  assert.equal(text(find(p.app, 'h1')), 'Sign in');

  p.route(studies({
    'GET /courses': { courses: [], unattached: { commitments: [], topics: [] } },
    [authPath]: {
      idToken: 'alice-live-token', refreshToken: 'alice-refresh', expiresIn: '3600',
      localId: 'aliceUid', email: 'alice@example.com',
    },
  }));
  await clickButton(p.app, 'Continue with Google');
  assert.equal(text(find(p.app, 'h1')), 'My studies');
  const line = text(find(p.app, '.folder-status'));
  assert.match(line, new RegExp(`^${confirmed} of ${files.length} files were checked`));
  assert.match(line, /already on your board/);
  assert.match(line, /Retry will not duplicate them/);
  const finish = button(p.app, 'Finish folder import');
  assert.equal(p.dom.activeElement, finish);
  assert.equal(paths(p).filter((path) => path === 'POST /course-drops').length, 2,
    'sign-in automatically replayed a folder write');
});

