test('source review publishes its whole Unicode bounds and keeps overflow unsent', async (t) => {
  const p = await open(t, home({
    'GET /courses': { courses: [] }, 'GET /course-intakes': { drafts: [] },
    'POST /course-intakes': { draft: { id: 'd-exact' } },
  }));
  await clickButton(p.app, 'My studies');
  await clickButton(p.app, 'Add');
  const form = find(p.app, '.intake-start');
  assert.match(text(form), /Up to 160 characters\. I save the whole source name\./);
  assert.match(text(form), /Up to 60,000 characters\. I keep the whole source for review\./);
  const title = find(form, '.source-title');
  const source = find(form, '.source-text');
  const writesBefore = paths(p).filter((path) => path === 'POST /course-intakes').length;

  await typeInto(title, '🙂'.repeat(161));
  await typeInto(source, 'Course: Exact');
  await clickButton(form, 'Review the import');
  assert.equal(paths(p).filter((path) => path === 'POST /course-intakes').length, writesBefore);
  assert.equal(p.dom.activeElement, title);
  assert.match(text(find(form, '.note')), /Nothing was sent\./);

  const exactTitle = '📄'.repeat(160);
  await typeInto(title, exactTitle);
  await typeInto(source, '🙂'.repeat(60_001));
  await clickButton(form, 'Review the import');
  assert.equal(paths(p).filter((path) => path === 'POST /course-intakes').length, writesBefore);
  assert.equal(p.dom.activeElement, source);
  assert.equal(source.value, '🙂'.repeat(60_001));
  assert.match(text(find(form, '.note')), /That source is 60,001 characters.*Nothing was sent\./);

  const exactSource = '🧭'.repeat(60_000);
  await typeInto(source, exactSource);
  await clickButton(form, 'Review the import');
  const sent = p.requests.find((request) =>
    request.method === 'POST' && request.url.endsWith('/course-intakes'))!;
  assert.equal((sent.body as Record<string, unknown>).title, exactTitle);
  assert.equal((sent.body as Record<string, unknown>).text, exactSource);
});

