test('intake review publishes every text limit and keeps overflow unsent and editable', async (t) => {
  const p = await open(t, home({
    'GET /courses': { courses: [] }, 'GET /course-intakes': { drafts: [INTAKE_DRAFT] },
    'PATCH /course-intakes/d1': { draft: INTAKE_DRAFT },
  }));
  await clickButton(p.app, 'My studies');
  const review = find(p.app, '.intake-review');
  const reviewText = text(review);
  for (const copy of [
    'Course titles: up to 160 characters.',
    'Providers: up to 120 characters.',
    'Objectives: up to 300 characters.',
    'Material titles: up to 180 characters.',
    'Assignment titles: up to 180 characters.',
  ]) assert.ok(reviewText.includes(copy), copy);

  const cases = [
    ['.course-detail-fields .name', 'Save title', 161, '.detail-note', ''],
    ['input[aria-label="Provider"]', 'Save provider', 121, '.detail-note', ''],
    ['.correct-objective', 'Save objective', 301, '.objective-proposal .note', '.objective-proposal'],
    ['.correct-material-title', 'Save title', 181, '.material-proposal .note', '.material-proposal'],
    ['.correct-commitment-title', 'Save assignment', 181,
      '.commitment-proposal .note', '.commitment-proposal'],
  ] as const;
  const writesBefore = paths(p).filter((path) => path === 'PATCH /course-intakes/d1').length;
  for (const [selector, label, count, statusSelector, ownerSelector] of cases) {
    const field = find(review, selector);
    await typeInto(field, '🙂'.repeat(count));
    await clickButton(ownerSelector ? find(review, ownerSelector) : review, label);
    assert.equal(paths(p).filter((path) => path === 'PATCH /course-intakes/d1').length, writesBefore);
    assert.equal(field.value, '🙂'.repeat(count));
    assert.equal(p.dom.activeElement, field);
    assert.match(text(find(review, statusSelector)), /Nothing was sent\./);
  }

  const exact = '🧭'.repeat(120);
  const provider = find(review, 'input[aria-label="Provider"]');
  await typeInto(provider, exact);
  await clickButton(review, 'Save provider');
  const sent = p.requests.filter((request) =>
    request.method === 'PATCH' && request.url.endsWith('/course-intakes/d1'))[0]!;
  assert.deepEqual(sent.body, { field: 'provider', value: exact });
});

