test('recording a real result keeps the replanning receipt on screen', async (t) => {
  const p = await open(t, home({
    'GET /plan': planTable(),
    'GET /outcome-context': {
      courses: [{ id: 'k1', title: 'Agent Systems' }],
      commitments: [{ id: 'c1', title: 'Marketing analysis', courseId: 'k1' }],
      topics: [{ id: 't1', label: 'Tool boundaries' }],
    },
    'GET /outcomes': { outcomes: [] },
    'POST /outcomes': {
      adaptation: {
        changed: true, before: NEXT_COMMITMENT.primary,
        after: { ...NEXT_COMMITMENT.primary, kind: 'session', title: 'Repair tool boundaries' },
        changedBecause: '“Report grade” changed the next move from “Marketing analysis” to “Repair tool boundaries”.',
      },
    },
  }));
  await clickButton(p.app, 'Plan');
  // Behind Add now, on its own route: the results themselves live in My studies
  // per course, and what stays in the Plan is the recording, because the moment
  // somebody records one is the moment after they ticked the thing off.
  assert.equal(p.app.querySelectorAll('.outcome-capture').length, 0,
    'the result form is still standing in the Plan body');
  await clickButton(p.app, 'Add');
  await clickButton(find(p.app, '.add-routes'), 'Record a result');
  const form = find(p.app, '.outcome-capture');
  await typeInto(find(form, '.title'), 'Report grade');
  await typeInto(find(form, '.score'), '40');
  await typeInto(find(form, '.max'), '100');
  await typeInto(find(form, '.topic'), 't1');
  await clickButton(form, 'Record result');
  assert.match(text(find(form, '.adaptation')), /changed the next move/);
  assert.equal(find(form, '.adaptation').getAttribute('role'), 'status');
  assert.equal(form.getAttribute('aria-busy'), null);
  assert.equal(p.dom.activeElement, button(form, 'See the updated next move'),
    'the result landed but focus remained on the disabled Record result control');
  const sent = p.requests.find((r) => r.method === 'POST' && r.url.endsWith('/outcomes'))!;
  assert.deepEqual((sent.body as Record<string, unknown>).topicIds, ['t1']);
  assert.ok(button(form, 'See the updated next move'));
});

