test('recording a result shows its whole-word limits and sends exact Unicode boundaries whole', async (t) => {
  const p = await open(t, home({
    'GET /plan': planTable(),
    'GET /outcome-context': { courses: [], commitments: [], topics: [] },
    'POST /outcomes': {
      adaptation: {
        changed: false, before: NEXT_EMPTY.primary, after: NEXT_EMPTY.primary,
        changedBecause: 'The result is recorded; the current next move still wins.',
      },
    },
  }));
  await clickButton(p.app, 'Plan');
  await clickButton(p.app, 'Add');
  await clickButton(find(p.app, '.add-routes'), 'Record a result');
  const form = find(p.app, '.outcome-capture');
  assert.match(text(form), /Up to 180 characters\. I save the whole result name\./);
  assert.match(text(form), /Up to 6,000 characters\. I save the whole note\./);
  const title = find(form, '.title');
  const feedback = find(form, '.feedback');
  const receipt = find(form, '.adaptation');
  const postsBefore = paths(p).filter((path) => path === 'POST /outcomes').length;

  await typeInto(title, '🙂'.repeat(181));
  await clickButton(form, 'Record result');
  assert.equal(paths(p).filter((path) => path === 'POST /outcomes').length, postsBefore);
  assert.equal(title.value, '🙂'.repeat(181));
  assert.equal(p.dom.activeElement, title);
  assert.equal(text(receipt),
    'That result name is 181 characters. Keep it to 180 so I can save all of it. Nothing was sent.');

  const exactTitle = '🙂'.repeat(180);
  await typeInto(title, exactTitle);
  await typeInto(feedback, '🟢'.repeat(6_001));
  await clickButton(form, 'Record result');
  assert.equal(paths(p).filter((path) => path === 'POST /outcomes').length, postsBefore);
  assert.equal(feedback.value, '🟢'.repeat(6_001));
  assert.equal(p.dom.activeElement, feedback);
  assert.equal(text(receipt),
    'That result note is 6,001 characters. Keep it to 6,000 so I can save all of it. Nothing was sent.');

  const exactFeedback = '🟢'.repeat(6_000);
  await typeInto(feedback, exactFeedback);
  await clickButton(form, 'Record result');
  const sent = p.requests.filter((request) =>
    request.method === 'POST' && request.url.endsWith('/outcomes'))[0]!;
  assert.equal((sent.body as Record<string, unknown>).title, exactTitle);
  assert.equal((sent.body as Record<string, unknown>).feedback, exactFeedback);
});

test('the room no longer lists recorded results, because My studies does', async (t) => {
  /**
   * One rendering of one fact. A result read in the room where the work lives
   * and a result read in the Plan were the same object drawn twice, which is
   * how two rooms come to disagree about a grade. The correction control went
   * with it — `outcomeRow` is still one function, mounted where the course is.
   */
  const p = await open(t, home({
    'GET /plan': planTable(),
    'GET /outcome-context': { courses: [], commitments: [], topics: [] },
  }));
  await clickButton(p.app, 'Plan');
  assert.equal(p.app.querySelectorAll('.outcome-history').length, 0);
  assert.ok(!paths(p).includes('GET /outcomes'),
    'the Plan still pays for a list it does not draw');
});

// ============================================ the plan room, rebuilt (2026-08-24)


/** A learner-local day, relative to whatever "now" the panel is running in.
 * The calendar buckets against the real clock, so a fixed fixture date would
 * drift out of the three-week window the day after it was written. */
const isoDay = (offset: number): string =>
  localDayKey(Date.now() + offset * 86_400_000);
const dueOn = (offset: number): string => `${isoDay(offset)}T23:59:00.000Z`;

/** The service's order (`orderCommitments`): late, today, soon, later. */
const LANES = {
  commitments: [
    { ...COMMITMENT, id: 'late-1', title: 'Missed thing', state: 'late', dueAt: dueOn(-3) },
    { ...COMMITMENT, id: 'today-1', title: 'Due today', state: 'today', dueAt: dueOn(0) },
    {
      ...COMMITMENT, id: 'soon-1', title: 'This week thing', state: 'soon',
      dueAt: dueOn(3), plannedFor: dueOn(1), courseId: 'k1', estimateMinutes: 45,
    },
    { ...COMMITMENT, id: 'later-1', title: 'Further out', state: 'later', dueAt: dueOn(60) },
    {
      ...COMMITMENT, id: 'done-1', title: 'Finished thing', state: 'done',
      dueAt: dueOn(-5), doneAt: dueOn(-5),
    },
  ],
  points: 30, stars: 0, towardNextStar: 0, recentAwards: [],
};

const PLAN_CONTEXT = {
  courses: [{ id: 'k1', title: 'Agent Systems' }],
  commitments: [{ id: 'soon-1', title: 'This week thing', courseId: 'k1' }],
  topics: [{ id: 't1', label: 'Tool boundaries' }],
};

/** The room, with enough behind it to draw every part of it. */
const planRoom = (over: Table = {}): Table => home({
  'GET /plan': LANES,
  'GET /outcome-context': PLAN_CONTEXT,
  ...over,
});

const openPlan = async (t: TestContext, over: Table = {}): Promise<Panel> => {
  const p = await open(t, planRoom(over));
  await clickButton(p.app, 'Plan');
  return p;
};

const planCardOf = (p: Panel, id: string): El => find(p.app, `.plan-card[data-commitment="${id}"]`);

test('the Plan opens with the tutor, not with a form and not with a score', async (t) => {
  /**
   * The order IS the ruling. The room used to say "0 points", then show a
   * four-field form, and only then say what the learner had agreed to — a
   * data-entry screen wearing a plan's name.
   */
  const p = await openPlan(t, { 'GET /today': { next: NEXT_COMMITMENT } });
  const board = find(p.app, '.room-board');
  const blocks = board.children.map((c) => c.className.split(' ')[0]);
  assert.deepEqual(blocks,
    ['room-head', 'tutor', 'add-sheet-host', 'plan-wall', 'zone'],
    `the room is laid out in a different order: ${blocks.join(', ')}`);
  // Nothing to type into until Add is pressed.
  assert.equal(p.app.querySelectorAll('.add-commitment').length, 0);
  assert.equal(p.app.querySelectorAll('.outcome-capture').length, 0);
  assert.equal(find(p.app, '.add-sheet-host').children.length, 0);

  const add = button(p.app, 'Add');
  assert.equal(add.getAttribute('aria-expanded'), 'false');
  assert.equal(add.getAttribute('aria-controls'), 'plan-add-sheet');
  await click(add);
  assert.equal(add.getAttribute('aria-expanded'), 'true');
  assert.equal(text(add), 'Close');
  // Two routes, and the first one is the form the learner came here to use.
  assert.deepEqual(find(p.app, '.add-routes').querySelectorAll('button').map((b) => text(b)),
    ['Something with a date', 'Record a result']);
  assert.ok(find(p.app, '.add-commitment'), 'Add opened on nothing');
  assert.equal(p.dom.activeElement, find(p.app, '.add-commitment .title'),
    'the Add sheet opened before the first thing the learner can answer');
  // And it closes again, rather than standing open over the room.
  await click(add);
  assert.equal(text(add), 'Add');
  assert.equal(find(p.app, '.add-sheet-host').children.length, 0);
  assert.equal(p.dom.activeElement, add, 'closing the sheet did not return focus to Add');
});

test('an empty Plan is one useful invitation, not four empty reports and a zero', async (t) => {
  const p = await openPlan(t, {
    'GET /plan': { commitments: [], points: 0, stars: 0, towardNextStar: 0, recentAwards: [] },
  });
  const empty = find(p.app, '.plan-first');
  assert.equal(text(find(empty, 'h2')), 'Nothing with a date yet');
  assert.match(text(empty), /assignment, class, or study session/i);
  assert.ok(button(empty, 'Add something with a date'));
  assert.equal(p.app.querySelector('.plan-wall'), null);
  assert.equal(p.app.querySelector('.plan-done'), null);
  assert.equal(p.app.querySelector('.score'), null);
  assert.equal(text(p.app).includes('Nothing is due today'), false);
  assert.equal(text(p.app).includes('Nothing lands in the next week'), false);
  assert.equal(text(p.app).includes('Nothing further out'), false);
  assert.equal(text(p.app).includes('0 points'), false);

  await clickButton(empty, 'Add something with a date');
  assert.equal(text(button(p.app, 'Close')), 'Close');
  assert.equal((empty as unknown as { hidden: boolean }).hidden, true,
    'the empty report stayed behind the open form');
  assert.equal(p.dom.activeElement, find(p.app, '.add-commitment .title'));
});

