test('a tick reconciles Done, score, calendar, tutor and award in one confirmed repaint', async (t) => {
  let completed = false;
  const p = await openPlan(t, {
    'GET /plan': () => completed ? {
      ...LANES,
      commitments: LANES.commitments.map((c) => c.id === 'today-1'
        ? { ...c, state: 'done', doneAt: dueOn(0) }
        : c),
      points: 45,
    } : LANES,
    'GET /today': { next: NEXT_COMMITMENT },
    'POST /commitments/today-1/done': () => {
      completed = true;
      return {
        commitment: { ...COMMITMENT, id: 'today-1', state: 'done', doneAt: dueOn(0) },
        awarded: [{ points: 10, reason: 'closed' }, { points: 5, reason: 'on-time' }],
        points: 45, stars: 0,
      };
    },
  });
  const before = paths(p).filter((r) => r === 'GET /today').length;
  await click(find(planCardOf(p, 'today-1'), '.tick'));

  const moved = planCardOf(p, 'today-1');
  assert.equal(find(p.app, '.plan-lanes').querySelector('[data-commitment="today-1"]'), null,
    'the completed card still appeared unfinished');
  assert.equal(find(p.app, '.plan-done').querySelector('[data-commitment="today-1"]'), moved,
    'the confirmed completion did not move into Done');
  assert.match(text(find(moved, '.earned')), /\+15, on time/,
    'the award disappeared when the card moved');
  assert.equal(text(find(p.app, '.score')), '45 points');
  assert.equal(text(find(p.app, '.plan-calendar')).includes('Due today'), false,
    'the calendar retained an open marker for finished work');
  assert.equal(p.dom.activeElement, moved, 'focus did not follow the changed card into Done');
  const after = paths(p).filter((r) => r === 'GET /today').length;
  assert.ok(after > before, 'the tutor line was not re-read after the tick');
});

test('a slow completion cannot pull the learner back into a Plan they already left', async (t) => {
  const routes = planRoom({
    'POST /commitments/today-1/done': {
      commitment: { ...COMMITMENT, id: 'today-1', doneAt: dueOn(0) },
      awarded: [{ points: 10, reason: 'closed' }], points: 10, stars: 0,
    },
  });
  const p = await openPlan(t, routes);
  const immediate = serve(routes);
  let release!: (response: FakeResponse) => void;
  const delayed = new Promise<FakeResponse>((resolve) => { release = resolve; });
  p.c.fetchHandler = (url, init) => {
    const path = url.startsWith(SERVICE) ? url.slice(SERVICE.length) : url;
    if (`${init?.method ?? 'GET'} ${path}` === 'POST /commitments/today-1/done') return delayed;
    return immediate(url, init);
  };

  const pending = find(planCardOf(p, 'today-1'), '.tick').fireEvent('click');
  await Promise.resolve();
  await clickButton(p.app, 'Insights');
  const planReads = paths(p).filter((path) => path === 'GET /plan').length;
  release(jsonResponse({
    commitment: { ...COMMITMENT, id: 'today-1', doneAt: dueOn(0) },
    awarded: [{ points: 10, reason: 'closed' }], points: 10, stars: 0,
  }));
  await pending;
  await settle();
  assert.equal(p.app.dataset.room, 'model');
  assert.equal(paths(p).filter((path) => path === 'GET /plan').length, planReads,
    'a detached card redrew the room after its slow completion');
});

test('three lanes, late first in Now, and not one of them counts anything', async (t) => {
  const p = await openPlan(t);
  const lanes = find(p.app, '.plan-lanes').querySelectorAll('.lane');
  assert.deepEqual(lanes.map((l) => l.getAttribute('data-lane')), ['now', 'week', 'ahead']);
  assert.deepEqual(lanes.map((l) => text(find(l, 'h2'))), ['Now', 'This week', 'Ahead']);

  const ids = (lane: El): string[] =>
    lane.querySelectorAll('.plan-card').map((c) => c.getAttribute('data-commitment') ?? '');
  // Late and today share the Now lane, and late leads it. The lane is never
  // named after being late, and closing a late card still scores.
  assert.deepEqual(ids(lanes[0]!), ['late-1', 'today-1']);
  assert.deepEqual(ids(lanes[1]!), ['soon-1']);
  assert.deepEqual(ids(lanes[2]!), ['later-1']);
  // Done is not in a lane; it is under them.
  assert.deepEqual(ids(find(p.app, '.plan-done')), ['done-1']);

  // SB-18 and SB-33 on the shape that grows a tally most easily. No heading
  // carries a number and the room never says how far behind anybody is.
  for (const lane of lanes) {
    assert.ok(!/\d/.test(text(find(lane, 'h2'))), text(find(lane, 'h2')));
  }
  const said = text(find(p.app, '.room-board'));
  assert.ok(!/overdue|to clear|remaining|left to|behind/i.test(said), said.slice(0, 200));
  assert.ok(!/\b\d+\s+(?:late|overdue|things|items|tasks)\b/i.test(said), said.slice(0, 200));
});

test('a card says what it is, whose course, when, how long, and what was promised', async (t) => {
  const p = await openPlan(t);
  const one = planCardOf(p, 'soon-1');
  assert.equal(text(find(one, '.label')), 'This week thing');
  // The course label, resolved from the read the room already makes. `/plan`
  // has always carried `courseId` and the room never drew it, so every card
  // was a title with no idea what it belonged to.
  assert.equal(text(find(one, '.course')), 'Agent Systems');
  assert.equal(text(find(one, '.when')), 'due in 3 days');
  assert.equal(text(find(one, '.estimate')), '45 min');
  assert.equal(text(find(one, '.promised')), 'you said tomorrow');
  // A card that knows none of the optional facts says none of them, rather
  // than drawing three empty slots.
  const bare = planCardOf(p, 'later-1');
  assert.equal(text(find(bare, '.course')), '');
  assert.equal(text(find(bare, '.estimate')), '');
  assert.equal(find(bare, '.when').textContent.length > 0, true);
});

