test('the score is at the foot of Done, and Done offers the way back', async (t) => {
  const p = await openPlan(t, { 'POST /commitments/done-1/reopen': { commitment: COMMITMENT } });
  const done = find(p.app, '.plan-done');
  assert.equal(text(find(done, 'h2')), 'Done');
  assert.equal(text(find(done, '.score')), '30 points');
  // SB-74: `POST /commitments/{id}/reopen` was written, tested, and never
  // wired, so somebody who ticked the wrong row had no way back.
  const one = planCardOf(p, 'done-1');
  assert.equal((find(one, '.tick') as unknown as { disabled: boolean }).disabled, true,
    'a done card offers a tick that pays nothing');
  await clickButton(one, 'More');
  await clickButton(one, 'Reopen');
  assert.equal(lastWrite(p)!.url, `${SERVICE}/commitments/done-1/reopen`);
  assert.equal(lastWrite(p)!.method, 'POST');
  assert.equal(p.dom.activeElement, planCardOf(p, 'done-1'),
    'a successful reopen rebuilt Plan without returning to the exact card');
});

