test('“Move to a day” sends the promise and only the promise', async (t) => {
  /**
   * The load-bearing wire assertion. A due date is somebody else's fact and the
   * move gesture must never be able to carry one: `plannedFor` is the learner's
   * own promise, and it is what the kept-promise award is paid against.
   */
  const p = await openPlan(t, { 'PUT /commitments/soon-1': { commitment: COMMITMENT } });
  const one = planCardOf(p, 'soon-1');
  await clickButton(one, 'More');
  await clickButton(one, 'Move to a day');
  const day = isoDay(2);
  find(one, '.move-date .planned').value = day;
  await clickButton(one, 'Move it');
  const sent = lastWrite(p)!;
  assert.equal(sent.url, `${SERVICE}/commitments/soon-1`);
  assert.equal(sent.method, 'PUT');
  assert.deepEqual(sent.body, { plannedFor: day });
});

