test('a recurring date edit asks for scope before it can change remaining dates', async (t) => {
  const recurring = {
    ...COMMITMENT, id: 'series-one-02', title: 'Studio class', state: 'soon',
    dueAt: '2099-09-09T07:00:00.000Z', dueTime: '17:00',
    dueTimeZone: 'Australia/Sydney', recurrence: {
      seriesId: 'series-one', index: 1, total: 6, cadence: 'weekly',
      timeZone: 'Australia/Sydney', requestHash: `sha256:${'a'.repeat(64)}`,
    },
  };
  const p = await openPlan(t, {
    'GET /plan': { ...LANES, commitments: [recurring] },
    'PUT /commitments/series-one-02?scope=remaining': {
      commitment: recurring, commitments: [recurring], changed: 1, preservedCompleted: 0,
    },
  });
  const card = planCardOf(p, recurring.id);
  await clickButton(card, 'More');
  assert.match(text(find(card, '.menu-choices .note')), /Weekly · 2 of 6/);
  await clickButton(card, 'Change the date');
  assert.equal(p.dom.activeElement, button(card, 'Only this date'));
  assert.ok(button(card, 'This and later'));
  assert.equal(card.querySelectorAll('.date-edit').length, 0,
    'choosing Change the date silently assumed a series scope');

  await clickButton(card, 'This and later');
  const date = find(card, '.date-edit .due');
  assert.equal(p.dom.activeElement, date);
  assert.match(text(find(card, '.deadline-zone')), /Completed dates and your planned days stay/);
  await typeInto(date, '2099-09-16');
  await clickButton(card, 'This and later');
  const sent = lastWrite(p)!;
  assert.equal(sent.url, `${SERVICE}/commitments/series-one-02?scope=remaining`);
  assert.deepEqual(sent.body, { dueAt: '2099-09-16', dueTime: '17:00' });
});

