/**
 * THE LINK THAT MAKES A DEADLINE CHANGE WHAT TONIGHT TEACHES.
 *
 * `topicIds` is described in `commitments.ts` as *"the link that makes teaching
 * deadline-aware"* and until 2026-08-24 no surface in the product wrote it: the
 * form posted four fields and the menu offered four actions, none of them this.
 * Every commitment on a live board carried an empty array, so `dueWeight` had
 * nothing to weigh and the biggest piece of work in somebody's week had nowhere
 * to send them but a list.
 */
test('a card can be linked to what it leans on, and the link is written back', async (t) => {
  const p = await openPlan(t, {
    'PUT /commitments/soon-1': {
      commitment: { ...LANES.commitments[2], topicIds: ['t1'] },
    },
    'GET /plan': { ...LANES, commitments: LANES.commitments.map(
      (c) => (c.id === 'soon-1' ? { ...c, topicIds: ['t1'] } : c)) },
  });
  const one = planCardOf(p, 'soon-1');
  await clickButton(one, 'More');
  await clickButton(one, 'Change what it is linked to');
  // The reason to bother is on the sheet, beside the boxes.
  assert.match(text(find(one, '.topic-edit .why')), /teaches those things first/);
  const box = find(one, '.topic-edit input[type=checkbox]');
  assert.equal(p.dom.activeElement, find(one, '.topic-edit .course-pick'),
    'the link editor opened without focus on its first field');
  box.checked = true;
  await clickButton(one, 'Save the links');

  const sent = lastWrite(p)!;
  assert.equal(sent.url, `${SERVICE}/commitments/soon-1`);
  assert.equal(sent.method, 'PUT');
  // Both halves of the same question, and nothing else. A control that could
  // also carry a date would be a second way to move a deadline.
  // The course comes back as it was stored: opening the menu on a linked row
  // shows the link rather than offering to make one that is already there.
  assert.deepEqual(sent.body, { courseId: 'k1', topicIds: ['t1'] });
  // Repainted from the service, so the card shows what was stored.
  assert.match(text(planCardOf(p, 'soon-1')), /Leans on Tool boundaries/);
});

