test('a completed card repairs its study links without reopening or losing completion', async (t) => {
  const doneBefore = LANES.commitments[4]!;
  let updated = false;
  const linked = { ...doneBefore, courseId: 'k1', topicIds: ['t1'] };
  const p = await openPlan(t, {
    'GET /plan': () => ({
      ...LANES,
      commitments: LANES.commitments.map((c) => c.id === 'done-1' && updated ? linked : c),
    }),
    'PUT /commitments/done-1': () => {
      updated = true;
      return { commitment: linked };
    },
  });
  let card = planCardOf(p, 'done-1');
  await clickButton(card, 'More');
  assert.ok(button(card, 'Link it to what you are studying'));
  await clickButton(card, 'Link it to what you are studying');
  find(card, '.topic-edit .course-pick').value = 'k1';
  find(card, '.topic-edit input[type=checkbox]').checked = true;
  await clickButton(card, 'Save the links');

  assert.deepEqual(lastWrite(p)!.body, { courseId: 'k1', topicIds: ['t1'] });
  assert.equal(paths(p).some((path) => path === 'POST /commitments/done-1/reopen'), false);
  card = planCardOf(p, 'done-1');
  assert.equal(find(card, '.tick').getAttribute('aria-label'), 'Done: Finished thing');
  assert.equal(text(find(card, '.course')), 'Agent Systems');
  assert.match(text(find(card, '.leans')), /Tool boundaries/);
  assert.equal(p.dom.activeElement, card);
});

