test('deleting takes two presses and says what survives it', async (t) => {
  const p = await openPlan(t, { 'DELETE /commitments/soon-1': { ok: true } });
  const one = planCardOf(p, 'soon-1');
  await clickButton(one, 'More');
  const before = p.requests.length;
  await clickButton(one, 'Delete');
  assert.equal(p.requests.length, before, 'the first press already sent the delete');
  const confirm = find(one, '.delete-confirm');
  assert.equal(p.dom.activeElement, button(confirm, 'Delete it'),
    'Delete replaced its launcher without entering the confirmation');
  assert.match(text(confirm), /goes for good/);
  // Nothing in the award ledger is rewound by a delete: an award is a record
  // of a moment, and a ledger that can be rewound can be farmed.
  assert.match(text(confirm), /What it earned stays where it is/);
  // And the way out of it.
  await clickButton(one, 'Keep it');
  assert.equal(one.querySelectorAll('.delete-confirm').length, 0);
  assert.equal(p.dom.activeElement, find(one, '[data-menu]'),
    'Keep it closed the confirmation without returning to More');
  assert.equal(p.requests.length, before);

  await clickButton(one, 'More');
  await clickButton(one, 'Delete');
  await clickButton(one, 'Delete it');
  assert.equal(lastWrite(p)!.method, 'DELETE');
  assert.equal(lastWrite(p)!.url, `${SERVICE}/commitments/soon-1`);
});

