test('the calendar draws three weeks, marks today once, and puts the thing in the cell', async (t) => {
  const p = await openPlan(t);
  const cal = find(p.app, '.plan-calendar');
  assert.deepEqual(cal.querySelectorAll('.cal-week').map((w) => w.getAttribute('data-week')),
    ['0', '1', '2']);
  assert.deepEqual(cal.querySelectorAll('.cal-head').map((h) => text(h)),
    ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']);
  assert.deepEqual(cal.querySelectorAll('.cal-key span').map((item) => text(item)),
    ['Deadline', 'Your planned day']);
  const today = cal.querySelectorAll('.cal-day').filter((d) => d.getAttribute('data-today'));
  assert.equal(today.length, 1);
  assert.equal(today[0]!.getAttribute('data-day'), isoDay(0));

  // A deadline is drawn solid; the day they said they would do it is drawn
  // lighter, in its own cell. Two different facts, two different marks.
  const dueCell = find(cal, `.cal-day[data-day="${isoDay(3)}"]`);
  const due = find(dueCell, '.cal-item[data-kind="due"]');
  assert.equal(text(due), 'This week thing');
  assert.equal(due.getAttribute('aria-label'), 'Deadline: This week thing');
  assert.match(dueCell.getAttribute('aria-label') ?? '',
    new RegExp(`^Plan something for ${isoDay(3)}\\. Deadline: This week thing$`));
  const plannedCell = find(cal, `.cal-day[data-day="${isoDay(1)}"]`);
  const planned = find(plannedCell, '.cal-item[data-kind="planned"]');
  assert.equal(text(planned), 'This week thing');
  assert.equal(planned.getAttribute('aria-label'), 'Your planned day: This week thing');
  assert.match(plannedCell.getAttribute('aria-label') ?? '',
    new RegExp(`^Plan something for ${isoDay(1)}\\. Your planned day: This week thing$`));
});

test('no cell in the calendar carries a number but its own date', async (t) => {
  /**
   * Open Question 7's bound, ruled and accepted. A calendar is the surface that
   * most naturally grows a count in every square, and a count in a square is
   * the backlog SB-18 has kept out of every other room.
   */
  const p = await openPlan(t, {
    'GET /plan': {
      ...LANES,
      commitments: ['a', 'b', 'c', 'd'].map((id) => ({
        ...COMMITMENT, id, title: `Thing ${id.toUpperCase()}`, state: 'soon', dueAt: dueOn(2),
      })),
    },
  });
  const cell = find(p.app, `.cal-day[data-day="${isoDay(2)}"]`);
  assert.equal(cell.querySelectorAll('.cal-item').length, 4, 'four things, drawn as four things');
  // The only number on the cell is the date at the top of it.
  assert.equal(text(find(cell, '.cal-date')), isoDay(2).slice(8));
  const items = cell.querySelectorAll('.cal-item').map((i) => text(i));
  assert.deepEqual(items, ['Thing A', 'Thing B', 'Thing C', 'Thing D']);
  for (const said of items) assert.ok(!/^\s*\d+\s*$/.test(said), said);
  // And the room says nothing about a session being scheduled, because one is
  // built when it is ready rather than at an hour this product chose.
  assert.equal(text(find(p.app, '.cal-note')), 'Lessons appear in Learn when they are ready.');
});

test('a card dropped on a day moves the promise, never the deadline', async (t) => {
  const p = await openPlan(t, { 'PUT /commitments/soon-1': { commitment: COMMITMENT } });
  const one = planCardOf(p, 'soon-1');
  // The card offers itself to the browser's drag, which is what makes the day
  // cell a target at all.
  assert.equal(one.getAttribute('draggable'), 'true');
  const cell = find(p.app, `.cal-day[data-day="${isoDay(4)}"]`);
  // A browser will not fire `drop` unless `dragover` was prevented.
  await cell.fireEvent('dragover');
  assert.ok(cell.classList.contains('over'), 'the cell never says "yes, here"');
  await cell.fireEvent('drop', { dataTransfer: { getData: () => 'soon-1' } });
  await settle();
  assert.ok(!cell.classList.contains('over'));
  const sent = lastWrite(p)!;
  assert.equal(sent.url, `${SERVICE}/commitments/soon-1`);
  assert.equal(sent.method, 'PUT');
  assert.deepEqual(sent.body, { plannedFor: isoDay(4) });
});

