// ------------------------------------------------------------- the geometry

test('the plan room is two columns of tokens, and warns in the one warning colour', () => {
  const css = readFileSync(fileURLToPath(new URL('../../panel.css', import.meta.url)), 'utf8');
  const room = css.slice(css.indexOf('.tutor {'), css.indexOf('.outcome-capture {'));
  assert.ok(room.length > 1_500, 'the plan block moved and this assertion stopped reading it');

  // A literal colour anywhere in this room is a second alarm colour by another
  // name, which is how `--warn` stops meaning "look at this".
  assert.deepEqual([...room.matchAll(/#[0-9a-fA-F]{3,8}\b|\b(?:red|crimson|tomato)\b/g)].map((m) => m[0]), [],
    'a literal colour in the Plan room');
  /**
   * And amber marks two things, both of which are one card's dates having gone
   * wrong, and both of which are a colour and nothing else — no fill, no edge,
   * no badge. A late card's due line was the first. The second is the sentence
   * added on 2026-08-24 for the case the card used to print in silence: due
   * today, promised for tomorrow, no lane change and nothing on screen saying
   * the two dates disagree.
   *
   * The list is exhaustive on purpose. A third entry here is the moment to ask
   * whether `--warn` still means "look at this" or has become the Plan's
   * decoration.
   */
  const warns = [...room.matchAll(/([^{}]+)\{[^}]*var\(--warn\)[^}]*\}/g)]
    .map((m) => m[1]!.trim().split('\n').pop()!.trim());
  assert.deepEqual(warns, ['.plan-card .clash', '.plan-card[data-state="late"] .when'],
    'something else in the Plan is shouting in the alarm colour');

  // The wall: lanes and the calendar side by side, one column before the cells
  // stop being legible — well above the 560px panel breakpoint, because the
  // layout fails at a narrow window rather than at a phone.
  const wall = /^\.plan-wall \{[^}]*\}/m.exec(room);
  assert.ok(wall, 'the wall lost its own rule and inherits the room flow');
  assert.match(wall[0], /display: grid/);
  // Proportional, not a fixed rail: `.room-board` is `--shell` wide in every
  // room, so a fixed lane column is a fifth of the wall at 1680px and half of
  // it at 900px.
  assert.match(wall[0], /grid-template-columns: minmax\(0, 1fr\) minmax\(0, 1\.4fr\)/);
  assert.match(room, /@media \(max-width: 860px\) \{\s*\.plan-wall \{ grid-template-columns: minmax\(0, 1fr\)/,
    'a narrow window still lays 21 day cells out beside three lanes');

  // The tutor is a compact priority strip. It may carry a quiet wash and one
  // edge, but remains a single line with no heading or hero-sized treatment.
  const tutor = /^\.tutor \{[^}]*\}/m.exec(room);
  assert.ok(tutor, 'the tutor line has no rule of its own');
  assert.match(tutor[0], /border-left: 4px solid var\(--mark-1\)/,
    'the next move has no visual authority in the planner');
  assert.match(tutor[0], /background: var\(--soft\)/,
    'the next move fell back into detached text');
  assert.doesNotMatch(tutor[0], /border-radius|min-height|box-shadow/,
    'the compact priority strip became a second hero card');
  assert.match(room, /\.tutor\.hushed \{ display: none; \}/,
    'a tutor with nothing to say still spends the room gap');

  // The room's own rhythm still comes from `.room-board`, so every new block
  // in the Plan has to be in the list that clears the historical margins.
  assert.match(css, /data-room="plan"\] \.room-board > :where\(\s*\.tutor, \.add-sheet-host, \.add-sheet, \.plan-wall, \.plan-done/,
    'a Plan block was added without being handed the shared room rhythm');
  assert.match(room, /\.plan-lanes \{[^}]*gap: 18px/,
    'the lanes stack at a rhythm the room does not use');
});

