  await clickButton(row, 'Correct result');
  const edit = find(row, '.correction-fields');
  await typeInto(find(edit, '.corrected-result'), 'Draft I changed my mind about');
  const writesBefore = p.requests.filter((request) => request.method === 'POST').length;

  await clickButton(edit, 'Cancel');

  assert.equal(p.requests.filter((request) => request.method === 'POST').length, writesBefore);
