test('direct study forms publish one whole Unicode naming contract and keep overflow unsent', async (t) => {
  const coursePanel = await open(t, studies({ 'POST /courses': { course: { id: 'k2' } } }));
  await clickButton(coursePanel.app, 'My studies');
  await clickButton(coursePanel.app, 'Add');
  await clickButton(find(coursePanel.app, '.add-routes'), 'Course');
  const course = find(coursePanel.app, '.add-course');
  assert.match(text(course), /Up to 160 characters\. I save the whole course name\./);
  assert.match(text(course), /Up to 120 characters\. I save the whole provider name\./);
  const courseTitle = find(course, '.title');
  const provider = find(course, '.provider');
  await typeInto(courseTitle, '🙂'.repeat(161));
  await clickButton(course, 'Add course');
  assert.equal(paths(coursePanel).filter((path) => path === 'POST /courses').length, 0);
  assert.equal(coursePanel.dom.activeElement, courseTitle);
  assert.match(text(find(course, '[role="status"]')), /Nothing was sent\./);
  await typeInto(courseTitle, '🧭'.repeat(160));
  await typeInto(provider, '🙂'.repeat(121));
  await clickButton(course, 'Add course');
  assert.equal(paths(coursePanel).filter((path) => path === 'POST /courses').length, 0);
  assert.equal(coursePanel.dom.activeElement, provider);
  await typeInto(provider, '🏫'.repeat(120));
  await clickButton(course, 'Add course');
  assert.deepEqual(lastWrite(coursePanel)?.body, {
    title: '🧭'.repeat(160), provider: '🏫'.repeat(120),
  });

  const materialPanel = await open(t, studies({
    'POST /courses/k1/material': { course: { id: 'k1' } },
  }));
  await clickButton(materialPanel.app, 'My studies');
  await clickButton(materialPanel.app, 'Add');
  await clickButton(find(materialPanel.app, '.add-routes'), 'Material');
  const material = find(materialPanel.app, '.add-material');
  assert.match(text(material), /Up to 180 characters\. I save the whole material title\./);
  const materialTitle = find(material, '.title');
  await typeInto(materialTitle, '🙂'.repeat(181));
  await clickButton(material, 'Add material');
  assert.equal(paths(materialPanel).filter((path) => path === 'POST /courses/k1/material').length, 0);
  assert.equal(materialPanel.dom.activeElement, materialTitle);
  assert.match(text(find(material, '[role="status"]')), /Nothing was sent\./);
  await typeInto(materialTitle, '📚'.repeat(180));
  await clickButton(material, 'Add material');
  assert.equal((lastWrite(materialPanel)?.body as Record<string, unknown>).title, '📚'.repeat(180));

  const planPanel = await open(t, studies({
    'POST /commitments': { commitment: { id: 'c2' } },
  }));
  await clickButton(planPanel.app, 'My studies');
  await clickButton(planPanel.app, 'Add');
  await clickButton(find(planPanel.app, '.add-routes'), 'Something with a date');
  const dated = find(planPanel.app, '.add-commitment');
  assert.match(text(dated), /Up to 180 characters\. I save the whole name\./);
  const assignmentTitle = find(dated, '.title');
  await typeInto(assignmentTitle, '🙂'.repeat(181));
  await typeInto(find(dated, '.due'), '2026-09-04');
  await clickButton(dated, 'Add it');
  assert.equal(paths(planPanel).filter((path) => path === 'POST /commitments').length, 0);
  assert.equal(planPanel.dom.activeElement, assignmentTitle);
  assert.match(text(find(dated, '[role="status"]')), /Nothing was sent\./);
  await typeInto(assignmentTitle, '📝'.repeat(180));
  await clickButton(dated, 'Add it');
  assert.equal((lastWrite(planPanel)?.body as Record<string, unknown>).title, '📝'.repeat(180));

  const editPanel = await open(t, studies({ 'PUT /courses/k1': { course: STUDY_COURSE } }));
  await clickButton(editPanel.app, 'My studies');
  const record = find(editPanel.app, '.course[data-course="k1"]');
  await clickButton(record, 'Course options');
  await clickButton(record, 'Edit course');
  const edit = find(record, '.course-edit');
  assert.match(text(edit), /Up to 160 characters\. I save the whole course name\./);
  assert.match(text(edit), /Up to 120 characters\. I save the whole provider name\./);
  const editProvider = find(edit, '.provider');
  await typeInto(editProvider, '🙂'.repeat(121));
  await clickButton(edit, 'Save course');
  assert.equal(paths(editPanel).filter((path) => path === 'PUT /courses/k1').length, 0);
  assert.equal(editPanel.dom.activeElement, editProvider);
  assert.match(text(find(edit, '[role="status"]')), /Nothing was sent\./);
});

