  const row = find(p.app, '.material[data-material="m1"]');
  const writesBefore = p.requests.filter((request) => request.method !== 'GET').length;

  await clickButton(row, 'Material options');
  await clickButton(row, 'Edit material');
  await clickButton(find(row, '.material-edit'), 'Cancel');
  assert.equal(p.requests.filter((request) => request.method !== 'GET').length, writesBefore);
  assert.equal(p.dom.activeElement, button(row, 'Edit material'));

  await clickButton(row, 'Edit material');
  const form = find(row, '.material-edit');
  await typeInto(find(form, '.title'), 'Caching fundamentals');
