/**
 * The defect this room was rebuilt on top of.
 *
 * `POST /commitments` has accepted `courseId` since the day it was written and
 * this form never sent it, so every deadline typed in by hand was stored
 * belonging to no course — invisible in the room where the work lives, and out
 * of reach of the deadline weighting for the topics that course teaches.
 */
test('a dated thing added here belongs to the course it was added under', async (t) => {
  const p = await open(t, studies({ 'POST /commitments': { commitment: { id: 'c2' } } }));
  await clickButton(p.app, 'My studies');
  await clickButton(p.app, 'Add');
  await clickButton(find(p.app, '.add-routes'), 'Something with a date');

  const form = find(p.app, '.add-commitment');
  await typeInto(find(form, '.title'), 'Story draft');
  await typeInto(find(form, '.due'), '2026-09-04');
  find(form, 'select.course-pick').value = 'k1';
  await clickButton(form, 'Add it');

  const sent = lastWrite(p)!;
  assert.equal(sent.url, `${SERVICE}/commitments`);
  assert.deepEqual(sent.body, {
    title: 'Story draft', kind: 'assignment', dueAt: '2026-09-04',
    plannedFor: null, courseId: 'k1', topicIds: [],
  });
});

