// ------------------------------------------- the row, after it is put right

const GRADE = {
  id: 'o1', kind: 'grade', title: 'Story draft', courseId: 'k1', commitmentId: null,
  topicIds: [], score: 62, maxScore: 100, summary: '', feedback: 'Turn arrives late.',
  criteria: [], source: null, recordedAt: '2026-08-21T10:00:00.000Z',
};

/**
 * What `POST /outcomes/:id/correct` answers.
 *
 * The replacement it wrote, under a NEW id: the service invalidates the old
 * record's signals, marks it deleted and stores a fresh one. That is why the id
 * matters as much as the number — a row that keeps aiming at the id it was
 * drawn with is aiming at a record the first correction deleted.
 */
const corrected = (id: string, over: Record<string, unknown>): unknown => ({
  outcome: { ...GRADE, id, ...over },
  adaptation: {
    changed: false, before: NEXT_EMPTY.primary, after: NEXT_EMPTY.primary,
    changedBecause: 'The correction is recorded; the current next move still wins.',
  },
});

const correctTo = async (row: El, score: string): Promise<void> => {
  await clickButton(row, 'Correct result');
  const fields = find(row, '.correction-fields');
  await typeInto(find(fields, '.corrected-score'), score);
  await clickButton(fields, 'Save correction');
};

test('a corrected result reads back corrected, and can be corrected again', async (t) => {
  /**
   * The pinsSince card's lie, in the Results row. The Correct control removed
   * itself before the request and never came back; on success only the
   * replanning receipt was appended, and the score the row displays was never
   * touched. So a learner who corrected 62 to 72 was shown a receipt saying the
   * correction was recorded directly under the number 62 — and had no way to
   * try again short of leaving the room and coming back.
   */
  const p = await open(t, studies({
    'GET /outcomes': { outcomes: [GRADE], history: [] },
    'POST /outcomes/o1/correct': corrected('o1b', { score: 72 }),
    'POST /outcomes/o1b/correct': corrected('o1c', { score: 74 }),
  }));
  await clickButton(p.app, 'My studies');
  const row = find(p.app, '.course .results .outcome-row');
  assert.match(text(find(row, '.result')), /62 \/ 100/);

  await clickButton(row, 'Correct result');
  assert.equal(p.dom.activeElement, find(row, '.corrected-result'),
    'Correct removed itself without moving focus into the correction');
  await typeInto(find(row, '.corrected-score'), '72');
  await clickButton(find(row, '.correction-fields'), 'Save correction');
  assert.equal(text(find(row, '.result')), '72 / 100', 'the row is still reading back the superseded score');
  assert.match(text(find(row, '.receipt-line')), /correction is recorded/);
  assert.equal(find(row, '.receipt-line').getAttribute('role'), 'status');
  assert.equal(text(button(row, 'See the current next move')), 'See the current next move');
  assert.equal(p.dom.activeElement, button(row, 'See the current next move'),
    'Save correction disappeared without moving focus to the useful next action');
  assert.equal((lastBody(p) as { score: string }).score, '72');

  // And again, at the record the service actually wrote — not the one this row
  // was drawn from, which the first correction superseded.
  await correctTo(row, '74');
  assert.equal(paths(p)[paths(p).length - 1], 'POST /outcomes/o1b/correct');
  assert.equal(text(find(row, '.result')), '74 / 100');
  assert.ok(button(row, 'Correct result'), 'the way to put a result right went with the correction');
});

test('SB-119: a changed correction puts the updated next move beside the edit and rereads it', async (t) => {
  const updated = {
    ...NEXT_COMMITMENT,
    primary: { ...NEXT_COMMITMENT.primary, title: 'Repair tool boundaries' },
  };
  const p = await open(t, studies({
    'GET /outcomes': { outcomes: [GRADE], history: [] },
    'GET /today': { next: updated },
    'POST /outcomes/o1/correct': {
      outcome: { ...GRADE, id: 'o1b', score: 72 },
      adaptation: {
        changed: true,
        before: NEXT_COMMITMENT.primary,
        after: updated.primary,
        changedBecause: 'The correction changed the next move to “Repair tool boundaries”.',
      },
    },
  }));
  await clickButton(p.app, 'My studies');
  const row = find(p.app, '.course .results .outcome-row');
  await correctTo(row, '72');

  assert.match(text(find(row, '.receipt-line')), /changed the next move/);
  const see = button(row, 'See the updated next move');
  assert.equal(p.dom.activeElement, see);
  const readsBefore = paths(p).filter((path) => path === 'GET /today').length;
  await clickButton(row, 'See the updated next move');
  assert.equal(p.app.dataset.room, 'today');
  assert.match(text(p.app), /Repair tool boundaries/);
  assert.equal(paths(p).filter((path) => path === 'GET /today').length, readsBefore + 1,
    'the correction response was rendered as current instead of rereading Today');
});

