  assert.equal(body.kind, 'self-assessment');
  assert.equal(body.score, null);
  assert.equal(body.maxScore, null);
  assert.equal(body.feedback, 'I can now explain the failure case.');
  assert.equal(body.commitmentId, 'c1');
  assert.deepEqual(body.topicIds, ['t1']);
  assert.deepEqual(body.source,
    { sourceId: 'source-1', quote: 'Retry handling is unclear.' });
