test('correcting a result keeps overflow editable and sends exact Unicode boundaries whole', async (t) => {
  const p = await open(t, studies({
    'GET /outcomes': { outcomes: [GRADE], history: [] },
    'POST /outcomes/o1/correct': corrected('o1b', { title: 'Corrected', feedback: 'Whole' }),
  }));
  await clickButton(p.app, 'My studies');
  const row = find(p.app, '.course .results .outcome-row');
  await clickButton(row, 'Correct result');
  const edit = find(row, '.correction-fields');
  assert.match(text(edit), /Up to 180 characters\. I save the whole result name\./);
  assert.match(text(edit), /Up to 6,000 characters\. I save the whole note\./);
  const title = find(edit, '.corrected-result');
  const feedback = find(edit, '.corrected-feedback');
  const note = find(edit, '.note');
  const postsBefore = paths(p).filter((path) => path === 'POST /outcomes/o1/correct').length;

  await typeInto(title, '🧭'.repeat(181));
  await clickButton(edit, 'Save correction');
  assert.equal(paths(p).filter((path) => path === 'POST /outcomes/o1/correct').length, postsBefore);
  assert.equal(title.value, '🧭'.repeat(181));
  assert.equal(p.dom.activeElement, title);
  assert.equal(text(note),
    'That result name is 181 characters. Keep it to 180 so I can save all of it. Nothing was sent.');

  const exactTitle = '🧭'.repeat(180);
  await typeInto(title, exactTitle);
  await typeInto(feedback, '📝'.repeat(6_001));
  await clickButton(edit, 'Save correction');
  assert.equal(paths(p).filter((path) => path === 'POST /outcomes/o1/correct').length, postsBefore);
  assert.equal(feedback.value, '📝'.repeat(6_001));
  assert.equal(p.dom.activeElement, feedback);
  assert.equal(text(note),
    'That result note is 6,001 characters. Keep it to 6,000 so I can save all of it. Nothing was sent.');

  const exactFeedback = '📝'.repeat(6_000);
  await typeInto(feedback, exactFeedback);
  await clickButton(edit, 'Save correction');
  const sent = p.requests.filter((request) =>
    request.method === 'POST' && request.url.endsWith('/outcomes/o1/correct'))[0]!;
  assert.equal((sent.body as Record<string, unknown>).title, exactTitle);
  assert.equal((sent.body as Record<string, unknown>).feedback, exactFeedback);
});

