const QUICK = (over: Record<string, unknown> = {}) => ({
  availableMinutes: 1,
  primary: {
    id: 'take:p1:1', kind: 'quick-take', targetId: 'p1',
    title: 'A quick take on TLS',
    detail: 'A source-backed explanation shaped to your 1-minute window.',
    minutes: 1, destination: 'take', cta: 'Learn this now',
    reasons: [{ code: 'ready', text: 'You are new to this one, and nothing has been asked about it yet.' }],
    rank: 300, othersReady: 1, ...over,
  },
  alternatives: [],
});
/** What the ranker answers once the first pick has been refused. */
const QUICK_NEXT = QUICK({
  id: 'take:p2:1', targetId: 'p2', title: 'A quick take on Certificate chains',
  othersReady: 0,
});

const hero = (over: Table = {}): Table => home({
  'GET /session': { session: session({ sections: [] }), card: card({ minutes: 0, registers: [] }) },
  'GET /today': { next: QUICK() },
  ...over,
});

test('SB-286: the one minute hero carries its own two controls, and neither takes the accent', async (t) => {
  const p = await open(t, hero());
  const card = find(p.app, '.next-action');
  assert.equal(text(find(card, 'h1')), 'A quick take on TLS');
  // The same instrument as a lineup row: a glyph, and the whole sentence on it
  // twice, so it is reachable by a pointer that rests and by a screen reader.
  for (const label of ['Not now', 'Show me another']) {
    const control = iconControl(card, label);
    assert.equal(control.getAttribute('title'), label);
    assert.equal(text(control), '', `${label} still renders as text`);
    assert.ok(control.className.includes('link'), `${label} is not quiet`);
  }
  assert.equal(p.app.querySelectorAll('button.primary').length, 1);
  assert.equal(text(find(p.app, 'button.primary')), 'Learn this now');
  // Drawing them costs nothing: the ranker already said what was behind the pick.
  assert.deepEqual(paths(p), FIRST_PAINT);
});

test('SB-286: not now on the hero writes the close’s own mark and moves to the next pick', async (t) => {
  const p = await open(t, hero({
    'POST /pins/p1/quick-take/verdict': { ok: true, verdict: 'not-now', backAfterDays: 7, changed: false },
  }));
  // The topic is held from here on, so the ranker's next answer is a different
  // one. That is the service's job; this is the panel asking it again.
  p.route(hero({
    'GET /today': { next: QUICK_NEXT },
    'POST /pins/p1/quick-take/verdict': { ok: true, verdict: 'not-now', backAfterDays: 7 },
  }));
  await pressIcon(find(p.app, '.next-action'), 'Not now');

  const wrote = p.requests.find((r) => r.url.endsWith('/pins/p1/quick-take/verdict'));
  assert.ok(wrote, `no deferral was sent: ${paths(p).join(' | ')}`);
  assert.deepEqual(wrote.body, { verdict: 'not-now' },
    'the hero invented a vocabulary of its own instead of using the close’s');
  // The receipt is the close's own sentence, carrying the service's own window.
  assert.equal(text(find(p.app, '.build-note')), quickTakeAnsweredLine('not-now', 7));
  // And no dead end: the next candidate is on screen with its own controls.
  assert.equal(text(find(p.app, '.next-action h1')), 'A quick take on Certificate chains');
  assert.ok(iconControl(find(p.app, '.next-action'), 'Not now'));
});

