test('starting an alternative still records the pass over, once, on the press', async (t) => {
  // The forward-only ledger survives the rework unchanged. It is written when
  // somebody takes the offer, not when the rail draws it.
  const p = await open(t, railed({
    'GET /today': {
      next: {
        ...NEXT_SESSION,
        alternatives: [{
          id: 'burst:t1', kind: 'burst', targetId: null, title: 'Take a five-minute recall burst',
          detail: 'One quick check.', minutes: 5, destination: 'burst', cta: 'Start burst',
          reasons: [{ code: 'review-due', text: 'One topic is due for recall.' }], rank: 500,
        }],
      },
    },
    'POST /model/slipping/passed-over': { ok: true },
  }));
  assert.equal(paths(p).filter((path) => path.includes('passed-over')).length, 0,
    'reading a list is not choosing off it');
  const alts = find(p.app, '[data-rail=instead]').querySelectorAll('.alt');
  await click(alts[alts.length - 1]!);
  const wrote = p.requests.filter((r) => r.url.includes('passed-over'));
  assert.equal(wrote.length, 1, 'the ledger took a second copy of one decision');
  assert.deepEqual(wrote[0]?.body, {
    offeredId: 'session:sess-1', chosenId: 'burst:t1', offeredReason: 'ready',
  });
  assert.equal(p.app.dataset.room, 'burst');
});

