test('an empty rail says what will fill it, rather than being an empty column', async (t) => {

  const p = await open(t, railed({
    'GET /session': {
      session: session({ sections: [section({ topicId: 't1' })] }), card: card(), upcoming: [],
    },
    'GET /today': { next: { ...NEXT_SESSION, alternatives: [] } },
  }));
  assert.equal(p.app.querySelectorAll('.room-rail').length, 1, 'the column is permanent');
  assert.equal(find(p.app, '.room-columns').getAttribute('data-rail'), 'empty');
  // It names where the content comes from rather than apologising, and it does
  // not draw the headings of blocks that have nothing in them.
  const empty = find(p.app, '[data-rail-empty]');
  assert.equal(text(find(empty, '.alt-label')), 'Nothing else to start yet');
  // What fills it is what the rail now holds: other things to start, with how
  // long each takes. It stopped promising a list of future topics the day that
  // list moved to the board.
  assert.match(text(empty), /with how long each one takes/);
  assert.match(text(empty), /Pin something and the next run builds them\./);
  assert.equal(p.app.querySelectorAll('[data-rail=upcoming]').length, 0);
  assert.equal(p.app.querySelectorAll('[data-rail=ready]').length, 0);
  // And the one thing to do is still the one thing to do.
  assert.equal(find(p.app, '.room-main').querySelectorAll('.next-action').length, 1);
});

