test('the notice is quiet furniture, not a warning and not a control', async (t) => {
  const p = await open(t, everyRoom());
  const notice = find(p.app, '.page-notice');
  assert.equal(notice.tagName, 'P');
  assert.equal(notice.querySelectorAll('button').length, 0, 'nothing to press, nothing to dismiss');
  // A dismissible notice is a notice that is dismissed once and never seen
  // again, which is the same as not having one.
  assert.ok(!/dismiss|got it|understood|ok/i.test(text(notice)));

  const css = readFileSync(fileURLToPath(new URL('../../panel.css', import.meta.url)), 'utf8');
  // Anchored, so the `#app > .page-notice` ordering rule is not mistaken for
  // the rule that decides how the line reads.
  const rule = /^\.page-notice \{[^}]*\}/m.exec(css);
  assert.ok(rule, 'the notice has no rule and inherits body copy');
  assert.match(rule[0], /color:\s*var\(--muted\)/);
  assert.ok(!/--warn/.test(rule[0]),
    'the notice took the colour this product warns in, for a standing condition');
  // `#app` is a flex column purely so the notice can be ordered last on the two
  // screens that put their content straight into it.
  assert.match(css, /#app > \.page-notice \{[^}]*order:\s*1/);
});

