test('Current and Lineup preserve the exact open lesson while its lineup is managed', async (t) => {
  const p = await open(t, lined({ 'PUT /prefs': prefs() }));
  const chips = find(p.app, '.time-choice');
  await clickButton(p.app, 'Start');
  const lesson = find(p.app, '.section');
  const question = find(p.app, '.ask-box');
  await typeInto(question, 'How does the certificate fit?');
  assert.equal(p.app.querySelectorAll('.time-choice').length, 0);
  assert.deepEqual(find(p.app, '.learn-mode-toggle').querySelectorAll('button').map((b) => text(b)),
    ['Current', 'Lineup']);

  await clickButton(find(p.app, '.learn-mode-toggle'), 'Lineup');
  assert.equal(find(p.app, '.time-choice'), chips, 'Lineup rebuilt its session-length control');
  assert.deepEqual([...chips.querySelectorAll('button')].map((b) => text(b)),
    ['1 min', '3 min', '5 min']);
  assert.equal(find(p.app, '.room-board').getAttribute('data-learning'), 'no');

  await clickButton(chips, '1 min');
  assert.deepEqual(lastBody(p), { availableMinutes: 1 });
  assert.equal(button(chips, '1 min').getAttribute('aria-pressed'), 'true');
  assert.equal(button(chips, '3 min').getAttribute('aria-pressed'), 'false');

  await clickButton(find(p.app, '.learn-mode-toggle'), 'Current');
  assert.equal(find(p.app, '.section'), lesson, 'Current rebuilt the lesson it had put aside');
  assert.equal(find(p.app, '.ask-box'), question);
  assert.equal(question.value, 'How does the certificate fit?');
  assert.equal(find(p.app, '.room-board').getAttribute('data-learning'), 'yes');
});

