test('pressing Start replaces two columns of content and rebuilds nothing else', async (t) => {
  const p = await open(t, lined());
  const masthead = find(p.app, '.masthead');
  const columns = find(p.app, '.room-columns');
  const main = find(p.app, '.room-main');
  const rail = find(p.app, '.room-rail');
  const modeToggle = find(p.app, '.learn-mode-toggle');
  const notice = find(p.app, '.page-notice');
  const board = find(p.app, '.room-board');

  const cardNode = find(p.app, '.next-action');

  await clickButton(p.app, 'Start');


  assert.equal(find(p.app, '.next-action'), cardNode, 'the bordered card was rebuilt');
  assert.equal(find(p.app, '.next-action .section').parentElement, cardNode,
    'the lesson is not inside the card');
  assert.equal(find(p.app, '.masthead'), masthead, 'the bar was rebuilt');
  assert.equal(find(p.app, '.room-columns'), columns, 'the grid was rebuilt');
  assert.equal(find(p.app, '.room-main'), main, 'the main column was rebuilt');
  assert.equal(find(p.app, '.room-rail'), rail, 'the rail was rebuilt');
  assert.equal(find(p.app, '.learn-mode-toggle'), modeToggle, 'the Current/Lineup toggle was rebuilt');
  assert.equal(p.app.querySelectorAll('.time-choice').length, 0,
    'session length stayed above the active lesson');
  assert.equal(find(p.app, '.page-notice'), notice, 'the footer notice was rebuilt');
  assert.equal(find(p.app, '.room-board'), board, 'the room canvas was rebuilt');
  // And the thing that DID change is the content of those two columns.
  assert.equal(main.querySelectorAll('.section').length, 1);
  assert.equal(p.app.querySelectorAll('.lineup').length, 0);
  assert.equal(find(p.app, '.gemini-routes').parentElement?.parentElement, rail);
  assert.equal(main.querySelectorAll('.gemini-routes').length, 0);
});

