// ============================ §6f-i: prompt forwarding, and a readable page


/** A lesson with every fact the prompt is built from: a course, a piece of
 *  dated work, the Composer's summary, a question, and something after it. */
const tutored = (over: Table = {}): Table => home({
  'GET /session': {
    session: session({
      sections: [
        section({
          topicId: 't1', heading: 'How TLS gets its keys', depth: 'building',
          estimatedMinutes: 6,
          summary: 'What the handshake agrees on before anything is encrypted',
          subject: { courseId: 'c1', title: 'Networks and Security' },
          serves: { commitmentId: 'w1', title: 'Marketing analysis' },
          // The Marker's rubric rides on the same object as the prompt. It is
          // here in the fixture precisely so a test can watch it not travel.
          question: {
            prompt: 'Say it back in your own words.',
            expectedPoints: ['ephemeral keys', 'nothing long lived is reused'],
          },
        }),
        section({ topicId: 't2', heading: 'Why forward secrecy', depth: 'from-nothing', question: null }),
      ],
    }),
    card: card(),
  },
  'GET /sessions/sess-1/sections/t1/sources': {
    sources: [
      { id: 'p1:origin', origin: 'user-pin', title: 'ADK — Sessions', url: 'https://example.com/doc', at: null },
      { id: 'p2:ref-1', origin: 'agent-sourced', title: 'Ack deadlines', url: 'https://docs.example.com/acks', at: null },
    ],
    unresolved: 0,
  },
  ...over,
});

const AI_MODE = 'https://www.google.com/search';

const ROUTES_HEADING = 'Take this lesson to Gemini';
const TUTOR_BUTTON = 'New tab';
const BESIDE_BUTTON = 'Pop out';
const PANEL_BUTTON = 'Side panel';

/** The seven lines this fixture's first lesson forwards. Written out rather
 *  than imported, so a copy change has to be made twice on purpose. */
const PROMPT_LINES = [
  'I’m studying Networks and Security, working towards Marketing analysis.',
  'I’m opening a lesson on How TLS gets its keys: What the handshake agrees on before anything is encrypted.',
  'I have the basics; build on them, don’t re-explain.',
  'I want to connect it to what I know and use it on a case I haven’t seen yet.',
  'After this one I’m on to Why forward secrecy.',
  'The lesson has this practice question: “Say it back in your own words.” '
    + 'I haven’t answered it. Ask me that question directly as your first response, then teach from my answer.',
  'The lesson itself is below. I don’t need a welcome, a menu, or a reminder to reply. Start teaching me now.',
];

const routes = (p: Panel): El => find(p.app, '.room-rail .gemini-routes');

const forward = async (p: Panel): Promise<void> => { await clickButton(routes(p), TUTOR_BUTTON); };
const forwardBeside = async (p: Panel): Promise<void> => { await clickButton(routes(p), BESIDE_BUTTON); };
const forwardToPanel = async (p: Panel): Promise<void> => { await clickButton(routes(p), PANEL_BUTTON); };

/** Whatever the last press handed the browser, whichever surface it used. */
const openedUrl = (p: Panel): string => {
  const url = p.c.windowsCreated.at(-1)?.url
    ?? p.dom.openedTabs.filter((tab) => !tab.closed).at(-1)?.url
    ?? p.c.tabsCreated.at(-1)?.url;
  assert.ok(url, 'nothing was opened');
  return url;
};

/** The prompt inside it. */
const forwarded = (p: Panel): string =>
  new URL(openedUrl(p)).searchParams.get('q') ?? '';

// ------------------------------------------------------- the interactive-agent reachability contract: the rail

test('§6f-i: the group is in the rail, not under the lesson', async (t) => {

  const p = await open(t, tutored());
  await startSession(p);
  const rail = find(p.app, '.room-rail');
  assert.equal(rail.querySelectorAll('.gemini-routes').length, 1);
  assert.equal(find(p.app, '.room-main').querySelectorAll('.gemini-routes').length, 0,
    'the group is still in the main column');
  const stack = find(p.app, '.rail-stack');
  const kinds = stack.children.map((c) => c.className.split(/\s+/)[0]);
  assert.ok(kinds.indexOf('gemini-routes') >= 0);
  assert.equal(p.app.querySelectorAll('.notebook').length, 0,
    'the Notebook block is a destination in the group now, not a block beneath it');
});

test('§6f-i: they are real buttons, in the hand-off’s own idiom', async (t) => {

  const p = await open(t, tutored());
  await startSession(p);
  const row = find(p.app, '.gemini-routes .routes');
  assert.deepEqual(row.querySelectorAll('button').map((b) => text(b)),
    [TUTOR_BUTTON, BESIDE_BUTTON, PANEL_BUTTON, NOTEBOOK_BUTTON]);
  for (const b of row.querySelectorAll('button')) {
    assert.ok(!b.className.includes('link'),
      `"${text(b)}" is drawn as a text link, matching the accepted destination treatment`);
    // The label is a place; the sentence is on the control. Same string in
    // both, or it is two controls depending on how you meet it.
    const title = b.getAttribute('title');
    assert.ok(title && title.length > 20, `"${text(b)}" carries no sentence`);
    assert.equal(b.getAttribute('aria-label'), title);
  }
  assert.equal(text(find(p.app, '.gemini-routes .alt-label')), ROUTES_HEADING);
});

test('§6f-i: the four doors use the board’s own visual grammar', () => {
  /**
   * Joint QC, 2026-08-30: the correct words and real button semantics were
   * still arriving as generic product UI — a small-caps caption, rounded
   * bordered controls, and a 3+1 wrap that made Notebook look incidental.
   * Whiteboard already owns marker colours and BlackBoard remaps the same
   * tokens to chalk, so this block must use that house language directly.
   */
  const css = readFileSync(fileURLToPath(new URL('../../panel.css', import.meta.url)), 'utf8');

  const heading = /\.gemini-routes > \.alt-label \{([^}]*)\}/.exec(css);
  assert.ok(heading, 'the hand-off heading still falls back to the generic caption register');
  assert.match(heading[1]!, /font-family:\s*var\(--hand\)/,
    'the hand-off heading is not written in the board hand');
  assert.match(heading[1]!, /text-transform:\s*none/,
    'the heading is still being turned into generic small-caps UI');

  const grid = /\.gemini-routes \.routes \{([^}]*)\}/.exec(css);
  assert.ok(grid, 'the four destinations have no layout of their own');
  assert.match(grid[1]!, /display:\s*grid/);
  assert.match(grid[1]!, /grid-template-columns:\s*repeat\(2,\s*minmax\(0,\s*1fr\)\)/,
    'the four equal destinations are not held in a deliberate 2×2 block');

  const door = /\.gemini-routes \.routes button \{([^}]*)\}/.exec(css);
  assert.ok(door, 'the destination buttons have no shared board treatment');
  assert.match(door[1]!, /font-family:\s*var\(--hand\)/);
  assert.match(door[1]!, /background:\s*transparent/);
  assert.match(door[1]!, /border-radius:\s*0/,
    'the destinations still inherit the generic rounded-button silhouette');

  const marks: Array<[string, string]> = [
    ['\\[data-tutor="tab"\\]', '--mark-1'],
    ['\\[data-tutor="beside"\\]', '--mark-2'],
    ['\\[data-tutor="copy"\\]', '--mark-3'],
    ['\\[data-handoff\\]', '--mark-4'],
  ];
  for (const [selector, token] of marks) {
    assert.match(css, new RegExp(`\\.gemini-routes \\.routes ${selector} \\{[^}]*border-left-color:\\s*var\\(${token}\\)`),
      `${selector} is not carried by its Whiteboard marker / BlackBoard chalk token`);
  }
});

test('§6f-i: the group is a heading, four labelled presses, and nothing else', async (t) => {
  /**
   * **THE FINDING THIS TEST IS THE ANSWER TO.** Read cold on 2026-08-29, this
   * was the one region of the product that did not explain itself: a heading
   * saying *Learn with Gemini* with no object in it, three place names of which
   * one was secretly a clipboard write, and a paragraph underneath doing the
   * explaining that the controls were failing to do. The affordance-first interface contract's law is that
   * the affordances ARE the instruction, and interface copy restating what the
   * interface shows is a defect.
   *
   * So: the object is in the heading, the act is in every label, and the
   * paragraph is gone. Held here rather than only in `tutor-brief.test.ts`
   * because the failure that matters is on the screen: a seam paragraph can
   * come back as markup in `panel.ts` without any constant changing.
   */
  const p = await open(t, tutored());
  await startSession(p);
  const group = routes(p);
  assert.equal(group.querySelectorAll('.seam').length, 0,
    'the explainer paragraph is back: the labels and their titles do this job now');
  // Nothing on the block before a press except the heading, the four presses
  // and an outcome region with nothing in it yet. Asserted as the block's own
  // children, because that is where a re-added paragraph would show up.
  assert.deepEqual(group.children.map((c) => c.className.split(/\s+/)[0]),
    ['alt-label', 'routes', 'routes-out']);
  assert.equal(text(find(group, '.alt-label')), ROUTES_HEADING);
  assert.deepEqual(find(group, '.routes').querySelectorAll('button').map((b) => text(b)),
    [TUTOR_BUTTON, BESIDE_BUTTON, PANEL_BUTTON, NOTEBOOK_BUTTON]);
  assert.equal(text(find(group, '.routes-out')), '');
  // The heading names what travels, so no button has to repeat it. The two
  // doors that do not open anything where the learner is looking say what they
  // do on the control itself, which is where the labels stopped saying it.
  assert.match(ROUTES_HEADING, /this lesson/);
  assert.match(button(group, PANEL_BUTTON).getAttribute('title') ?? '', /^Copies\b/);
  assert.match(button(group, NOTEBOOK_BUTTON).getAttribute('title') ?? '', /I take this lesson/);
});

test('§6f-i: a press that only copies still says so out loud, the moment it happens', async (t) => {
  /**
   * The Side panel door opens nothing. Without a live region the whole of its
   * feedback is a sentence appearing somewhere off the eye's path, which is a
   * control that looks broken to anybody using a screen reader and ambiguous to
   * everybody else. The panel already has this pattern everywhere a press has
   * an outcome; this block was the exception.
   */
  const p = await open(t, tutored());
  await startSession(p);
  const out = find(p.app, '.gemini-routes .routes-out');
  assert.equal(out.getAttribute('role'), 'status');
  assert.equal(out.getAttribute('aria-live'), 'polite');
  // Empty before the press, so the region announces the outcome rather than
  // re-announcing itself on every lesson.
  assert.equal(text(out), '');
  await forwardToPanel(p);
  assert.match(text(out), /^Forwarding prompt has been copied to your clipboard\./);
});

