test('§6f-i: a lesson already read carries no group, and the hand-off leaves with it', async (t) => {
  const p = await open(t, tutored({
    'GET /session': {
      session: session({
        sections: [
          section({ topicId: 't1', heading: 'How TLS gets its keys', completed: true }),
          section({ topicId: 't2', heading: 'Why forward secrecy', question: null }),
        ],
      }),
      card: card(),
    },
  }));
  await startSession(p);
  await clickButton(find(p.app, '.room-rail'), 'How TLS gets its keys');
  assert.equal(text(find(p.app, '.section .lesson-area')), 'How TLS gets its keys');
  assert.equal(p.app.querySelectorAll('.gemini-routes').length, 0);
  /**
   * And the Notebook hand-off goes with it, which is a change of scope and a
   * deliberate one. It was session-scoped and survived a finished lesson; it is
   * the fourth destination in this group now, and the group is about carrying
   * an unfinished lesson onward. The row says *take this lesson to*, so a row
   * drawn where there is no lesson to take would be four controls making a
   * promise the screen cannot keep.
   */
  assert.equal(p.app.querySelectorAll('[data-handoff]').length, 0);
});

