// ----------------------------------------- the first-person payload contract: the payload, first person

test('§6f-i: drawing it costs nothing, and neither does pressing it', async (t) => {

  const p = await open(t, tutored());
  await startSession(p);
  assert.deepEqual(paths(p), FIRST_PAINT);
  await forward(p);
  await forwardBeside(p);
  await forwardToPanel(p);
  /**
   * Three presses, three rows, and nothing between the press and the tab.
   *
   * The rule is about what the LEARNER waits for. The prompt is still computed
   * from the session already in hand, the tab still opens without a round trip,
   * and the row is written afterwards and never awaited: the External record is
   * fire and forget, so a press costs the learner exactly what it always did.
   */
  assert.deepEqual(paths(p), [...FIRST_PAINT, ...Array(3).fill('POST /external')],
    'a press asked the service for something before it opened anything');
});

test('§6f-i: one press opens a new tab at AI Mode carrying the whole prompt', async (t) => {
  const p = await open(t, tutored());
  await startSession(p);
  await forward(p);

  assert.equal(p.dom.openedTabs.filter((tab) => !tab.closed).length, 1);
  const url = new URL(p.dom.openedTabs.find((tab) => !tab.closed)!.url);
  assert.deepEqual(p.c.tabsCreated, [],
    'the service-hosted Gemini route still used chrome.tabs');
  assert.equal(`${url.origin}${url.pathname}`, AI_MODE);
  // Without `udm=50` this is a search box and the prompt is a query nobody
  // answers. The chat's own `?q=` was checked the same evening and ignores it.
  assert.equal(url.searchParams.get('udm'), '50');

  const q = forwarded(p);
  assert.deepEqual(q.split('\n\n')[0]!.split('\n'), PROMPT_LINES);
  assert.match(q, /\n\nHere’s the lesson Virgil opened:\nThe handshake picks a key\.$/);
});

test('§6f-i AUDIENCE LAW: the prompt goes out as the learner speaking', async (t) => {

  const p = await open(t, tutored());
  await startSession(p);
  await forward(p);
  const q = forwarded(p);

  assert.match(q, /^I’m studying /, 'it opens with the learner, because that is who is talking');
  assert.ok(!/for your tutor/i.test(q), 'the heading that named an audience is still in the payload');
  for (const third of ['They are studying', 'your student', 'the learner', 'They have', 'their own attempt']) {
    assert.ok(!q.includes(third), `the payload speaks about the learner in the third person: "${third}"`);
  }
  assert.match(q, /Ask me that question directly as your first response, then teach from my answer\./);
  assert.match(q, /I don’t need a welcome, a menu, or a reminder to reply\. Start teaching me now\./);
});

