test('§6f-i: the copied line belongs to the Side panel door and to no other', async (t) => {
  /**
   * It is a ruled exception to §6f-i's copy laws — three instructions in a row,
   * on a screen whose rule is that the interface teaches itself — and it earns
   * that because no page can open the browser's side panel, so the step that
   * completes this route happens somewhere Virgil cannot reach or confirm.
   */
  const p = await open(t, tutored());
  await startSession(p);

  await forward(p);
  assert.equal(text(find(p.app, '.gemini-routes .forwarded')),
    'Opened a new tab with this lesson in it.');
  await forwardBeside(p);
  assert.equal(text(find(p.app, '.gemini-routes .forwarded')),
    'Opened a window beside this page with this lesson in it.');
  const said = text(routes(p));
  assert.ok(!said.includes('clipboard'), 'a door that opened something claimed a copy');
  assert.ok(!said.includes('hit enter'));

  await forwardToPanel(p);
  assert.match(text(find(p.app, '.gemini-routes .forwarded')), /^Forwarding prompt has been copied/);
  // One line, replaced. Three outcomes stacked would be a log of what the
  // learner has already acted on.
  assert.equal(p.app.querySelectorAll('.gemini-routes .forwarded').length, 1);
});

test('§6f-i: each failure names its own surface, and loses nothing', async (t) => {
  for (const [opts, expected] of [
    [{ tabsFail: true }, /couldn’t open the tab/],
    [{ windowsFail: true }, /couldn’t open the window/],
    [{ clipboardFails: true }, /couldn’t copy it/],
  ] as const) {
    const p = await open(t, tutored(), true, {}, opts);
    await startSession(p);
    if ('tabsFail' in opts) await forward(p);
    else if ('windowsFail' in opts) await forwardBeside(p);
    else await forwardToPanel(p);
    const said = text(find(p.app, '.gemini-routes .routes-out'));
    assert.match(said, expected);
    assert.match(said, /Nothing was lost/);
  }
});

