test('§6f-i: forwarding writes a row about the handoff and no evidence about anybody', async (t) => {
  /**
   * The ledger law §5d's hand-off is held to, and the sharp reason is still the
   * one that matters: a block that quietly recorded *asked a tutor about this*
   * as evidence would be minting a signal out of a gesture whose meaning nobody
   * has established.
   *
   * What each press writes now is one External row: the label, where it went,
   * and which lesson it was. That is a record of a button being pressed, and it
   * makes no claim about comfort, completion or ability. The claim comes later
   * and only if the learner makes one, on the face, in their own press.
   */
  const p = await open(t, tutored());
  await startSession(p);
  const before = p.requests.length;
  await forward(p);
  await forwardBeside(p);
  await forwardToPanel(p);
  const caused = p.requests.slice(before);
  assert.deepEqual(caused.map((r) => `${r.method} ${r.url.slice(SERVICE.length)}`),
    ['POST /external', 'POST /external', 'POST /external']);
  for (const r of caused) {
    assert.doesNotMatch(r.url, /signal|comfort|progression|award/, `a press reached ${r.url}`);
    assert.ok(!('mark' in (r.body as Record<string, unknown>)),
      'a send answered the question the learner has not been asked yet');
  }
});

/**
 * THE ASSISTANT-LEGIBILITY GUARD, NARROWED TO WHAT IS ACTUALLY ON THE PAGE.
 *
 * The layer-2 rot guard. It used to cover the on-page brief as well; that block
 * is gone, so the guard covers what remains and what still matters: **the
 * lesson's teaching content is real, visible DOM text, and the sources behind
 * it are reachable and followable.**
 *
 * That is still the whole mechanism for the panel route. Once a learner points
 * their browser's assistant at this page, what it can do depends entirely on
 * what is legibly on it — and a lesson body moved behind a canvas, or a source
 * list turned into decoration, would pass every other test in this file.
 *
 * Two halves, because there are two ways to lose it: the tree (no hiding
 * attribute, class or inline style) and the stylesheet (no rule that hides any
 * of it from outside the markup).
 */
const HIDING_STYLE = /display\s*:\s*none|visibility\s*:\s*hidden|opacity\s*:\s*0(?!\.)|font-size\s*:\s*0|clip\s*:|clip-path\s*:|text-indent\s*:\s*-|height\s*:\s*0|width\s*:\s*0|left\s*:\s*-\d{3}|top\s*:\s*-\d{3}/;
const HIDING_CLASS = /\b(sr-only|visually-hidden|screen-?reader|offscreen|off-screen|hidden)\b/;

const everyNode = (root: El): El[] => [root, ...root.children.flatMap(everyNode)];

test('§6f-i guard: the lesson is visible DOM text, hidden by nothing', async (t) => {
  const p = await open(t, tutored());
  await startSession(p);
  // SB-44's own control, which is where the source links live on this screen.
  await clickButton(find(p.app, '.section'), '2 sources · why am I seeing this?');

  const lesson = find(p.app, '.section');
  // The lesson and the teaching are two columns since 2026-08-29, and the page
  // an assistant reads is both of them.
  const said = `${text(lesson)} ${text(find(p.app, '[data-rail="teaching"]'))}`;

  // 1. The teaching content is really in the text of the page.
  assert.match(said, /How TLS gets its keys/, 'the heading');
  assert.match(said, /The handshake picks a key\./, 'the lesson body');
  assert.match(said, /Say it back in your own words\./, 'the practice question');

  // 2. The sources are real, followable, visible links rather than decoration.
  const links = find(p.app, '.sources-out').querySelectorAll('a');
  assert.equal(links.length, 2);
  for (const a of links) {
    assert.match(String(a.getAttribute('href')), /^https?:\/\//);
    assert.ok(text(a).length > 0, 'a link with no text is a link nothing can read');
    assert.ok(said.includes(text(a)), 'and its name is in the page text');
  }

  // 3. Nothing on any of it is hidden by attribute, class or inline style.
  //    The rail's control group is walked too: a control nobody can see is not
  //    a control, and it is now the only route the page offers.
  for (const root of [lesson, routes(p)]) {
    for (const node of everyNode(root)) {
      const where = `${node.tagName}.${node.className || '(no class)'}`;
      assert.equal(node.getAttribute('aria-hidden'), null, `${where} is aria-hidden`);
      assert.equal(node.getAttribute('hidden'), null, `${where} carries the hidden attribute`);
      assert.ok(!HIDING_CLASS.test(node.className), `${where} carries a hiding class`);
      for (const [prop, value] of Object.entries(node.style)) {
        assert.ok(!HIDING_STYLE.test(`${prop}:${value}`), `${where} is hidden inline by ${prop}: ${value}`);
      }
    }
  }
});

test('§6f-i guard: no rule in the stylesheet hides the lesson or the routes', () => {
  /**
   * The half the DOM cannot see. A single `display: none` in a media query
   * would leave every assertion above passing and the block invisible — the
   * shape of failure this layer dies of, since nobody would be looking at a
   * narrow window on the day it landed.
   */
  const css = readFileSync(fileURLToPath(new URL('../../panel.css', import.meta.url)), 'utf8')
    .replace(/\/\*[\s\S]*?\*\//g, '');
  const guarded = /\.gemini-routes|\.section\s+\.body|\.sources-out/;
  const offenders: string[] = [];
  for (const m of css.matchAll(/([^{}]+)\{([^{}]*)\}/g)) {
    const selector = (m[1] ?? '').replace(/\s+/g, ' ').trim();
    if (!guarded.test(selector)) continue;
    // `:empty` rules are the exception that proves it: hiding a node with
    // nothing in it is not hiding anything.
    if (/:empty/.test(selector)) continue;
    if (HIDING_STYLE.test(m[2] ?? '')) offenders.push(`${selector} { ${(m[2] ?? '').trim()} }`);
  }
  assert.deepEqual(offenders, [],
    'the free-tutor layer works only while the page stays readable, and a page stays '
    + 'readable only while something is checking');

  assert.match(css, /\.gemini-routes \.routes \{[^}]*display: grid/,
    'the group has no styling at all — it should be quiet, not absent');
});

