test('Pins draws Virgil with the same destination-card grammar as Gemini', () => {
  const css = readFileSync(fileURLToPath(new URL('../../panel.css', import.meta.url)), 'utf8');
  assert.match(css, /\.pins-item\[data-collapsible="true"\] \.pins-excerpt[^}]*-webkit-line-clamp:\s*4/s,
    'Pins did not limit excerpts only when it also offered Show more');
  assert.doesNotMatch(css, /^\.pins-excerpt\s*\{[^}]*-webkit-line-clamp/ms,
    'all pin excerpts were clipped, including ones without an expansion control');
  const virgil = /\.pins-actions button \{([^}]*)\}/.exec(css);
  const gemini = /\.gemini-routes \.routes button \{([^}]*)\}/.exec(css);
  assert.ok(virgil && gemini);
  for (const rule of [
    /min-height:\s*44px/, /border-left:\s*3px\s+solid/, /border-radius:\s*0/,
    /background:\s*transparent/, /font-family:\s*var\(--hand\)/, /text-align:\s*left/,
  ]) {
    assert.match(virgil[1]!, rule, `Virgil lost destination treatment ${rule}`);
    assert.match(gemini[1]!, rule, `the comparison destination lost treatment ${rule}`);
  }
});

