test('switching faces swaps in place and rebuilds nothing', async (t) => {
  /**
   * The same machinery the lesson uses, one level out. The card is re-attached
   * rather than rebuilt, so the bordered block with the accent line survives a
   * trip to the board and back.
   */
  const p = await open(t, boarded());
  const masthead = find(p.app, '.masthead');
  const columns = find(p.app, '.room-columns');
  const main = find(p.app, '.room-main');
  const chips = find(p.app, '.time-choice');
  const modeToggle = find(p.app, '.learn-mode-toggle');
  const toggle = find(p.app, '.face-toggle');
  const notice = find(p.app, '.page-notice');
  const cardNode = find(p.app, '.next-action');

  await toBoardFace(p);
  assert.ok(p.app.querySelector('.board'), 'the board face did not draw');
  assert.equal(p.app.dataset.room, 'today', 'a face is not a room');
  assert.equal(find(p.app, '.masthead'), masthead);
  assert.equal(find(p.app, '.room-columns'), columns);
  assert.equal(find(p.app, '.room-main'), main);
  assert.equal(p.app.querySelectorAll('.time-choice').length, 0);
  assert.equal(find(p.app, '.learn-mode-toggle'), modeToggle);
  assert.equal(find(p.app, '.face-toggle'), toggle);
  assert.equal(find(p.app, '.page-notice'), notice);
  assert.equal(p.app.querySelectorAll('.next-action').length, 0, 'the card is off the page');

  await clickButton(toggle, 'Up next');
  assert.equal(find(p.app, '.next-action'), cardNode, 'the card was rebuilt on the way back');
  assert.equal(find(p.app, '.masthead'), masthead);
  assert.equal(p.app.querySelectorAll('.board').length, 0);
  assert.equal(p.app.querySelectorAll('.lineup-item').length, 3);
  assert.equal(find(p.app, '.time-choice'), chips);
});

test('the first Board visit keeps its named wait until the whole face can paint', async (t) => {
  const p = await open(t, boarded());
  let release!: (response: FakeResponse) => void;
  const pending = new Promise<FakeResponse>((resolve) => { release = resolve; });
  const base = serve(boarded());
  p.c.fetchHandler = (url, init) => new URL(url).pathname === '/flagged'
    ? pending
    : base(url, init);

  await button(find(p.app, '.face-toggle'), 'Board').fireEvent('click');
  await settle();
  assert.equal(text(find(p.app, '.board-face .thinking')), LOADING_HOME,
    'the Board face became a blank canvas while its secondary reads were still running');
  release(jsonResponse({ rows: [], more: 0 }));
  await settle(12);
  assert.ok(p.app.querySelector('.board'));
  assert.equal(p.app.querySelectorAll('.board-face .thinking').length, 0);
});

