test('the board face is built once a visit, so toggling costs nothing after the first press', async (t) => {
  /**
   * The face is kept and re-attached rather than redrawn. That is only honest
   * while the board it shows is still the board that is there, which is why
   * anything that changes it goes through the redraw rather than hoping the
   * next toggle notices.
  */
  const p = await open(t, boarded());
  await toBoardFace(p);
  assert.equal(find(p.app, '.board-face').getAttribute('data-guide-target'), 'grow-surface');
  assert.ok(find(p.app, '[data-guide-section="topic"]'));
  const search = find(p.app, '.search');
  await typeInto(search, 'tls');
  const after = paths(p).length;
  const toggle = find(p.app, '.face-toggle');
  await clickButton(toggle, 'Up next');
  assert.equal(p.app.querySelectorAll('.search').length, 0,
    'Board search filtered a Learn face it does not own');
  await clickButton(toggle, 'Board');
  assert.deepEqual(paths(p).slice(after), [], 'toggling re-read the board');
  assert.ok(p.app.querySelector('.board'), 'and the face that was kept is still drawn');
  assert.equal(find(p.app, '.search'), search, 'the cached Board lost and rebuilt its search');
  assert.equal((find(p.app, '.search') as unknown as { value: string }).value, 'tls',
    'returning to the cached Board discarded the learner\'s query');
});

