test('the framed canvas is the page constant, and the board is painted on it', () => {

  const css = readFileSync(fileURLToPath(new URL('../../panel.css', import.meta.url)), 'utf8');
  const hosted = /\.room-board \.board \{[^}]*\}/.exec(css);
  assert.ok(hosted, 'a hosted board still brings its own frame');
  assert.match(hosted[0], /border:\s*none/);
  assert.match(hosted[0], /background:\s*none/);
  assert.match(hosted[0], /padding:\s*0/);
  // And nothing strips the canvas itself any more: one geometry, both faces.
  assert.doesNotMatch(css, /\.room-board\[data-learn-face="board"\]\s*\{/,
    'the canvas is still being stood down on one of its own faces');

  // The board's content takes the canvas, which is what it had as a room.
  assert.match(css, /\.room-columns\[data-face="board"\] \{[^}]*grid-template-columns:\s*minmax\(0, 1fr\)/);
  assert.match(css, /\.room-columns\[data-face="board"\] \.room-rail \{[^}]*display:\s*none/);
});

test('the toggle is two words in chalk, in the canvas corner', () => {

  const css = readFileSync(fileURLToPath(new URL('../../panel.css', import.meta.url)), 'utf8');
  const box = /^\.face-toggle \{[^}]*\}/m.exec(css);
  assert.ok(box, 'the toggle lost its rule');
  assert.match(box[0], /position:\s*absolute/, 'it is in the corner, not a row across the page');
  assert.match(box[0], /top:\s*\d+px/);
  assert.match(box[0], /right:\s*\d+px/);
  // Positioned against the canvas, which is the thing it sits in the corner of.
  assert.match(css, /^\.room-board \{[^}]*position:\s*relative/m);

  const face = /\.face-toggle button\.face \{[^}]*\}/.exec(css);
  assert.ok(face);
  assert.match(face[0], /font-family:\s*var\(--hand\)/, 'it is not written on the board');
  assert.match(face[0], /color:\s*var\(--muted\)/, 'it is not in board ink');
  // The board tokens are redeclared on the canvas, so both themes come free.
  assert.match(css, /\.board,\s*\n\.room-board \{[^}]*--muted:\s*var\(--board-muted\)/);

  const pressed = /\.face-toggle button\.face\[aria-pressed="true"\] \{[^}]*\}/.exec(css);
  assert.ok(pressed, 'the toggle has no chosen state');
  assert.match(pressed[0], /border-bottom-color/, 'the chalk rule under the chosen face is gone');
  assert.ok(!/var\(--accent\)/.test(pressed[0]), 'the toggle took the accent');

  const phone = /@media \(max-width: 520px\) \{\s*\/\* The face chooser[\s\S]*?\.face-toggle \{([^}]*)\}/.exec(css);
  assert.ok(phone, 'the phone-width face chooser lost its collision repair');
  assert.match(phone[1]!, /position:\s*static/,
    'the phone-width chooser can overlap controls that follow it');
  assert.match(phone[1]!, /display:\s*flex/,
    'the phone-width chooser still participates in an inline line box');
  assert.match(phone[1]!, /width:\s*100%/,
    'the phone-width chooser does not own a row');
});

