  assert.deepEqual(kept.map((r) => `${r.method} ${r.url.slice(SERVICE.length)}`), ['POST /model']);
  assert.deepEqual(kept[0]!.body,
    { text: 'The worked example was the thing that made it land.' });
  assert.equal(text(find(row, '.more-said')), 'Kept. It is in your insights now.');

  const before = p.requests.length;
  await clickButton(find(row, '.marks'), 'Easy');
  assert.deepEqual(p.requests.slice(before)[0]!.body, {
    mark: 'easy',
    methods: ['hands-on'],
    note: 'The worked example was the thing that made it land.',
    availableMinutes: 5,
  });
