test('a Pending lesson that finishes off-face is kept and opens without a second run', async (t) => {
  const pending = {
    topicId: 't3', label: 'Old thing', register: 'building', why: 'due another pass',
    heldBack: false, pinId: 'p-old', quickTakeMinutes: 1,
  };
  const routes: Table = {
    'GET /session': {
      session: session({ sections: [section({ topicId: 't1' })] }), card: card(),
      upcoming: [pending],
    },
    'POST /pins/p-old/quick-take?minutes=1': {
      outcome: 'ready', body: 'A checked explanation from the saved source.',
      label: 'Old thing', register: 'building', topicId: 't3',
      pinned: {
        text: 'The saved source.', kind: 'selection', pageTitle: 'Old source',
        url: 'https://example.test/old', note: null,
      },
    },
  };
  const p = await openBoard(t, routes);
  const immediate = p.c.fetchHandler;
  let release!: (response: FakeResponse) => void;
  const delayed = new Promise<FakeResponse>((resolve) => { release = resolve; });
  p.c.fetchHandler = (url, init) => {
    const path = url.startsWith(SERVICE) ? url.slice(SERVICE.length) : url;
    if (`${init?.method ?? 'GET'} ${path}` === 'POST /pins/p-old/quick-take?minutes=1') return delayed;
    return immediate(url, init);
  };

  await button(boardCardActions(p, 'Old thing'), 'Run then learn').fireEvent('click');
  await new Promise<void>((resolve) => { setTimeout(resolve, 0); });
  await clickButton(find(p.app, '.face-toggle'), 'External');
  release(jsonResponse(routes['POST /pins/p-old/quick-take?minutes=1']));
  await settle();

  await clickButton(find(p.app, '.face-toggle'), 'Board');
  assert.equal(text(find(boardCardFor(p, 'Old thing'), '.run-status')), 'Ready to open.');
  assert.equal(button(boardCardActions(p, 'Old thing'), 'Run then learn').disabled, false);
  const runCount = paths(p).filter((path) => path === 'POST /pins/p-old/quick-take?minutes=1').length;
  await clickButton(boardCardActions(p, 'Old thing'), 'Run then learn');
  assert.equal(paths(p).filter((path) => path === 'POST /pins/p-old/quick-take?minutes=1').length,
    runCount, 'opening the finished lesson paid for a second run');
  assert.equal(find(p.app, '.room-columns').getAttribute('data-face'), 'learn');
  assert.match(text(find(p.app, '.foreground-lesson .body')), /checked explanation/i);
});

